class EffectOrderButton : public QToolButton {
  QPoint pressPoint;
  static constexpr const char *mime = "application/x-wavy-flo-effect-order";
public:
  std::function<QByteArray()> payload;
  EffectOrderButton() {
    setFocusPolicy(Qt::StrongFocus);
  }

  void startDrag() {
    if (!payload) return;
    auto data = payload();
    if (data.isEmpty()) return;
    setDown(false);
    QDrag drag(this);
    auto *m = new QMimeData;
    m->setData(mime, data);
    drag.setMimeData(m);

    const int badgeW = std::clamp(fontMetrics().horizontalAdvance(text()) + 28, 100, 260);
    const int badgeH = 24;
    QPixmap pixmap(badgeW, badgeH);
    pixmap.fill(Qt::transparent);
    {
      QPainter p(&pixmap);
      p.setRenderHint(QPainter::Antialiasing);
      p.setRenderHint(QPainter::TextAntialiasing);
      p.setBrush(QColor(24, 32, 45, 235));
      p.setPen(QPen(QColor("#2D8CFF"), 1.5));
      p.drawRoundedRect(pixmap.rect().adjusted(1, 1, -1, -1), 3, 3);
      p.setFont(font());
      p.setPen(QColor("#FFFFFF"));
      p.drawText(pixmap.rect().adjusted(8, 0, -8, 0), Qt::AlignLeft | Qt::AlignVCenter | Qt::TextSingleLine, text());
    }
    drag.setPixmap(pixmap);
    drag.setHotSpot(QPoint(16, badgeH / 2));
    drag.exec(Qt::MoveAction);
  }

protected:
  void mousePressEvent(QMouseEvent *event) override {
    pressPoint = event->position().toPoint();
    QToolButton::mousePressEvent(event);
  }
  void mouseMoveEvent(QMouseEvent *event) override {
    if ((event->buttons() & Qt::LeftButton) &&
        (event->position().toPoint() - pressPoint).manhattanLength() >= QApplication::startDragDistance()) {
      startDrag();
      return;
    }
    QToolButton::mouseMoveEvent(event);
  }
  void paintEvent(QPaintEvent *) override {
    QPainter p(this);
    p.setRenderHint(QPainter::TextAntialiasing);
    QStyleOptionToolButton opt;
    initStyleOption(&opt);
    p.setFont(opt.font);

    QColor textColor = opt.palette.buttonText().color();
    if (textColor.alpha() == 0 || textColor == Qt::black) {
      textColor = isChecked() ? ui_theme::ink("#FFFFFF") : ui_theme::ink("#D2D6E0");
    }
    if (underMouse() || isDown()) {
      textColor = ui_theme::ink("#FFFFFF");
    }
    p.setPen(textColor);

    QRect textRect = rect().adjusted(4, 0, -4, 0);
    p.drawText(textRect, Qt::AlignLeft | Qt::AlignVCenter | Qt::TextSingleLine, text());
  }
};

class EffectHeaderWidget : public QWidget {
  int dropLine = 0; // -1 for top, 1 for bottom, 0 for none
  static constexpr const char *mime = "application/x-wavy-flo-effect-order";
public:
  std::function<bool(const QByteArray &)> accepts;
  std::function<void(const QByteArray &, bool)> moveEffect;

  EffectHeaderWidget(QWidget *parent = nullptr) : QWidget(parent) {
    setAcceptDrops(true);
    setAttribute(Qt::WA_Hover);
  }

protected:
  void dragEnterEvent(QDragEnterEvent *event) override {
    if (accepts && accepts(event->mimeData()->data(mime))) {
      event->acceptProposedAction();
    }
  }
  void dragMoveEvent(QDragMoveEvent *event) override {
    if (accepts && accepts(event->mimeData()->data(mime))) {
      dropLine = event->position().y() < height() / 2.0 ? -1 : 1;
      update();
      event->acceptProposedAction();
    }
  }
  void dragLeaveEvent(QDragLeaveEvent *event) override {
    dropLine = 0;
    update();
    event->accept();
  }
  void dropEvent(QDropEvent *event) override {
    const int line = dropLine;
    dropLine = 0;
    update();
    const auto data = event->mimeData()->data(mime);
    if (accepts && accepts(data) && moveEffect) {
      moveEffect(data, line >= 0);
      event->acceptProposedAction();
    }
  }
  void paintEvent(QPaintEvent *event) override {
    QWidget::paintEvent(event);
    if (dropLine != 0) {
      QPainter p(this);
      p.setRenderHint(QPainter::Antialiasing);
      const int y = dropLine < 0 ? 0 : height() - 3;
      p.fillRect(QRect(0, y, width(), 3), ui_theme::ink("#2D8CFF"));
      p.setBrush(ui_theme::ink("#2D8CFF"));
      p.setPen(Qt::NoPen);
      p.drawEllipse(QPointF(4, y + 1.5), 3, 3);
    }
  }
};

class EffectDropZone : public QWidget {
  int dropLine = 0;
  static constexpr const char *mime = "application/x-wavy-flo-effect-order";
public:
  std::function<bool(const QByteArray &)> accepts;
  std::function<void(const QByteArray &, bool)> moveEffect;
  EffectDropZone() { setAcceptDrops(true); }
protected:
  void dragEnterEvent(QDragEnterEvent *event) override {
    if (accepts && accepts(event->mimeData()->data(mime))) event->acceptProposedAction();
  }
  void dragMoveEvent(QDragMoveEvent *event) override {
    if (accepts && accepts(event->mimeData()->data(mime))) {
      dropLine = event->position().y() < height() / 2.0 ? -1 : 1;
      update();
      event->acceptProposedAction();
    }
  }
  void dragLeaveEvent(QDragLeaveEvent *event) override { dropLine = 0; update(); event->accept(); }
  void dropEvent(QDropEvent *event) override {
    const int line = dropLine;
    dropLine = 0; update();
    const auto data = event->mimeData()->data(mime);
    if (accepts && accepts(data) && moveEffect) {
      moveEffect(data, line >= 0);
      event->acceptProposedAction();
    }
  }
  void paintEvent(QPaintEvent *event) override {
    QWidget::paintEvent(event);
    if (dropLine != 0) {
      QPainter p(this);
      p.setRenderHint(QPainter::Antialiasing);
      const int y = dropLine < 0 ? 0 : height() - 3;
      p.fillRect(QRect(0, y, width(), 3), ui_theme::ink("#2D8CFF"));
    }
  }
};

class HeaderClickFilter : public QObject {
  std::function<void()> onClick;
  std::function<void(const QPoint &)> onContextMenu;
  std::function<void()> onDelete;
  std::function<void()> onDragStart;
  QPoint pressPoint;
  bool isPressed = false;
public:
  HeaderClickFilter(QObject *parent, std::function<void()> click,
                    std::function<void(const QPoint &)> context = nullptr,
                    std::function<void()> del = nullptr,
                    std::function<void()> drag = nullptr)
      : QObject(parent), onClick(std::move(click)), onContextMenu(std::move(context)),
        onDelete(std::move(del)), onDragStart(std::move(drag)) {}
protected:
  bool eventFilter(QObject *obj, QEvent *e) override {
    if (e->type() == QEvent::MouseButtonPress) {
      auto *me = static_cast<QMouseEvent *>(e);
      if (me->button() == Qt::LeftButton) {
        pressPoint = me->pos();
        isPressed = true;
        if (onClick) onClick();
        if (qobject_cast<QWidget *>(obj) && !qobject_cast<QAbstractButton *>(obj) && obj->objectName() != "controlBody") {
          return false;
        }
      }
    } else if (e->type() == QEvent::MouseMove) {
      auto *me = static_cast<QMouseEvent *>(e);
      if (isPressed && (me->buttons() & Qt::LeftButton)) {
        if ((me->pos() - pressPoint).manhattanLength() >= QApplication::startDragDistance()) {
          isPressed = false;
          if (onDragStart) {
            onDragStart();
            return true;
          }
        }
      }
    } else if (e->type() == QEvent::MouseButtonRelease) {
      isPressed = false;
    } else if (e->type() == QEvent::ContextMenu) {
      auto *ce = static_cast<QContextMenuEvent *>(e);
      if (onContextMenu) { onContextMenu(ce->globalPos()); return true; }
    } else if (e->type() == QEvent::KeyPress) {
      auto *ke = static_cast<QKeyEvent *>(e);
      if (ke->key() == Qt::Key_Delete || ke->key() == Qt::Key_Backspace) {
        if (onDelete) { onDelete(); return true; }
      }
    }
    return QObject::eventFilter(obj, e);
  }
};

enum ProjectItemRole {
  ProjectKindRole = Qt::UserRole + 30,
  ProjectAssetIndexRole,
  ProjectIdRole
};

static QPixmap makeAssetPlaceholderPixmap(const QString &type, const QSize &size) {
  QPixmap pix(size);
  pix.fill(QColor("#0C0C0C"));
  QPainter p(&pix);
  p.setRenderHint(QPainter::Antialiasing);

  const int cx = size.width() / 2;
  const int cy = size.height() / 2;

  if (type == "MAIN" || type == "composition") {
    QRectF r(cx - 16, cy - 11, 32, 22);
    p.setPen(QPen(QColor("#3B82F6"), 1.2));
    p.setBrush(QColor("#15253A"));
    p.drawRoundedRect(r, 3, 3);
    p.setPen(QPen(QColor("#75B2FF"), 1.2));
    p.drawLine(QPointF(cx - 10, cy - 9), QPointF(cx - 6, cy - 3));
    p.drawLine(QPointF(cx - 3, cy - 9), QPointF(cx + 1, cy - 3));
    p.drawLine(QPointF(cx + 4, cy - 9), QPointF(cx + 8, cy - 3));
  } else if (type == "FOLDER" || type == "folder") {
    QRectF r(cx - 15, cy - 9, 30, 18);
    p.setPen(QPen(QColor("#F59E0B"), 1.2));
    p.setBrush(QColor("#2B2215"));
    p.drawRoundedRect(r, 2, 2);
    p.fillRect(QRectF(cx - 15, cy - 11, 12, 3), QColor("#F59E0B"));
  } else if (type == "AUDIO" || type == "audio") {
    p.setPen(QPen(QColor("#10B981"), 1.5));
    for (int i = -4; i <= 4; ++i) {
      int h = (i == 0) ? 16 : ((std::abs(i) % 2 == 0) ? 8 : 12);
      p.drawLine(cx + i * 3, cy - h / 2, cx + i * 3, cy + h / 2);
    }
  } else {
    QRectF r(cx - 15, cy - 10, 30, 20);
    p.setPen(QPen(QColor("#8B5CF6"), 1.2));
    p.setBrush(QColor("#1E182B"));
    p.drawRoundedRect(r, 2, 2);
    p.setPen(QPen(QColor("#A78BFA"), 1.2));
    QPainterPath path;
    path.moveTo(cx - 11, cy + 6);
    path.lineTo(cx - 3, cy - 3);
    path.lineTo(cx + 3, cy + 3);
    path.lineTo(cx + 7, cy - 1);
    path.lineTo(cx + 11, cy + 6);
    p.drawPath(path);
    p.drawEllipse(QPointF(cx + 6, cy - 5), 2, 2);
  }
  return pix;
}

static QIcon makeProjectCompIcon(int size = 16) {
  QPixmap pix(size, size);
  pix.fill(Qt::transparent);
  QPainter p(&pix);
  p.setRenderHint(QPainter::Antialiasing);
  QRectF r(1, 2, size - 2, size - 4);
  p.setPen(QPen(QColor("#75B2FF"), 1.2));
  p.setBrush(QColor("#1B4B99"));
  p.drawRoundedRect(r, 2, 2);
  p.setPen(QPen(QColor("#EAEAEA"), 1.0));
  p.drawLine(QPointF(r.left() + 3, r.top() + 1), QPointF(r.left() + 6, r.top() + 4));
  p.drawLine(QPointF(r.left() + 8, r.top() + 1), QPointF(r.left() + 11, r.top() + 4));
  return QIcon(pix);
}

