// Help > About Wavy-Flo: what it is, where its downloads are, and everyone who
// has made it. Its source is private, shared with the people invited to it, so
// nothing here points at it.
void showAboutWavyFlo(QWidget *parent) {
  QDialog dialog(parent);
  dialog.setWindowTitle("About Wavy-Flo");
  auto *layout = new QVBoxLayout(&dialog);
  auto *head = new QHBoxLayout;
  auto *icon = new QLabel;
  icon->setPixmap(QPixmap(":/resources/wavy-flo.png").scaled(64, 64, Qt::KeepAspectRatio, Qt::SmoothTransformation));
  head->addWidget(icon, 0, Qt::AlignTop);
  auto *about = new QLabel(QString(
      "<h2 style='margin:0'>Wavy-Flo %1</h2>"
      "<p>A Windows editor for motion graphics and music videos.</p>"
      "<p>What you make with Wavy-Flo is yours.</p>"
      "<p><a href='https://github.com/Kibo4aa/Wavy-Flo-Releases/releases/latest'>Downloads</a></p>")
      .arg(kWavyFloVersion));
  about->setWordWrap(true);
  about->setOpenExternalLinks(true);
  about->setTextInteractionFlags(Qt::TextBrowserInteraction);
  head->addWidget(about, 1);
  layout->addLayout(head);
  auto *credits = new QTextBrowser;
  credits->setOpenExternalLinks(true);
  const QString list = wavyFloCredits();
  if (list.isEmpty()) credits->setPlainText("Keblackan, and everyone who helps make Wavy-Flo.");
  else credits->setMarkdown(list);
  layout->addWidget(credits, 1);
  auto *buttons = new QDialogButtonBox(QDialogButtonBox::Close);
  auto *ffmpeg = buttons->addButton("FFmpeg licenses...", QDialogButtonBox::HelpRole);
  QObject::connect(ffmpeg, &QPushButton::clicked, &dialog, [&dialog] { showFFmpegLicenses(&dialog); });
  QObject::connect(buttons, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
  layout->addWidget(buttons);
  dialog.resize(560, 560);
  dialog.exec();
}
// The editor laid over a text layer while it is typed into. It draws no
// letters of its own: the layer itself, drawn by the renderer with its colour,
// strokes and effects, is what shows. Its own letters, drawn by the text
// widget, were the layer's plain colour (often white) and sat a pixel or two
// off the real ones, so the text seemed to lose its look and jump while it was
// edited. This draws only what typing needs -- the caret and the selection --
// where the same document's layout puts them.
class InlineTextEdit : public QTextEdit {
public:
  InlineTextEdit() {
    const int flash = QApplication::cursorFlashTime();
    blink.setInterval(flash > 0 ? flash / 2 : 530);
    QObject::connect(&blink, &QTimer::timeout, this, [this] {
      caretOn = !caretOn;
      viewport()->update();
    });
    blink.start();
    auto wake = [this] {
      caretOn = true;
      blink.start();
      viewport()->update();
    };
    QObject::connect(this, &QTextEdit::cursorPositionChanged, this, wake);
    QObject::connect(this, &QTextEdit::selectionChanged, this, wake);
    QObject::connect(this, &QTextEdit::textChanged, this, wake);
  }
protected:
  void paintEvent(QPaintEvent *) override {
    QPainter p(viewport());
    p.setRenderHint(QPainter::Antialiasing);
    const QTextCursor cursor = textCursor();
    const QPointF scroll(-horizontalScrollBar()->value(), -verticalScrollBar()->value());
    if (cursor.hasSelection()) {
      const int from = cursor.selectionStart(), to = cursor.selectionEnd();
      QColor tint("#2D8CFF");
      tint.setAlpha(95);
      for (QTextBlock block = document()->begin(); block.isValid(); block = block.next()) {
        const int start = block.position(), end = start + block.length();
        if (end <= from || start >= to) continue;
        const QTextLayout *layout = block.layout();
        if (!layout) continue;
        const QPointF origin = layout->position() + scroll;
        for (int i = 0; i < layout->lineCount(); ++i) {
          const QTextLine line = layout->lineAt(i);
          const int lineFrom = start + line.textStart(), lineTo = lineFrom + line.textLength();
          const int a = std::max(from, lineFrom), b = std::min(to, lineTo);
          if (a > b) continue;
          double x1 = line.cursorToX(a - start), x2 = line.cursorToX(b - start);
          if (x2 < x1) std::swap(x1, x2);
          // A selection running on past the end of the line takes its break too.
          if (to > lineTo) x2 += line.height() / 4;
          if (x2 - x1 < .5) continue;
          p.fillRect(QRectF(origin.x() + x1, origin.y() + line.y(), x2 - x1, line.height()), tint);
        }
      }
    }
    if (caretOn && hasFocus() && !cursor.hasSelection()) {
      const QRectF caret = cursorRect(cursor);
      const double thick = std::max(2., caret.height() / 24);
      const QRectF bar(caret.left() - thick / 2, caret.top(), thick, caret.height());
      // Dark round a light bar, so it shows on pale letters and dark ones alike.
      p.fillRect(bar.adjusted(-1, -1, 1, 1), QColor(16, 18, 24, 160));
      p.fillRect(bar, QColor("#2D8CFF"));
    }
  }
private:
  QTimer blink;
  bool caretOn = true;
};
class Editor;
// A point an OpenFX effect on a layer works with (OfxControl::point), as a
// handle on the preview: the effect, the two controls it sets and where those
// are among the effect's parameters, and where it is in the composition now.
struct OfxPointHandle {
  QString effect, idX, idY, label;
  int indexX = -1, indexY = -1;
  bool normalised = false;
  QPointF at;
};
class Preview : public QWidget {
public:
  Editor *e;
  QRectF imageRect;
  QPointF origin, panOrigin;
  QString tool = "select";
  QJsonArray pathDraft;
  QString maskTarget;
  // A Shape tool drag over a layer that is not a shape: the outline being drawn,
  // which becomes a mask on that layer when the button is let go.
  QString shapeMaskTarget;
  QJsonArray shapeMaskNodes;
  void commitShapeMask();
  // A Pen path made with no selection owns this new layer from its very first
  // point.  That makes the Shape Layer visible in the Timeline while it is
  // being drawn, instead of only appearing after the closing click.
  QString penTarget;
  bool penTargetCreated = false;
  bool penContinuing = false;
  int penBasePoints = 0;
  bool pathDragging = false;
  bool penHoverClose = false;
  QPointF penHoverPos;
  bool penHasHoverPos = false;
  bool penAltBreak = false;
  QPointF penInitialIn;
  void finishPath(bool closed);
  void cancelPathDraft();
  double zoom = 1;
  int resolutionDivisor = 1;
  // Auto: drawn at no more pixels than the viewer shows the Main at (see
  // paintEvent), and at full resolution from 100% up.
  bool autoResolution = true;
  QPointF pan;
  bool grid = true, transparency = true;
  bool layerBox = true;
  // Snapping. A drag catches on the composition's own edges and middle and on
  // the edges and middle of every other layer visible at this frame, within
  // eight screen pixels -- eight pixels of pointer travel, not of composition,
  // so it feels the same however far you have zoomed in. Ctrl suspends it for
  // one drag without turning it off.
  bool snapping = true;
  double snapGuideX = 0, snapGuideY = 0;
  bool snappedX = false, snappedY = false;
  void collectGuides(QVector<double> &xs, QVector<double> &ys) const;
  QPointF snapped(QPointF point, Qt::KeyboardModifiers);
  QPointF snapBox(QRectF box, Qt::KeyboardModifiers);
  void clearSnap() { snappedX = snappedY = false; }
  QPointer<QTextEdit> inlineEditor;
  int editingLayer = -1;
  QPointer<QGraphicsView> textEditView;
  QGraphicsProxyWidget *textEditProxy = nullptr;
  bool dragging = false, spaceHeld = false, spaceDragged = false, dragCheckpoint = false;
  // A drag of a layer inside a selected Layer Struktur: the other layers of
  // the selection, each with its Position when the drag began, moved by as
  // much on the canvas.
  std::vector<std::pair<int, QPointF>> structureDrag;
  // A layer, a shape or a motion path being dragged in the viewer: the
  // timeline's rows and the frames held ahead wait for the button to come up
  // (Editor::refresh), since a drag changes neither.
  bool editingByDrag() const { return (dragging && tool != "hand" && !spaceHeld) || motionPathDragKind != 0; }
  // A track point being dragged: which, and how the pointer maps back into
  // the footage's own coordinates.
  int trackDragPoint = -1;
  QPointF trackDragOffset;
  QTransform trackDragBack;
  // An OpenFX point being dragged, and how far the pointer is from it.
  std::optional<OfxPointHandle> ofxDrag;
  QPointF ofxDragOffset;
  // Composition to the widget, as the frame is shown.
  QTransform compositionScreen() const;
  QTransform trackScreen(const Layer &) const;
  int motionPathDragKind = 0; // 0 = none, 1 = keyframe, 2 = out-handle, 3 = in-handle
  int motionPathDragSeg = -1;
  double motionPathDragFrame = 0;
  QPointF motionPathDragStartComp;
  QPointF motionPathDragInitialOffset;
  double motionPathOppositeLen = 0;
  QElapsedTimer spaceClock;
  bool event(QEvent *) override;
  // The rendered frame is kept until the composition itself changes. update()
  // marks it stale -- every edit path already calls it -- while overlay-only
  // repaints (panning, zooming, selection handles, guides, path drafts) call
  // updateOverlay() and reuse the pixels that are already on screen.
  QImage cachedImage;
  QRect cachedRegion;
  QSize cachedTarget;
  bool frameValid = false;
  int cachedEditing = -2;
  double cachedFrameTime = -1;
  quint64 renderRevision = 0;
  struct CpuFrame { QImage image; QSize target; QRect region; double frame=0,ms=0; int editing=-1; quint64 revision=0; QString work; bool gpu=false; bool plate=false; };
  // A layer dragged here on the cores: the picture of everything beneath it,
  // drawn once for the drag (renderOverPlate). Dropped when the drag ends.
  std::shared_ptr<DragPlate> dragPlate;
  // The frames being drawn, and which frames they are. Only the first while
  // editing; playing a Main that takes longer to draw than a frame lasts, a
  // second alongside it: whatever one leaves idle -- a title's letters drawn
  // on one core, the wait for the last band -- the other uses. (A third gained
  // nothing: by then every core is busy.)
  static constexpr int kCpuJobs = 2;
  std::array<std::future<CpuFrame>, kCpuJobs> cpuJobs;
  std::array<double, kCpuJobs> cpuJobAt{-1, -1};
  // Which of them is drawing on the card.
  std::array<bool, kCpuJobs> cpuJobOnCard{false, false};
  // Set by a job as it hands its frame over, just before its future is ready.
  std::array<std::shared_ptr<std::atomic<bool>>, kCpuJobs> cpuJobDone;
  // The edit each job draws, and the one whose picture is on screen: during a
  // drag two can be under way, and the later one may come back first.
  std::array<quint64, kCpuJobs> cpuJobRevision{0, 0};
  quint64 shownRevision = 0;
  bool cpuBusy() const { return std::any_of(cpuJobs.begin(), cpuJobs.end(), [](const auto &j) { return j.valid(); }); }
  // Frames finished before the playhead reached them, held until it does: shown
  // the moment they were done, the picture ran a frame or three ahead of the
  // playhead instead of behind it.
  std::vector<CpuFrame> heldFrames;
  bool framePollScheduled=false;
  // How long the last full-resolution frame took to make, so a slow one can be
  // produced off the UI thread while the previous picture stays on screen.
  double lastFullFrameMs=0;
  // The same, smoothed over the frames of a playback, for how far ahead of the
  // playhead the next one is drawn.
  double playbackFrameMs=0;
  // Viewer pixels per composition pixel in the last frame drawn: how small
  // footage can be decoded and still look the same (footageShrinkFor).
  double footageScale=0;
  void update() { ++renderRevision; frameValid = false; QWidget::update(); }
  void updateOverlay() { QWidget::update(); }
  // Layers about to come on, drawn once on their own in the background while
  // playing, so the frame they first appear in finds their pictures made: a
  // title appearing cost that frame 10-35 ms more than the next (Kotonoha's
  // HUD part INTRO, 45 ms against 9 once warmed), often a skipped frame.
  std::future<void> warmJob;
  QSet<QString> warmedLayers;
  void warmAppearing(const Scene &s, double from, QSize target, QRect region);
  Preview(Editor *editor);
  void wheelEvent(QWheelEvent *) override;
  void paintEvent(QPaintEvent *) override;
  void mousePressEvent(QMouseEvent *) override;
  void mouseMoveEvent(QMouseEvent *) override;
  void mouseReleaseEvent(QMouseEvent *) override;
  void mouseDoubleClickEvent(QMouseEvent *) override;
  void leaveEvent(QEvent *) override;
  QPointF comp(QPointF point) const;
};
struct Pick {
  int layer = 0, key = 0, property = 0;
  bool operator<(const Pick &o) const {
    return std::tie(layer, property, key) <
           std::tie(o.layer, o.property, o.key);
  }
};
class Timeline : public QWidget {  
public:
  Editor *e;
  bool graph = false;
  // labelWidth must hold, left to right: eye, No, Name, then the right-anchored
  // block Link + Blend + Matte + (audio, 3D, MB). colLinkWidth is that whole
  // right block, so it has to be at least Blend + Matte + the three switches
  // plus room for the Link text -- otherwise Blend spills left over Name and
  // the header reads as one mangled column. These defaults satisfy that; the
  // drag clamps below keep it true when either divider is moved.
  int prop = 0, filter = -1, filterLayer = -1, labelWidth = 520;
  QString layerSearchQuery;
  // Left switch & identity columns: Eye, Solo (Isolate), and combined > Label Swatch categories
  // Eye, Solo and Lock share the 48 px Eye and Solo had, so the label, the
  // number and the name stay where they were.
  static constexpr int eyeColumnWidth = 16, soloColumnWidth = 16, lockColumnWidth = 16, labelColumnWidth = 36;
  int colHideWidth = eyeColumnWidth + soloColumnWidth + lockColumnWidth + labelColumnWidth; // 84: right border of > Label, left border of #
  int colNoWidth = 108, colLinkWidth = 282; // 108: right border of #, left border of Layer Name
  static constexpr int eyeCenter = 8, isolateCenter = 24, lockCenter = 40;
  static constexpr int switchesWidth = eyeColumnWidth + soloColumnWidth + lockColumnWidth;
  static constexpr int layerArrowCenter = 56, labelSwatchCenter = 72;
  // Vertical metrics, kept as named constants so the ruler strip, layer rows
  // and property rows can be made shorter in one place -- every draw and every
  // hit test derives its offsets from these, so the two never drift apart.
  // Trimmed to ~75% of the original 26/28/24 to give the timeline back height.
  int rulerH = 26; // top strip: ruler + column headers
  int rowH = 22;   // a layer or section header row
  int propH = 19;  // a single property (keyframe) row
  void applyUiScale(double scale) {
    rulerH = std::max(20, (int)std::round(26.0 * scale));
    rowH = std::max(18, (int)std::round(22.0 * scale));
    propH = std::max(15, (int)std::round(19.0 * scale));
    rebuild();
    update();
  }
  // Layer switch columns: balanced with identical widths for pixel symmetry.
  int audioColumnWidth = 26;
  int threeDColumnWidth = 26;
  int motionBlurColumnWidth = 26;
  int blendColumnWidth = 64;
  int matteColumnWidth = 80;
  int layerControlWidth() const {
    return audioColumnWidth + threeDColumnWidth + motionBlurColumnWidth;
  }
  int audioColumnLeft() const { return labelWidth - layerControlWidth(); }
  int matteColumnLeft() const { return audioColumnLeft() - matteColumnWidth; }
  int blendColumnLeft() const { return matteColumnLeft() - blendColumnWidth; }
  int threeDColumnLeft() const { return labelWidth - motionBlurColumnWidth - threeDColumnWidth; }
  int motionBlurColumnLeft() const { return labelWidth - motionBlurColumnWidth; }
  int linkTextWidth() const {
    return std::max(10, blendColumnLeft() - (labelWidth - colLinkWidth) - 14);
  }
  double ppf = 3, scrollX = 0;
  int fittedWidth = -1, fittedFrames = -1, fittedLabelWidth = -1;
  bool fitKeys = false;
  struct Row {
    int layer, property;
    bool header, paired;
    double top;
    int section =
        0; // 0 layer/property, 1 Transform, 2 Effect, 3 Text-Animation, 10 one Text Animation of a stack, 11 Additional Transform
    int indent = 0;
    // Where a property's name starts, and the guides down the left tying the
    // row to the groups it is in: bit 0 the first level (Transform, Effect...),
    // bit 1 the second (Text Animation, a path), bit 2 one Text Animation.
    int nameLeft = 98;
    int guides = 0;
    QString uid; // section 10: which Text Animation, section 11: which Additional Transform
  };
  struct TimelineItem {
    int layer = -1;
    int section = 0;
    int property = -1;
    QString uid;

    bool operator<(const TimelineItem &o) const {
      if (layer != o.layer) return layer < o.layer;
      if (section != o.section) return section < o.section;
      if (property != o.property) return property < o.property;
      return uid < o.uid;
    }
    bool operator==(const TimelineItem &o) const {
      return layer == o.layer && section == o.section && property == o.property && uid == o.uid;
    }
  };
  TimelineItem itemKey(const Row &r) const {
    return {r.layer, r.section, r.property, r.uid};
  }
  std::set<TimelineItem> selectedItems;
  int selectionAnchorRow = -1;
  bool isRowSelected(const Row &r) const;
  bool isArrowAt(const Row &r, QPointF pt) const;
  void selectRow(int rowIndex, Qt::KeyboardModifiers modifiers);
  bool hasNonLayerSelection() const;
  void deleteSelectedItems();
  static constexpr int guideX(int level) { return 56 + level * 16; }
  QRectF parentLinkRect(const Row &r) const {
    const double left = labelWidth - colLinkWidth + 4;
    return QRectF(left, r.top + (rowH - 16) / 2., std::max(10.0, blendColumnLeft() - left - 4), 16);
  }
  QRectF blendModeRect(const Row &r) const {
    return QRectF(blendColumnLeft() + 2, r.top + (rowH - 16) / 2., std::max(10.0, blendColumnWidth - 4.0), 16);
  }
  QRectF matteModeRect(const Row &r) const {
    return QRectF(matteColumnLeft() + 2, r.top + (rowH - 16) / 2., std::max(10.0, matteColumnWidth - 24.0), 16);
  }
  QRectF matteInvertRect(const Row &r) const {
    return QRectF(matteColumnLeft() + matteColumnWidth - 20, r.top + (rowH - 16) / 2., 18, 16);
  }
  QRectF maskSwatchRect(const Row &r) const {
    return QRectF(104, r.top + (rowH - 12) / 2.0, 12, 12);
  }
  QRectF maskModeRect(const Row &r) const {
    return QRectF(188, r.top + (rowH - 18) / 2.0, 68, 18);
  }
  QRectF maskInvertRect(const Row &r) const {
    return QRectF(262, r.top + (rowH - 18) / 2.0, 56, 18);
  }
  QRectF maskLockRect(const Row &r) const {
    return QRectF(324, r.top + (rowH - 18) / 2.0, 18, 18);
  }
  std::vector<Row> rows;
  int reorderSource = -1, reorderSlot = -1;
  double reorderY = 0;
  // Into which Layer Struktur the dragged row would go (none when empty), how
  // far in its line is drawn, and the structure's row it would be dropped
  // onto (-1 when it goes between rows instead).
  QString reorderInto;
  int reorderIndent = 0, reorderOnto = -1;
  // The drop a pointer at `y` would make, into the members above.
  void reorderTarget(double y);
  int pickWhipSource = -1, pickWhipTarget = -1, pickWhipHover = -1;
  QPointF pickWhipEnd;
  int activeRow = -1, activeValueProp = 0;
  double valueBefore = 0, layerStartBefore = 0, layerDurationBefore = 0;
  double sourceOffsetBefore = 0;
  std::map<int, double> multiLayerStartsBefore;
  QTimer edgeTimer;
  // While a value is dragged -- in the viewer or on a number -- the rows only
  // show it changing, and painting them again for every picture cost a busy
  // Main five milliseconds each time: thirty times a second is plenty.
  QTimer paintSoon;
  QElapsedTimer lastPainted;
  void updateSoon() {
    if (paintSoon.isActive()) return;
    const qint64 since = lastPainted.isValid() ? lastPainted.elapsed() : 1000;
    paintSoon.start(int(std::max<qint64>(0, 33 - since)));
  }
  QPointF scrubPointer;
  void scrubCTI();
  void rebuild();
  std::vector<Pick> picks() const;
  std::vector<int> rowProps(const Row &) const;
  // A parameter's stopwatch set on (a first keyframe at the playhead, when it
  // has none) or off (every keyframe gone, the value left as the playhead shows it).
  void setStopwatch(const Row &, bool on);
  bool isScaleRow(const Row &) const;
  QRectF valueRect(const Row &, int property) const;
  QRectF scaleLockRect(const Row &) const;
  void contextMenuEvent(QContextMenuEvent *) override;
  void wheelEvent(QWheelEvent *) override;
  void mouseDoubleClickEvent(QMouseEvent *) override;
  void editNumber(int row, int property);
  // Renaming in place, the way a list of named things is renamed everywhere
  // else: select the row, press Return, type.
  void editLayerName(int row);
  void keyPressEvent(QKeyEvent *) override;
  std::set<Pick> selected;
  void expandPairedSelection();
  QString gesture;
  // Composition markers in the ruler: which one is being dragged, where it was
  // taken hold of, and whether it has moved yet (an undo step only if it has).
  int markerDragging = -1;
  double markerGrab = 0;
  bool markerMoved = false;
  int markerAt(QPointF point) const;
  void paintMarkers(QPainter &p);
  void paintPlayRange(QPainter &p);
  // The Play Range's bar along the top of the ruler: its ends or the whole of
  // it taken hold of ("rangeStart", "rangeEnd", "rangeMove"), where it was
  // taken, and whether it has moved yet (an undo step only if it has).
  QString playRangePartAt(QPointF point) const;
  double rangeGrab = 0;
  bool rangeMoved = false;
  bool dragToggleTargetState = false;
  int shiftDragAxis = 0;
  QPointF origin;
  QRectF marquee;
  double lower = 0, upper = 1, graphZoomX = 1, graphZoomY = 1;
  QPointF graphPan;
  double graphValue(double py) const {
    return lower + (plot().bottom() + graphPan.y() - py) /
                       (plot().height() * graphZoomY) * (upper - lower);
  }
  std::vector<std::tuple<Pick, double, double>> initial;
  int handleKey = -1, handleIndex = 0;
  double oppositeHandleRadius = 0, keyDragValuePerPixel = 1;
  Timeline(Editor *editor);
  double x(double f) const;
  double frame(double x) const;
  QRectF plot() const;
  QRectF frameArea() const;
  double y(double v) const;
  QPointF keyPoint(int l, int k, int property = -1) const;
  void bounds();
  void clampGraphHorizontal();
  QPainterPath graphPath() const;
  void followSelection();
  void fitGraphView();
  void paintEvent(QPaintEvent *) override;
  void mousePressEvent(QMouseEvent *) override;
  void mouseMoveEvent(QMouseEvent *) override;
  void mouseReleaseEvent(QMouseEvent *) override;
  // The top strip -- column names, ruler, markers -- stays at the top of what
  // is shown while the rows scroll under it. The drawing and the handling are
  // written for an unscrolled strip at y 0; these put it where it is seen.
  int scrollShift() const;
  bool inStickyHeader(QPointF) const;
  std::unique_ptr<QMouseEvent> headerMapped(QMouseEvent *, bool map) const;
  void paintBody(QPainter &, QPaintEvent *);
  void pressAt(QMouseEvent *);
  void moveAt(QMouseEvent *);
  void releaseAt(QMouseEvent *);
  void doubleClickAt(QMouseEvent *);
  void contextMenuAt(QContextMenuEvent *);
  bool headerPass = false, pressInHeader = false;
  void dragEnterEvent(QDragEnterEvent *) override;
  void dragMoveEvent(QDragMoveEvent *) override;
  void dropEvent(QDropEvent *) override;
  void showParentMenu(int layer, const QPoint &globalPosition);
  void showBlendModeMenu(int layer, const QPoint &globalPosition);
  void showLabelMenu(int layer, const QPoint &globalPosition);
  // The layers a click on one row's switch, Link or Matte reaches: every
  // selected layer when the clicked one is among several selected (as in
  // After Effects), otherwise only the one clicked.
  std::vector<int> clickTargets(int clicked) const;
  // One switch of one layer set the way the sweep `kind` sets it ("drag_hide",
  // "drag_isolate", "drag_lock", "drag_audio", "drag_3d", "drag_blur"). A
  // Layer Struktur passes its eye, solo and lock on to what it holds.
  // Whether anything changed.
  bool setSwitch(const QString &kind, int index, bool on);
  // A switch clicked: set to `on` on clickTargets(clicked) as one undo step,
  // and the sweep begun that a drag on from here continues.
  void pressSwitch(const QString &kind, int clicked, bool on);
  // The parent (-1: none) or the matte (empty: none) chosen on a row, given
  // to clickTargets(clicked) but the chosen layer itself. One undo step, and
  // none when nothing changes; whether anything did.
  bool setParentFrom(int clicked, int parent);
  bool setMatteFrom(int clicked, const QString &matteId);
  // The other selected layers' own copy of property `p` of `layer` (layer,
  // property), when `layer` is among several selected.
  std::vector<std::pair<int, int>> sameValueTargets(int layer, int p) const;
  // Theirs as it was when a value drag began (layer, property, value): each
  // is moved by as much as the dragged one.
  std::vector<std::tuple<int, int, double>> valueAlso;
  // Each of `values` set as though its layer were the selected one; the
  // timeline goes on showing the clicked layer's property and picked keys.
  void setValuesOnOthers(const std::vector<std::tuple<int, int, double>> &values);
  // Alt-click on a solo switch: this layer (a Layer Struktur: what it holds)
  // the only one soloed; Alt-clicked again while it is, solo off everywhere.
  // One undo step.
  void soloOnly(int clicked);
  // A layer's arrow clicked: it opens or folds; with Ctrl (`selectedToo`),
  // every selected layer goes the same way when it is one of them.
  void toggleArrow(int clicked, bool selectedToo);
  // The time ruler zoomed by `factor` (= and -), the playhead kept where it is
  // on screen; ; goes between one frame's detail and the whole Main.
  void zoomTime(double factor);
  void zoomFramesOrAll();
  // The picked keys all held, or (when they all are already) made linear again.
  void toggleHoldKeys();
  void ease(QString type);
  // The picked keys of each property played backwards in their own span.
  // Returns how many properties were turned round.
  int reverseKeys();
  bool stretchKeys = false;
  double stretchPivotFrame = 0;
  double stretchHandleFrame = 0;
  int stretchSelectedKeys(double factor);
  void stretchKeysDialog();
};
// A pre-render run on its way: what its lanes have drawn and not yet handed
// over, and where the playhead is, so a lane does not start a frame the
// playhead will have passed before it is done.
struct PreRenderRun {
  QMutex guard;
  QVector<QPair<int, PreRenderCache::Prepared>> ready;
  std::atomic<int> playhead{0};
  std::atomic<int> lead{0}; // frames closer than this ahead of the playhead are not started
  int total = 0;
  bool playing = false;
  std::atomic<qint64> renderNs{0};
  std::atomic<int> rendered{0};
};

