  // OpenFX instances of layers no longer in the project let go of.
  void releaseOfxInstances();
  // `frame`: the frame being drawn, when that is not the one on screen (export).
  int processEffect(const WavyEffectV1 *api, QImage &image, double frame = -1) {
    if (const auto *ofx = ofxPlugins.value(api, nullptr)) {
      QString problem;
      const bool drawn = ofxRender(*ofx, QStringLiteral("frame|") + ofx->identifier, image,
                                   frame >= 0 ? frame : scene.frame, std::max(1, scene.fps),
                                   pluginValues(api), 1.0, &problem);
      if (!drawn) reportOfxProblem(problem);
      return drawn ? 0 : 1;
    }
    // A graph plugin describes operations and the host runs them, so it is on
    // the GPU or across every core without the plugin containing a line about
    // either. A pixel plugin writes its own loop, and gets the same cores only
    // if it has said that is safe.
    if(auto *graph=graphPlugins.value(api,nullptr))return executeEffectGraph(graph,image,preferGpu);
    const auto *parallel=parallelPlugins.value(api,nullptr);
    const bool reentrant=parallel && parallel->reentrant;
    const int reach=parallel?parallel->rowReach:0;
    // A plugin with controls is called with them, whatever the depth: V4 is the
    // only entry point that carries values, so it is tried before the older two.
    if(const auto *v4=parameterPlugins.value(api,nullptr)) {
      const int depth=image.depth()==32?8:image.format()==QImage::Format_RGBA64?16:32;
      const unsigned bit=depth==8?1u:depth==16?2u:4u;
      if(v4->supportedDepths & bit) {
        const auto values=pluginValues(api);
        return pluginRuntime.process(api,*v4,shaderPlugins.value(api,nullptr),parallel,
                                     image,values,preferGpu);
      }
    }
    if(image.depth()==32)
      return pluginRuntime.processPixels(api,parallel,image,[api](void *p,int w,int h,int s){
        return api->process(static_cast<uint8_t *>(p),w,h,s,1);});
    int depth=image.format()==QImage::Format_RGBA64 ? 16 : 32;
    auto *v2=precisionPlugins.value(api,nullptr);
    if(!v2 || !(v2->supportedDepths & (depth==16?2u:4u))) {
      statusBar()->showMessage("Selected plugin supports only 8 bpc; choose a compatible plugin or an 8 bpc Main.");
      return -2;
    }
    return pluginRuntime.processPixels(api,parallel,image,[v2,depth](void *p,int w,int h,int s){
      return v2->process(p,w,h,s,depth,1);});
  }
