  struct HeldRefresh {
    Editor *e;
    explicit HeldRefresh(Editor *editor) : e(editor) { ++e->refreshHeld; }
    ~HeldRefresh() {
      if (--e->refreshHeld > 0 || !e->refreshOwed) return;
      const bool list = e->refreshOwedList, timeOnly = e->refreshOwedTimeOnly;
      e->refreshOwed = e->refreshOwedList = false;
      e->refreshOwedTimeOnly = true;
      e->refresh(list, timeOnly);
    }
    HeldRefresh(const HeldRefresh &) = delete;
    HeldRefresh &operator=(const HeldRefresh &) = delete;
  };
