  auto makeDock = [&](QString name, QWidget *content, Qt::DockWidgetArea area) {
    auto *d = new DockPanel(name, this);
    d->setAcceptDrops(true);
    d->setObjectName(name);
    d->setAllowedAreas(Qt::AllDockWidgetAreas);
    d->setMinimumSize(0, 0);
    if (content) {
      content->setMinimumSize(0, 0);
    }
    d->setWidget(content);
    d->setFeatures(QDockWidget::DockWidgetMovable |
                   QDockWidget::DockWidgetFloatable |
                   QDockWidget::DockWidgetClosable);
    connect(d,&QDockWidget::topLevelChanged,d,[this]{
      QTimer::singleShot(0,this,[this]{syncDockPanels(this);});
    });
    connect(d,&QDockWidget::dockLocationChanged,d,[this]{
      QTimer::singleShot(0,this,[this]{syncDockPanels(this);});
    });
    addDockWidget(area, d);
    return d;
  };
