  connect(assetProbe, &QMediaPlayer::durationChanged, this, &Editor::showAssetInfo);
  connect(assetProbeSink, &QVideoSink::videoFrameChanged, this,
          [this](const QVideoFrame &frame) {
            if (!assetPreview || !frame.isValid()) return;
            const QImage image = frame.toImage();
            if (image.isNull()) return;
            assetPreview->setText({});
            assetPreview->setPixmap(QPixmap::fromImage(image).scaled(
                assetPreview->size() - QSize(4, 4), Qt::KeepAspectRatio,
                Qt::SmoothTransformation));
          });
  connect(project, &QTreeWidget::currentItemChanged, this,
          [this](QTreeWidgetItem *, QTreeWidgetItem *) {
    if (!syncing) showAssetInfo();
  });
  connect(project, &QTreeWidget::itemDoubleClicked, this,
          [this](QTreeWidgetItem *item, int) {
            if (!item) return;
            const QString kind = item->data(0, ProjectKindRole).toString();
            if (kind == "folder") {
              item->setExpanded(!item->isExpanded());
            } else if (kind == "composition") {
              if (!activeGroupId.isEmpty()) {
                leaveGroup(true);
              }
            } else if (kind == "group") {
              const QString id = item->data(0, ProjectIdRole).toString();
              for (int i = 0; i < int(scene.layers.size()); ++i) {
                if (scene.layers[i].id == id && scene.layers[i].type == "group") {
                  openGroup(i);
                  break;
                }
              }
            } else {
              addProjectAsset();
            }
          });
  connect(project, &QTreeWidget::itemChanged, this,
          [this](QTreeWidgetItem *item, int) {
            if (syncing || !item) return;
            const QString id = item->data(0, ProjectIdRole).toString();
            if (id.isEmpty()) return;
            if (item->data(0, ProjectKindRole).toString() == "group") {
              checkpoint();
              for (auto &l : scene.layers) {
                if (l.id == id && l.type == "group") {
                  l.name = item->text(0).trimmed().isEmpty() ? "Group" : item->text(0).trimmed();
                  dirty = true;
                  break;
                }
              }
              showAssetInfo();
              refresh(false);
              return;
            }
            for (int i = 0; i < scene.assets.size(); ++i) {
              auto object = scene.assets[i].toObject();
              if (object["assetId"].toString() != id || object["name"].toString() == item->text(0))
                continue;
              object["name"] = item->text(0).trimmed().isEmpty() ? "Untitled" : item->text(0).trimmed();
              scene.assets[i] = object;
              if (projectAssetCache.contains(id))
                projectAssetCache[id].name = object["name"].toString();
              dirty = true;
              break;
            }
            showAssetInfo();
          });
  auto rememberFolder = [this](QTreeWidgetItem *item) {
    if (syncing || !item || item->data(0, ProjectKindRole).toString() != "folder") return;
    const QString id = item->data(0, ProjectIdRole).toString();
    for (int i = 0; i < scene.assets.size(); ++i) {
      auto object = scene.assets[i].toObject();
      if (object["assetId"].toString() != id) continue;
      object["expanded"] = item->isExpanded();
      scene.assets[i] = object;
      dirty = true;
      break;
    }
  };
