  auto styleButton = [&](const QString &name, const QString &tip,
                         const std::function<void(QPainter &, const QRectF &)> &draw) {
    auto *b = new QPushButton;
    b->setObjectName("textStyle/" + name);
    b->setCheckable(true);
    b->setFixedSize(26, 22);
    b->setIconSize(QSize(20, 14));
    b->setToolTip(tip);
    b->setAccessibleName(tip);
    b->setCursor(Qt::PointingHandCursor);
    b->setStyleSheet(
        "QPushButton { background: transparent; border: none; border-radius: 3px; padding: 0; } "
        "QPushButton:hover { background: rgba(255, 255, 255, 0.08); } "
        "QPushButton:checked { background: #383D4C; border-radius: 3px; }");
    auto picture = [&](const QColor &ink) {
      QPixmap px(QSize(40, 28));
      px.setDevicePixelRatio(2);
      px.fill(Qt::transparent);
      QPainter painter(&px);
      painter.setRenderHint(QPainter::Antialiasing);
      painter.setRenderHint(QPainter::TextAntialiasing);
      painter.setPen(ink);
      draw(painter, QRectF(0, 0, 20, 14));
      return px;
    };
    QIcon icon;
    icon.addPixmap(picture(QColor("#8E94A4")), QIcon::Normal, QIcon::Off);
    icon.addPixmap(picture(QColor("#FFFFFF")), QIcon::Active, QIcon::Off);
    icon.addPixmap(picture(QColor("#FFFFFF")), QIcon::Normal, QIcon::On);
    icon.addPixmap(picture(QColor("#FFFFFF")), QIcon::Active, QIcon::On);
    b->setIcon(ui_theme::themedIcon(icon));
    styleLayout->addWidget(b);
    return b;
  };
