  capsButtons[1] = styleButton("smallCaps", "Small Caps", [&](QPainter &q, const QRectF &a) {
    QFont big("Segoe UI"), small_("Segoe UI");
    big.setPixelSize(11);
    big.setBold(true);
    small_.setPixelSize(8);
    small_.setBold(true);
    const double baseline = a.center().y() + 4.0;
    q.setFont(big);
    const double wide = QFontMetricsF(big).horizontalAdvance("A") + QFontMetricsF(small_).horizontalAdvance("A") + 1;
    const double left = a.center().x() - wide / 2;
    q.drawText(QPointF(left, baseline), "A");
    q.setFont(small_);
    q.drawText(QPointF(left + QFontMetricsF(big).horizontalAdvance("A") + 1, baseline), "A");
  });
  capsButtons[2] = styleButton("lowercase", "All Lowercase", [&](QPainter &q, const QRectF &a) { styleLetters(q, a, "aa", 11, true, false); });
