  auto *alignHeader = new QLabel("ALIGN LAYERS");
  alignHeader->setStyleSheet("color: #8E8E8E; font-size: 10px; font-weight: 700; letter-spacing: 0.5px; margin-top: 4px;");
  alignPanelLayout->addWidget(alignHeader);

  auto *alignBtnRow = new QHBoxLayout;
  alignBtnRow->setContentsMargins(0, 0, 0, 0);
  alignBtnRow->setSpacing(2);

  for (int i : {0, 1, 2, 6, 3, 4, 5}) {
    if (i == 6) {
      alignBtnRow->addWidget(makeVDivider());
    } else if (i == 3) {
      alignBtnRow->addWidget(makeVDivider());
    }
    auto *button = new QPushButton;
    button->setObjectName(QString("compositionAlign/%1").arg(i));
    button->setFixedSize(26, 22);
    button->setIconSize(QSize(18, 18));
    button->setStyleSheet(
        "QPushButton { background: transparent; border: 1px solid transparent; border-radius: 3px; padding: 0; } "
        "QPushButton:hover { background: #2A2A2A; border: 1px solid #444444; } "
        "QPushButton:pressed { background: #202020; border: 1px solid #666666; }");
    auto label = QStringList{"Align Left", "Center Horizontally", "Align Right", "Align Top", "Center Vertically", "Align Bottom", "Center in Main"}[i];
    button->setToolTip(label);
    button->setAccessibleName(label);
    auto makeAlignPixmap = [&](const QColor &lineCol, const QColor &boxCol) {
      QPixmap icon(18, 18);
      icon.fill(Qt::transparent);
      QPainter painter(&icon);
      painter.setRenderHint(QPainter::Antialiasing);
      painter.setPen(QPen(lineCol, 1.8));
      if (i == 6) {
        painter.drawLine(9, 1, 9, 17);
        painter.drawLine(1, 9, 17, 9);
        painter.setBrush(boxCol);
        painter.setPen(Qt::NoPen);
        painter.drawRect(QRectF(5.5, 5.5, 7.0, 7.0));
      } else {
        if (i >= 3) { painter.translate(18, 0); painter.rotate(90); }
        int mode = i % 3, axis = mode == 0 ? 3 : mode == 1 ? 9 : 15;
        painter.drawLine(axis, 1, axis, 17);
        painter.setPen(Qt::NoPen);
        painter.setBrush(boxCol);
        for (int row = 0; row < 2; ++row) {
          int w = row ? 6 : 10;
          int x = mode == 0 ? axis : mode == 1 ? axis - w / 2 : axis - w;
          painter.drawRect(QRectF(x, row ? 10.5 : 3.5, w, 4.5));
        }
      }
      return icon;
    };
    QIcon alignIcon;
    alignIcon.addPixmap(makeAlignPixmap(QColor("#E2E2E2"), QColor("#E2E2E2")), QIcon::Normal);
    alignIcon.addPixmap(makeAlignPixmap(QColor("#FFFFFF"), QColor("#FFFFFF")), QIcon::Active);
    button->setIcon(ui_theme::themedIcon(alignIcon));
    alignBtnRow->addWidget(button);
    connect(button, &QPushButton::clicked, this, [=] {
      if (!layer()) return;
      struct Target { int index; QRectF bounds; };
      std::vector<Target> targets;
      auto boundsOf = [&](const Layer &l) {
        double t = scene.frame - l.start;
        QTransform tr = layerWorldTransform(l, scene, scene.frame);
        return tr.mapRect(layerContentBounds(l, scene));
      };
      QRectF reference(0, 0, scene.width, scene.height);
      int mode = alignReference->currentIndex();
      for (int index : alignSelection) {
        if (index < 0 || index >= int(scene.layers.size())) continue;
        const auto &l = scene.layers[index];
        if (scene.frame < l.start || scene.frame >= l.start + l.duration) continue;
        QRectF box = boundsOf(l);
        if (mode == 2) reference = targets.empty() ? box : reference.united(box);
        targets.push_back({index, box});
      }
      if (targets.empty()) return;
      if (mode == 0) reference = boundsOf(*layer());
      checkpoint();
      for (const auto &target : targets) {
        if (mode == 0 && target.index == scene.selected) continue;
        auto &l = scene.layers[target.index];
        const auto &box = target.bounds;
        double dx = i == 0 ? reference.left() - box.left() : i == 2 ? reference.right() - box.right() : reference.center().x() - box.center().x();
        double dy = i == 3 ? reference.top() - box.top() : i == 5 ? reference.bottom() - box.bottom() : reference.center().y() - box.center().y();
        double t = scene.frame - l.start;
        auto move = [&](int axis, double delta) {
          auto &property = l.p[axis];
          double value = property.at(t) + delta;
          if (property.keys.empty()) property.base = value;
          else property.set(t, value);
        };
        auto delta = layerPositionDelta(l, scene, scene.frame,
            QPointF(i < 3 || i == 6 ? dx : 0, i >= 3 ? dy : 0));
        move(0, delta.x());
        move(1, delta.y());
      }
      dirty = true;
      refresh();
    });
  }
  alignBtnRow->addStretch(1);
  alignPanelLayout->addLayout(alignBtnRow);

  auto *distributeHeader = new QLabel("DISTRIBUTE LAYERS");
  distributeHeader->setStyleSheet("color: #8E8E8E; font-size: 10px; font-weight: 700; letter-spacing: 0.5px; margin-top: 6px;");
  alignPanelLayout->addWidget(distributeHeader);

  auto *distributeBtnRow = new QHBoxLayout;
  distributeBtnRow->setContentsMargins(0, 0, 0, 0);
  distributeBtnRow->setSpacing(2);

  for (int mode = 0; mode < 6; ++mode) {
    if (mode == 3) {
      auto *midSpacer = new QWidget;
      midSpacer->setFixedWidth(48);
      distributeBtnRow->addWidget(midSpacer);
    }
    auto *button = new QPushButton;
    button->setObjectName(QString("distribute/%1").arg(mode));
    button->setFixedSize(26, 22);
    button->setIconSize(QSize(18, 18));
    button->setStyleSheet(
        "QPushButton { background: transparent; border: 1px solid transparent; border-radius: 3px; padding: 0; } "
        "QPushButton:hover { background: #2A2A2A; border: 1px solid #444444; } "
        "QPushButton:pressed { background: #202020; border: 1px solid #666666; }");
    QString label = QStringList{"Distribute Left Edges", "Distribute Horizontal Centers", "Distribute Right Edges", "Distribute Top Edges", "Distribute Vertical Centers", "Distribute Bottom Edges"}[mode];
    button->setAccessibleName(label);
    button->setToolTip(label + " · Ctrl+click at least 3 layer names in the timeline");
    auto makeDistributePixmap = [&](const QColor &lineCol, const QColor &boxCol) {
      QPixmap icon(18, 18);
      icon.fill(Qt::transparent);
      QPainter painter(&icon);
      painter.setRenderHint(QPainter::Antialiasing);
      if (mode >= 3) { painter.translate(18, 0); painter.rotate(90); }
      const int edge = mode % 3;

      const double bw = 4.5;
      const double bh1 = 10.5, by1 = 3.5;
      const double bh2 = 7.0,  by2 = 5.5;
      const double bx1 = 2.0,  bx2 = 11.5;

      painter.setPen(Qt::NoPen);
      painter.setBrush(boxCol);
      painter.drawRect(QRectF(bx1, by1, bw, bh1));
      painter.drawRect(QRectF(bx2, by2, bw, bh2));

      const double lx1 = (edge == 0) ? bx1 : (edge == 1) ? bx1 + bw / 2.0 : bx1 + bw;
      const double lx2 = (edge == 0) ? bx2 : (edge == 1) ? bx2 + bw / 2.0 : bx2 + bw;

      painter.setPen(QPen(lineCol, 1.8));
      painter.drawLine(QPointF(lx1, 1.5), QPointF(lx1, 16.5));
      painter.drawLine(QPointF(lx2, 1.5), QPointF(lx2, 16.5));

      return icon;
    };
    QIcon distIcon;
    distIcon.addPixmap(makeDistributePixmap(QColor("#E2E2E2"), QColor("#E2E2E2")), QIcon::Normal);
    distIcon.addPixmap(makeDistributePixmap(QColor("#FFFFFF"), QColor("#FFFFFF")), QIcon::Active);
    button->setIcon(ui_theme::themedIcon(distIcon));
    distributeBtnRow->addWidget(button);
    connect(button, &QPushButton::clicked, this, [=] {
      struct Item { int index; double coordinate; };
      std::vector<Item> items;
      bool horizontal = mode < 3;
      for (int index : alignSelection) {
        if (index < 0 || index >= int(scene.layers.size())) continue;
        auto &l = scene.layers[index];
        double t = scene.frame - l.start;
        if (t < 0 || t >= l.duration) continue;
        QTransform tr = layerWorldTransform(l, scene, scene.frame);
        QRectF box = tr.mapRect(layerContentBounds(l, scene));
        double coordinate = horizontal
          ? (mode == 0 ? box.left() : mode == 1 ? box.center().x() : box.right())
          : (mode == 3 ? box.top() : mode == 4 ? box.center().y() : box.bottom());
        items.push_back({index, coordinate});
      }
      if (items.size() < 3) return;
      std::stable_sort(items.begin(), items.end(), [](const Item &a, const Item &b) { return a.coordinate < b.coordinate; });
      checkpoint();
      double step = (items.back().coordinate - items.front().coordinate) / (items.size() - 1);
      for (int n = 1; n < int(items.size()) - 1; ++n) {
        auto &l = scene.layers[items[n].index];
        double t = scene.frame - l.start;
        const double distance = items.front().coordinate + n * step - items[n].coordinate;
        auto delta = layerPositionDelta(l, scene, scene.frame,
            horizontal ? QPointF(distance, 0) : QPointF(0, distance));
        for (int axis : {0, 1}) {
          auto &property = l.p[axis];
          const double value = property.at(t) + (axis == 0 ? delta.x() : delta.y());
          if (property.keys.empty()) property.base = value;
          else property.set(t, value);
        }
      }
      dirty = true;
      refresh();
    });
  }
  distributeBtnRow->addStretch(1);
  alignPanelLayout->addLayout(distributeBtnRow);

  auto *anchorHeader = new QLabel("ANCHOR POINT");
  anchorHeader->setStyleSheet("color: #8E8E8E; font-size: 10px; font-weight: 700; letter-spacing: 0.5px; margin-top: 6px;");
  alignPanelLayout->addWidget(anchorHeader);

  auto *anchorRow = new QHBoxLayout;
  anchorRow->setContentsMargins(0, 0, 0, 0);
  anchorRow->setSpacing(12);

  auto *anchorGrid = new QWidget;
  auto *anchorGridLayout = new QGridLayout(anchorGrid);
  anchorGridLayout->setContentsMargins(0, 0, 0, 0);
  anchorGridLayout->setHorizontalSpacing(2);
  anchorGridLayout->setVerticalSpacing(2);

  for (int spot = 0; spot < 9; ++spot) {
    const int column = spot % 3, row = spot / 3;
    auto *button = new QPushButton;
    button->setObjectName(QString("anchorAlign/%1").arg(spot));
    button->setFixedSize(26, 22);
    button->setIconSize(QSize(18, 18));
    button->setStyleSheet(
        "QPushButton { background: transparent; border: 1px solid transparent; border-radius: 3px; padding: 0; } "
        "QPushButton:hover { background: #2A2A2A; border: 1px solid #444444; } "
        "QPushButton:pressed { background: #202020; border: 1px solid #666666; }");
    const QString label =
        QStringList{"Top Left", "Top Center", "Top Right", "Middle Left", "Center",
                    "Middle Right", "Bottom Left", "Bottom Center", "Bottom Right"}[spot];
    button->setAccessibleName("Anchor " + label);
    button->setToolTip("Anchor Point to " + label + " · the layer stays where it is");
    auto makeAnchorPixmap = [&](const QColor &boxCol, const QColor &dotCol) {
      QPixmap icon(18, 18);
      icon.fill(Qt::transparent);
      QPainter painter(&icon);
      painter.setRenderHint(QPainter::Antialiasing);
      painter.setPen(QPen(boxCol, 1.2));
      painter.setBrush(Qt::NoBrush);
      const QRectF box(3.0, 3.0, 12, 12);
      painter.drawRect(box);
      painter.setPen(Qt::NoPen);
      painter.setBrush(dotCol);
      const QPointF dot(column == 0 ? box.left() : column == 1 ? box.center().x() : box.right(),
                        row == 0 ? box.top() : row == 1 ? box.center().y() : box.bottom());
      painter.drawEllipse(dot, 2.0, 2.0);
      return icon;
    };
    QIcon anchorIcon;
    anchorIcon.addPixmap(makeAnchorPixmap(QColor("#AAAAAA"), QColor("#E2E2E2")), QIcon::Normal);
    anchorIcon.addPixmap(makeAnchorPixmap(QColor("#FFFFFF"), QColor("#FFFFFF")), QIcon::Active);
    button->setIcon(ui_theme::themedIcon(anchorIcon));
    anchorGridLayout->addWidget(button, row, column);
    anchorAlignButtons.push_back(button);
    connect(button, &QPushButton::clicked, this, [=] {
      std::vector<int> targets;
      for (int index : alignSelection) {
        if (index < 0 || index >= int(scene.layers.size())) continue;
        const auto &l = scene.layers[index];
        const double t = scene.frame - l.start;
        if (t < 0 || t >= l.duration || l.type == "camera" || l.type == "light" || l.type == "empty") continue;
        targets.push_back(index);
      }
      if (targets.empty()) return;
      checkpoint();
      for (int index : targets) {
        auto &l = scene.layers[index];
        const double t = scene.frame - l.start;
        const QRectF box = layerContentBounds(l, scene);
        if (box.isEmpty()) continue;
        const QPointF wanted(
            column == 0 ? box.left() : column == 1 ? box.center().x() : box.right(),
            row == 0 ? box.top() : row == 1 ? box.center().y() : box.bottom());
        const QTransform world = layerWorldTransform(l, scene, scene.frame);
        const QPointF anchor(l.p[AnchorX].at(t), l.p[AnchorY].at(t));
        const auto shift = layerPositionDelta(l, scene, scene.frame,
                                              world.map(wanted) - world.map(anchor));
        auto set = [&](int axis, double value) {
          auto &property = l.p[axis];
          if (property.keys.empty()) property.base = value;
          else property.set(t, value);
        };
        const QPointF position = layerLocalPosition(l, t);
        set(AnchorX, wanted.x());
        set(AnchorY, wanted.y());
        set(0, position.x() + shift.x());
        set(1, position.y() + shift.y());
      }
      dirty = true;
      refresh();
    });
  }
  anchorRow->addWidget(anchorGrid);

