  struct ShapeSettingsGroup {
    QWidget *container = nullptr;
    QFormLayout *form = nullptr;
    QToolButton *disclosure = nullptr;
  };
  auto makeShapeGroup = [&](const QString &title, const QString &key, bool initiallyOpen) {
    auto *container = new QWidget(shapeProperties);
    container->setObjectName("shapeGroup/" + key);
    auto *groupLayout = new QVBoxLayout(container);
    groupLayout->setContentsMargins(0, 0, 0, 0);
    groupLayout->setSpacing(2);

    // The kit's heading (effect_ui.h): the same folds as Effect Setting.
    auto *disclosure = new FxFold(title, container);
    disclosure->setObjectName("shapeDisclosure/" + key);

    const QString setting = "shapeSettingsGroups/" + key;
    const bool open = QSettings("Wavy-Flo", "Wavy-Flo").value(setting, initiallyOpen).toBool();
    auto *content = new QWidget(container);
    auto *form = new QFormLayout(content);
    form->setContentsMargins(10, 2, 0, 4);
    form->setProperty("fxGuide", true); // its lines tied to its heading
    form->setFieldGrowthPolicy(QFormLayout::AllNonFixedFieldsGrow);
    disclosure->setChecked(open);
    content->setVisible(open);
    connect(disclosure, &QToolButton::toggled, this, [=](bool expanded) {
      content->setVisible(expanded);
      QSettings("Wavy-Flo", "Wavy-Flo").setValue(setting, expanded);
    });
    groupLayout->addWidget(disclosure);
    groupLayout->addWidget(content);
    return ShapeSettingsGroup{container, form, disclosure};
  };
  auto appearanceGroup = makeShapeGroup("Appearance & Geometry", "Appearance Geometry", true);
  auto *shapeAppearanceGroup = appearanceGroup.container;
  auto *shapeAppearanceForm = appearanceGroup.form;
  shapeLayout->addWidget(shapeAppearanceGroup);
  auto *shapeFillColor = fxSwatch();
  shapeFillColor->setObjectName("shapeProperty/Fill Color");
  auto *shapeStrokeColor = fxSwatch();
  shapeStrokeColor->setObjectName("shapeProperty/Stroke Color");
  shapeAppearanceForm->addRow("Fill Color", shapeFillColor);
  shapeAppearanceForm->addRow("Stroke Color", shapeStrokeColor);
  auto *shapeStroke = new ScrubSpin;
  shapeStroke->setObjectName("shapeProperty/Stroke Width");
  shapeStroke->setRange(0, 1000);
  shapeStroke->setDecimals(2);
  shapeStroke->setSingleStep(.1);
  shapeStroke->setSuffix(" px");
  shapeAppearanceForm->addRow("Stroke Width", shapeStroke);
  auto *shapeAlignment = new FxChoice;
  shapeAlignment->setObjectName("shapeProperty/Stroke Alignment");
  shapeAlignment->addItems({"Inside", "Outside", "Center"});
  shapeAppearanceForm->addRow("Stroke Align", shapeAlignment);
  auto *shapeCap = new FxChoice;
  shapeCap->setObjectName("shapeProperty/Line Cap");
  shapeCap->addItems({"Round", "Flat"});
  shapeAppearanceForm->addRow("Line Cap", shapeCap);

  struct ShapePropertyControl {
    QPointer<QDoubleSpinBox> spin;
    QPointer<QFormLayout> form;
    int property = 0;
    QStringList kinds;
  };
  auto shapeControls = std::make_shared<std::vector<ShapePropertyControl>>();
  auto addShapeNumber = [&](QFormLayout *form, const QString &label, int propertyIndex, double minimum,
                            double maximum, double step, QStringList kinds) {
    auto *spin = new ScrubSpin;
    spin->setObjectName("shapeProperty/" + label);
    spin->setRange(minimum, maximum);
    spin->setSingleStep(step);
    spin->setDecimals(step < 1 ? 2 : 0);
    if (label == "Width" || label == "Height" || label.contains("Radius")) spin->setSuffix(" px");
    else if (label == "Start" || label == "End") spin->setSuffix(" %");
    else if (label == "Offset") spin->setSuffix("°");
    else if (label == "Round Corners" || label == "Zig Zag Size" || label == "Offset Path") spin->setSuffix(" px");
    else if (label == "Pucker & Bloat") spin->setSuffix(" %");
    else if (label == "Twist") spin->setSuffix("°");
    else if (label == "Extrude Depth") spin->setSuffix(" px");
    else if (label == "Extrude Shade") spin->setSuffix(" %");
    else if (label == "Extrude Bevel") spin->setSuffix(" px");
    else if (label == "Extrude Bevel Roundness") spin->setSuffix(" %");
    form->addRow(label, spin);
    shapeControls->push_back({spin, form, propertyIndex, std::move(kinds)});
    connect(spin, &QDoubleSpinBox::valueChanged, this, [this, propertyIndex](double value) {
      if (syncing || !layer() || layer()->type != "shape") return;
      checkpoint();
      setValue(propertyIndex, value);
    });
  };
  addShapeNumber(shapeAppearanceForm, "Width", ShapeWidth, .01, 100000, 1, {"rect", "circle"});
  addShapeNumber(shapeAppearanceForm, "Height", ShapeHeight, .01, 100000, 1, {"rect", "circle"});
  addShapeNumber(shapeAppearanceForm, "Roundness", ShapeRoundness, 0, 100000, 1, {"rect", "polygon", "star"});
  addShapeNumber(shapeAppearanceForm, "Points", ShapePoints, 1, 1000, 1, {"polygon", "star"});
  addShapeNumber(shapeAppearanceForm, "Outer Radius", OuterRadius, .01, 100000, 1, {"polygon", "star"});
  addShapeNumber(shapeAppearanceForm, "Inner Radius", InnerRadius, 0, 100000, 1, {"star"});
  addShapeNumber(shapeAppearanceForm, "Path Rotation", PathRotation, -3600, 3600, .1, {"polygon", "star"});
  auto trimGroup = makeShapeGroup("Trim Path", "Trim Path", false);
  auto *shapeTrimGroup = trimGroup.container;
  auto *shapeTrimForm = trimGroup.form;
  shapeLayout->addWidget(shapeTrimGroup);
  const QStringList allShapeKinds{"rect", "circle", "polygon", "star", "path"};
  addShapeNumber(shapeTrimForm, "Start", ShapeTrimStart, 0, 100, .1, allShapeKinds);
  addShapeNumber(shapeTrimForm, "Offset", ShapeTrimOffset, -360, 360, .1, allShapeKinds);
  addShapeNumber(shapeTrimForm, "End", ShapeTrimEnd, 0, 100, .1, allShapeKinds);
  // Modifiers: reshape any shape, curves or not, one after the other, each a
