  auto modifierGroup = makeShapeGroup("Modifiers", "Modifiers", false);
  auto *shapeModifierGroup = modifierGroup.container;
  auto *shapeModifierForm = modifierGroup.form;
  shapeLayout->addWidget(shapeModifierGroup);
  addShapeNumber(shapeModifierForm, "Round Corners", ShapeRoundCorners, 0, 100000, 1, allShapeKinds);
  addShapeNumber(shapeModifierForm, "Pucker & Bloat", ShapePuckerBloat, -200, 200, 1, allShapeKinds);
  addShapeNumber(shapeModifierForm, "Zig Zag Size", ShapeZigZagSize, -1000, 1000, 1, allShapeKinds);
  addShapeNumber(shapeModifierForm, "Zig Zag Ridges", ShapeZigZagRidges, 0, 100, .5, allShapeKinds);
  addShapeNumber(shapeModifierForm, "Twist", ShapeTwist, -3600, 3600, 1, allShapeKinds);
  addShapeNumber(shapeModifierForm, "Offset Path", ShapeOffsetPath, -1000, 1000, 1, allShapeKinds);
  // 3D Extrude: depth for the outline, as a property of the layer like Trim Path.
  // It needs a 3D layer, so giving it any depth turns 3D on.
  auto extrudeGroup = makeShapeGroup("3D Extrude", "3D Extrude", false);
  shapeLayout->addWidget(extrudeGroup.container);
  addShapeNumber(extrudeGroup.form, "Extrude Depth", ExtrudeDepth, 0, 100000, 1, allShapeKinds);
  addShapeNumber(extrudeGroup.form, "Extrude Shade", ExtrudeShade, 0, 100, 1, allShapeKinds);
  addShapeNumber(extrudeGroup.form, "Extrude Bevel", ExtrudeBevel, 0, 100000, 1, allShapeKinds);
  addShapeNumber(extrudeGroup.form, "Extrude Bevel Roundness", ExtrudeBevelRound, 0, 100, 1, allShapeKinds);
  auto *shapePathHint = new QLabel("Use the Pen tool to edit this path's points.");
  shapePathHint->setObjectName("shapeProperty/Path Hint");
  shapePathHint->setWordWrap(true);
  shapePathHint->setStyleSheet("color:#9090A8;font-size:10px;");
  shapeAppearanceForm->addRow(shapePathHint);
  shapeLayout->addStretch();
  auto *shapePropertiesTab = addPropTab(panelScroll(shapeProperties), "Shape Settings", "rect");

  auto *maskProperties = new QWidget;
