  blurRowLayout->addWidget(lensBlurLevel);
  blurSectionLayout->addWidget(blurRow);
  auto *blurHint = new QLabel(
      "100% is exactly what the lens gives. Below holds the softness back without changing the f-stop; above "
      "pushes it past what the optics ask for.");
  blurHint->setWordWrap(true);
  blurHint->setStyleSheet("color:#9090A8;font-size:10px;");
  blurSectionLayout->addWidget(blurHint);
