  lightNumber(lampGroup.form, "Cone Angle", LightConeAngle, 1, 180, "\u00b0");
  lightNumber(lampGroup.form, "Cone Feather", LightConeFeather, 0, 100, " %");
  auto *lightFalloffBox = new FxChoice;
