  lightFalloffBox->setItemData(0, "As strong however far it reaches", Qt::ToolTipRole);
  lightFalloffBox->setItemData(1, "Whole within Radius, then fading out over Falloff Distance", Qt::ToolTipRole);
  lightFalloffBox->setItemData(2, "Whole within Radius, then weaker with the square of the distance, like a real lamp",
                               Qt::ToolTipRole);
  lampGroup.form->addRow("Falloff", lightFalloffBox);
  lightNumber(lampGroup.form, "Radius", LightRadius, 0, 100000, " px");
  lightNumber(lampGroup.form, "Falloff Distance", LightFalloffDistance, 1, 100000, " px");
  // Shadows: thrown by the 3D layers whose own Casts shadows is on.
  auto *lightShadowsBox = new QCheckBox("Casts shadows");
  lightShadowsBox->setObjectName("light/Casts Shadows");
  lightShadowsBox->setToolTip("Layers in this light's way throw shadows -- those whose Casts shadows is on, under Surface");
  lampGroup.form->addRow(lightShadowsBox);
  lightNumber(lampGroup.form, "Shadow Darkness", LightShadowDarkness, 0, 100, " %");
  lightNumber(lampGroup.form, "Shadow Softness", LightShadowSoftness, 0, 500, " px");
  auto aimGroup = makeShapeGroup("Aim", "Light Aim", true);
  lightLayout->addWidget(aimGroup.container);
  lightNumber(aimGroup.form, "Aim X", LightAimX, -100000, 100000, " px");
  lightNumber(aimGroup.form, "Aim Y", LightAimY, -100000, 100000, " px");
  lightNumber(aimGroup.form, "Aim Z", LightAimZ, -100000, 100000, " px");
  auto *aimMiddle = new QPushButton("Aim at the middle of the frame");
  aimMiddle->setObjectName("light/Aim Middle");
  aimGroup.form->addRow(aimMiddle);
  auto *aimSelected = new FxChoice;
  aimSelected->setObjectName("light/Aim At Layer");
  aimSelected->setToolTip("Points the light at where a layer is now");
  aimGroup.form->addRow("Aim at", aimSelected);
  auto *lampHint = new QLabel(
      "A light reaches 3D layers only. Where none of its light falls a layer goes dark, as it would in a room: "
      "an Ambient light lifts what the others leave in shadow.");
  lampHint->setObjectName("light/Hint");
  lampHint->setWordWrap(true);
  lampHint->setStyleSheet("color:#9090A8;font-size:10px;");
  lightLayout->addWidget(lampHint);
  auto surfaceGroup = makeShapeGroup("Surface", "Light Surface", true);
  lightLayout->addWidget(surfaceGroup.container);
  auto *takesLight = new QCheckBox("Lit by the scene's lights");
  takesLight->setObjectName("light/Takes Light");
  surfaceGroup.form->addRow(takesLight);
  lightNumber(surfaceGroup.form, "Shine", SurfaceShine, 0, 100, " %");
  lightNumber(surfaceGroup.form, "Gloss", SurfaceGloss, 0, 100, " %");
  auto *castsShadowsBox = new QCheckBox("Casts shadows");
  castsShadowsBox->setObjectName("light/Layer Casts Shadows");
  castsShadowsBox->setToolTip("This layer throws a shadow on the 3D layers behind it, from every light whose Casts shadows is on");
  surfaceGroup.form->addRow(castsShadowsBox);
  auto *surfaceHint = new QLabel;
  surfaceHint->setObjectName("light/Surface Hint");
  surfaceHint->setWordWrap(true);
  surfaceHint->setStyleSheet("color:#9090A8;font-size:10px;");
  surfaceGroup.form->addRow(surfaceHint);
  lightLayout->addStretch();
  addPropTab(panelScroll(lightProperties), "Light", "light");
  connect(lightKindBox, &QComboBox::currentIndexChanged, this, [this](int index) {
    if (syncing || !layer() || layer()->type != "light" || index < 0 || layer()->lightKind == index) return;
    checkpoint();
    layer()->lightKind = index;
    dirty = true;
    refresh(true);
  });
  connect(lightFalloffBox, &QComboBox::currentIndexChanged, this, [this](int index) {
    if (syncing || !layer() || layer()->type != "light" || index < 0 || layer()->lightFalloff == index) return;
    checkpoint();
    layer()->lightFalloff = index;
    dirty = true;
    refresh(true);
  });
  connect(lightColour, &QPushButton::clicked, this, [this] {
    if (!layer() || layer()->type != "light") return;
    const QString id = layer()->id;
    pickColorLive(layer()->color, "Light Color", false, [this, id](const QColor &colour) {
      if (!layer() || layer()->id != id) return;
      checkpoint();
      layer()->color = colour;
      dirty = true;
      refresh();
    });
  });
  auto aimAt = [this](QPointF where, double z) {
    if (!layer() || layer()->type != "light") return;
    checkpoint();
    setValue(LightAimX, where.x());
    setValue(LightAimY, where.y());
    setValue(LightAimZ, z);
  };
  connect(aimMiddle, &QPushButton::clicked, this, [this, aimAt] { aimAt(QPointF(scene.width / 2., scene.height / 2.), 0); });
  connect(aimSelected, &QComboBox::activated, this, [this, aimAt, aimSelected](int index) {
    const QString id = aimSelected->itemData(index).toString();
    for (const auto &other : scene.layers)
      if (other.id == id) {
        const double t = scene.frame - other.start;
        const QVector3D where = layerWorldMatrix(other, scene, scene.frame)
                                    .map(QVector3D(float(other.p[AnchorX].at(t)), float(other.p[AnchorY].at(t)),
                                                   float(other.threeD ? other.p[AnchorZ].at(t) : 0.)));
        aimAt(QPointF(where.x(), where.y()), where.z());
      }
    QSignalBlocker block(aimSelected);
    aimSelected->setCurrentIndex(0);
  });
  connect(takesLight, &QCheckBox::toggled, this, [this](bool on) {
    if (syncing || !layer() || !layerCanBeLit(*layer()) || layer()->acceptsLights == on) return;
    checkpoint();
    layer()->acceptsLights = on;
    dirty = true;
    refresh(true);
  });
  connect(lightShadowsBox, &QCheckBox::toggled, this, [this](bool on) {
    if (syncing || !layer() || layer()->type != "light" || layer()->lightShadows == on) return;
    checkpoint();
    layer()->lightShadows = on;
    dirty = true;
    refresh(true);
  });
  connect(castsShadowsBox, &QCheckBox::toggled, this, [this](bool on) {
    if (syncing || !layer() || !layerCanBeLit(*layer()) || layer()->castsShadows == on) return;
    checkpoint();
    layer()->castsShadows = on;
    dirty = true;
    refresh(true);
  });
  refreshLightPanel = [this, lampGroup, aimGroup, surfaceGroup, lampHint, lightControls, lightKindBox, lightFalloffBox,
                       lightShadowsBox, castsShadowsBox,
                       lightColour, takesLight, surfaceHint, aimSelected] {
    Layer *l = layer();
    const bool isLight = l && l->type == "light";
    const bool surface = l && layerCanBeLit(*l);
    const int kind = isLight ? std::clamp(l->lightKind, 0, 3) : 0;
    lampGroup.container->setVisible(isLight);
    aimGroup.container->setVisible(isLight && (kind == LightSpot || kind == LightSun));
    lampHint->setVisible(isLight);
    surfaceGroup.container->setVisible(surface);
    if (!isLight && !surface) return;
    const double time = scene.frame - l->start;
    for (auto &control : *lightControls) {
      if (!control.spin) continue;
      const bool surfaceControl = control.property == SurfaceShine || control.property == SurfaceGloss;
      const bool own = surfaceControl ? surface : isLight;
      if (!own) continue;
      QSignalBlocker block(control.spin);
      const double value = l->p[size_t(control.property)].at(time);
      if (std::abs(control.spin->value() - value) > 1e-9) control.spin->setValue(value);
      if (surfaceControl) control.spin->setEnabled(l->acceptsLights);
      bool shown = true;
      if (control.property == LightConeAngle || control.property == LightConeFeather) shown = kind == LightSpot;
      if (control.property == LightRadius) shown = (kind == LightPoint || kind == LightSpot) && l->lightFalloff != 0;
      if (control.property == LightFalloffDistance) shown = (kind == LightPoint || kind == LightSpot) && l->lightFalloff == 1;
      if (control.property == LightShadowDarkness || control.property == LightShadowSoftness)
        shown = kind != LightAmbient && l->lightShadows;
      if (control.form) control.form->setRowVisible(control.spin.data(), shown);
    }
    if (isLight) {
      QSignalBlocker blockKind(lightKindBox), blockFalloff(lightFalloffBox);
      if (lightKindBox->currentIndex() != kind) lightKindBox->setCurrentIndex(kind);
      if (lightFalloffBox->currentIndex() != l->lightFalloff) lightFalloffBox->setCurrentIndex(std::clamp(l->lightFalloff, 0, 2));
      lampGroup.form->setRowVisible(lightFalloffBox, kind == LightPoint || kind == LightSpot);
      {
        QSignalBlocker block(lightShadowsBox);
        lightShadowsBox->setChecked(l->lightShadows);
      }
      lampGroup.form->setRowVisible(lightShadowsBox, kind != LightAmbient); // ambient light comes from nowhere
      const QColor colour = l->color.isValid() ? l->color : QColor(Qt::white);
      lightColour->setToolTip(colour.name().toUpper());
      setStyleIfChanged(lightColour, fxSwatchStyle(colour));
      QStringList wanted{QString()};
      for (const auto &other : scene.layers)
        if (other.id != l->id && particlesFitLayer(other)) wanted << other.id;
      QStringList have;
      for (int i = 0; i < aimSelected->count(); ++i) have << aimSelected->itemData(i).toString();
      if (have != wanted) {
        QSignalBlocker block(aimSelected);
        aimSelected->clear();
        aimSelected->addItem("Choose a layer\u2026", QString());
        for (const auto &other : scene.layers)
          if (other.id != l->id && particlesFitLayer(other)) aimSelected->addItem(other.name, other.id);
      }
    }
    if (surface) {
      QSignalBlocker block(takesLight), blockCasts(castsShadowsBox);
      takesLight->setChecked(l->acceptsLights);
      castsShadowsBox->setChecked(l->castsShadows);
      int lights = 0, shadowing = 0;
      for (const auto &other : scene.layers) {
        lights += other.type == "light" && other.visible;
        shadowing += other.type == "light" && other.visible && other.lightShadows && other.lightKind != LightAmbient;
      }
      const QString text =
          lights == 0 ? QString("No light in this Main yet: add one with Layer \u2192 Add Light. Until then this layer is "
                                "drawn as it always was.")
          : !l->acceptsLights ? QString("This layer ignores the lights and is drawn as it always was.")
          : QString("Lit by %1 light%2. Shine is how strong the highlight is where a light glances off towards the "
                    "camera; Gloss how small and sharp it is.").arg(lights).arg(lights == 1 ? "" : "s") +
                (l->castsShadows && shadowing == 0
                     ? QString(" No light casts shadows yet: tick Casts shadows on one to see this layer's shadow.")
                     : QString());
      if (surfaceHint->text() != text) surfaceHint->setText(text);
    }
  };

  // Particles: what a particle layer gives off, how it moves and how it looks.
  // The sliders that can be keyframed are the layer's own properties, and show
  // in the timeline under Particles; the rest are settings kept with the layer.
  auto *particleProperties = new QWidget;
  particleProperties->setObjectName("particleProperties");
  auto *particleLayout = new QVBoxLayout(particleProperties);
  particleLayout->setContentsMargins(12, 12, 12, 12);
  particleLayout->setSpacing(8);
  auto *particleHeading = new QLabel("Particles");
  particleHeading->setStyleSheet(
      "color:#9090A8;font-size:10px;font-weight:700;letter-spacing:1.4px;"
      "text-transform:uppercase;padding:0 0 5px 0;");
  particleLayout->addWidget(particleHeading);
  auto *particlePreset = new FxChoice;
  particlePreset->setObjectName("particle/Preset");
  particlePreset->addItem("Start from a preset\u2026");
  particlePreset->addItems(particlePresetNames());
  particlePreset->setToolTip("Replaces this layer's particle settings with a ready-made look");
  particlePreset->setMaximumWidth(260);
  // Particles on this layer: a particle layer always has them; any other
  // layer that draws something can give them off too, over what it draws.
  auto *particleEmit = fxCheck();
  particleEmit->setObjectName("particle/Enabled");
  // A line of the kit, like every other switch: its name, then its box.
  auto *particleEmitLine = new QWidget;
  auto *particleEmitForm = new QFormLayout(particleEmitLine);
  particleEmitForm->setContentsMargins(0, 0, 0, 0);
  particleEmitForm->addRow("Emit Particles", particleEmit);
  particleEmit->setToolTip("Emit particles from this layer, over what it draws");
  particleLayout->insertWidget(particleLayout->indexOf(particleHeading) + 1, particleEmitLine);
  particleLayout->addWidget(particlePreset, 0, Qt::AlignLeft);
  auto particleSections = std::make_shared<std::vector<QPointer<QWidget>>>();
  particleSections->push_back(particlePreset);
  struct ParticleControl {
    QPointer<QWidget> widget;
    QByteArray key;    // a setting kept with the layer...
    int property = -1; // ...or one of its keyframeable properties
    int kind = 0;      // 0 number, 1 list, 3 colour
    QPointer<QFormLayout> form;
  };
  auto particleControls = std::make_shared<std::vector<ParticleControl>>();
  auto particleGroup = [&](const QString &title, bool open) {
    auto group = makeShapeGroup(title, "Particles " + title, open);
    particleLayout->addWidget(group.container);
    particleSections->push_back(group.container);
    return group.form;
  };
  auto particleNumber = [&](QFormLayout *form, const QString &label, int propertyIndex, const char *key, double minimum,
                            double maximum, double step, const QString &suffix) {
    auto *spin = new ScrubSpin;
    spin->setObjectName("particle/" + label);
    spin->setRange(minimum, maximum);
    spin->setSingleStep(step);
    spin->setDecimals(step < 1 ? 2 : 0);
    spin->setSuffix(suffix);
    form->addRow(label, spin);
    particleControls->push_back({spin, QByteArray(key), propertyIndex, 0, form});
    connect(spin, &QDoubleSpinBox::valueChanged, this, [this, propertyIndex, setting = QString::fromLatin1(key)](double value) {
      if (syncing || !layer() || !layerEmitsParticles(*layer())) return;
      checkpoint();
      if (propertyIndex >= 0) { setValue(propertyIndex, value); return; }
      layer()->particles[setting] = value;
      dirty = true;
      refresh();
    });
  };
  auto particleChoice = [&](QFormLayout *form, const QString &label, const char *key, const QStringList &items) {
    auto *combo = new FxChoice;
    combo->setObjectName("particle/" + label);
    combo->addItems(items);
    form->addRow(label, combo);
    particleControls->push_back({combo, QByteArray(key), -1, 1, form});
    connect(combo, &QComboBox::currentIndexChanged, this, [this, setting = QString::fromLatin1(key)](int index) {
      if (syncing || !layer() || !layerEmitsParticles(*layer()) || index < 0) return;
      checkpoint();
      layer()->particles[setting] = index;
      dirty = true;
      refresh();
    });
  };
  auto particleColour = [&](QFormLayout *form, const QString &label, const char *key) {
    auto *button = fxSwatch();
    button->setObjectName("particle/" + label);
    form->addRow(label, button);
    particleControls->push_back({button, QByteArray(key), -1, 3, form});
    connect(button, &QPushButton::clicked, this, [this, label, setting = QByteArray(key)] {
      if (!layer() || !layerEmitsParticles(*layer())) return;
      const QString id = layer()->id;
      pickColorLive(particleColor(*layer(), setting.constData()), "Particle " + label, false,
                    [this, id, setting](const QColor &colour) {
                      if (!layer() || layer()->id != id) return;
                      checkpoint();
                      layer()->particles[QString::fromLatin1(setting)] = colour.name();
                      dirty = true;
                      refresh();
                    });
    });
  };
  auto *emitterForm = particleGroup("Emitter", true);
  particleChoice(emitterForm, "Emitter", "emitter", {"Point", "Line", "Box", "Disc", "Ring", "Layer area"});
  particleNumber(emitterForm, "Emitter Width", -1, "emitterWidth", 0, 100000, 1, " px");
  particleNumber(emitterForm, "Emitter Height", -1, "emitterHeight", 0, 100000, 1, " px");
  particleNumber(emitterForm, "Emission Rate", ParticleRate, "", 0, 20000, 1, " /s");
  particleNumber(emitterForm, "Burst", -1, "burst", 0, 20000, 1, "");
  particleNumber(emitterForm, "Particle Life", ParticleLife, "", .05, 600, .1, " s");
  particleNumber(emitterForm, "Life Variance", -1, "lifeVariance", 0, 90, 1, " %");
  particleNumber(emitterForm, "Pre-roll", -1, "preroll", 0, 30, .5, " s");
  particleNumber(emitterForm, "Max Particles", -1, "maxParticles", 1, 20000, 100, "");
  particleNumber(emitterForm, "Seed", -1, "seed", 0, 99999, 1, "");
  auto *motionForm = particleGroup("Motion", true);
  particleNumber(motionForm, "Particle Speed", ParticleSpeed, "", 0, 20000, 1, " px/s");
  particleNumber(motionForm, "Speed Variance", -1, "speedVariance", 0, 100, 1, " %");
  particleNumber(motionForm, "Direction", ParticleDirection, "", -3600, 3600, 1, "\u00b0");
  particleNumber(motionForm, "Spread", ParticleSpread, "", 0, 360, 1, "\u00b0");
  particleNumber(motionForm, "Gravity", ParticleGravity, "", -20000, 20000, 1, " px/s\u00b2");
  particleNumber(motionForm, "Wind", ParticleWind, "", -20000, 20000, 1, " px/s\u00b2");
  particleNumber(motionForm, "Drag", -1, "drag", 0, 20, .1, "");
  particleNumber(motionForm, "Turbulence", ParticleTurbulence, "", 0, 5000, 1, " px");
  particleNumber(motionForm, "Wobble Speed", -1, "turbulenceFrequency", 0, 20, .05, " /s");
  // In depth, on a 3D layer: the particles spread front to back and seen
  // through the camera one by one, a 3D layer among them standing between.
  particleNumber(motionForm, "Depth", -1, "depth", 0, 100000, 10, " px");
  particleNumber(motionForm, "Z Speed", -1, "speedZ", -20000, 20000, 1, " px/s");
  particleChoice(motionForm, "Space", "space", {"World: leaves a trail", "Layer: moves with it"});
  auto *lookForm = particleGroup("Look", true);
  particleChoice(lookForm, "Particle Shape", "shape", {"Soft Dot", "Circle", "Square", "Streak", "Petal", "Star", "Bokeh", "Confetti"});
  particleNumber(lookForm, "Particle Size", ParticleSize, "", 0, 5000, .5, " px");
  particleNumber(lookForm, "Size Variance", -1, "sizeVariance", 0, 100, 1, " %");
  particleNumber(lookForm, "Size at End", -1, "sizeEnd", 0, 1000, 1, " %");
  particleNumber(lookForm, "Spin", ParticleSpin, "", -36000, 36000, 1, "\u00b0/s");
  particleChoice(lookForm, "Start Angle", "randomRotation", {"Upright", "Random"});
  particleColour(lookForm, "Start Color", "colorStart");
  particleColour(lookForm, "End Color", "colorEnd");
  particleNumber(lookForm, "Hue Variance", -1, "colorVariance", 0, 100, 1, " %");
  particleNumber(lookForm, "Particle Opacity", -1, "opacity", 0, 100, 1, " %");
  particleNumber(lookForm, "Opacity Variance", -1, "opacityVariance", 0, 100, 1, " %");
  particleNumber(lookForm, "Fade In", -1, "fadeIn", 0, 100, 1, " %");
  particleNumber(lookForm, "Fade Out", -1, "fadeOut", 0, 100, 1, " %");
  particleChoice(lookForm, "Blend", "blend", {"Normal", "Add (light)"});
  auto *particleHint = new QLabel(
      "Every frame is worked out from time alone, so scrubbing, jumping and rendering on every core give the same "
      "picture. Emission Rate, Life, Speed, Direction, Spread, Size, Gravity, Wind, Turbulence and Spin can be "
      "keyframed in the timeline under Particles.");
  particleHint->setWordWrap(true);
  particleHint->setStyleSheet("color:#9090A8;font-size:10px;");
  particleLayout->addWidget(particleHint);
  particleSections->push_back(particleHint);
  connect(particleEmit, &QCheckBox::toggled, this, [this](bool on) {
    if (syncing || !layer() || layer()->type == "particles") return;
    checkpoint();
    Layer &l = *layer();
    l.particlesOn = on;
    // The first time, sparkles over the layer: something to see at once.
    if (on && l.particles.isEmpty()) applyParticlePreset(l, scene, "Sparkle");
    dirty = true;
    refresh(true);
  });
  particleLayout->addStretch();
  QWidget *particlePage = panelScroll(particleProperties);
  auto *particleTab = addPropTab(particlePage, "Particles", "particles");

  // Motion Tracker: points followed through a video layer, then used to carry
  // another layer along or to hold the footage still.
  auto *trackerProperties = new QWidget;
  trackerProperties->setObjectName("trackerProperties");
  auto *trackerLayout = new QVBoxLayout(trackerProperties);
  trackerLayout->setContentsMargins(12, 12, 12, 12);
  trackerLayout->setSpacing(8);
  auto *trackerHeading = new QLabel("Motion Tracker");
  trackerHeading->setStyleSheet(
      "color:#9090A8;font-size:10px;font-weight:700;letter-spacing:1.4px;"
      "text-transform:uppercase;padding:0 0 5px 0;");
  trackerLayout->addWidget(trackerHeading);
  auto *trackerEmpty = new QLabel("Select a video layer, then add a point on something in it that moves.");
  trackerEmpty->setObjectName("tracker/Empty");
  trackerEmpty->setWordWrap(true);
  trackerEmpty->setStyleSheet("color:#9090A8;font-size:10px;");
  trackerLayout->addWidget(trackerEmpty);
  auto *trackerBody = new QWidget;
  auto *trackerBodyLayout = new QVBoxLayout(trackerBody);
  trackerBodyLayout->setContentsMargins(0, 0, 0, 0);
  trackerBodyLayout->setSpacing(8);
  trackerLayout->addWidget(trackerBody);
  auto *pointRow = new QHBoxLayout;
  auto *trackPointList = new FxChoice;
  trackPointList->setObjectName("tracker/Point");
  auto *trackAdd = new QPushButton("Add Point");
  trackAdd->setObjectName("tracker/Add");
  auto *trackDelete = new QPushButton("Delete");
  trackDelete->setObjectName("tracker/Delete");
  trackPointList->setMinimumWidth(140);
  trackPointList->setMaximumWidth(240);
  pointRow->addWidget(trackPointList);
  pointRow->addWidget(trackAdd);
  pointRow->addWidget(trackDelete);
  pointRow->addStretch(1);
  trackerBodyLayout->addLayout(pointRow);
  auto *trackForm = new QFormLayout;
  setupShapeForm(trackForm);
  auto *trackFeature = new ScrubSpin;
  trackFeature->setObjectName("tracker/Feature Size");
  trackFeature->setRange(8, 400); trackFeature->setDecimals(0); trackFeature->setSuffix(" px");
  trackFeature->setToolTip("The patch that is followed: big enough to hold some clear detail");
  auto *trackSearch = new ScrubSpin;
  trackSearch->setObjectName("tracker/Search Size");
  trackSearch->setRange(12, 1200); trackSearch->setDecimals(0); trackSearch->setSuffix(" px");
  trackSearch->setToolTip("How far from where it should be the patch is looked for: larger for fast motion");
  trackForm->addRow("Feature Size", trackFeature);
  trackForm->addRow("Search Size", trackSearch);
  trackerBodyLayout->addLayout(trackForm);
  auto *trackRow = new QHBoxLayout;
  auto *trackBack = new QPushButton(QString::fromUtf8("\u25C0 Track Back"));
  trackBack->setObjectName("tracker/Back");
  auto *trackForward = new QPushButton(QString::fromUtf8("Track Forward \u25B6"));
  trackForward->setObjectName("tracker/Forward");
  auto *trackStop = new QPushButton("Stop");
  trackStop->setObjectName("tracker/Stop");
  for (auto *button : {trackBack, trackForward, trackStop}) button->setMaximumWidth(150);
  trackRow->addWidget(trackBack);
  trackRow->addWidget(trackForward);
  trackRow->addWidget(trackStop);
  trackRow->addStretch(1);
  trackerBodyLayout->addLayout(trackRow);
  auto *trackStatusLabel = new QLabel;
  trackStatusLabel->setObjectName("tracker/Status");
  trackStatusLabel->setWordWrap(true);
  trackStatusLabel->setStyleSheet("color:#C8CCD8;font-size:11px;");
  trackerBodyLayout->addWidget(trackStatusLabel);
  auto *useHeading = new QLabel("Use the track");
  useHeading->setStyleSheet("color:#9090A8;font-size:10px;font-weight:700;padding:6px 0 0 0;");
  trackerBodyLayout->addWidget(useHeading);
  auto *applyRow = new QHBoxLayout;
  auto *trackTarget = new FxChoice;
  trackTarget->setObjectName("tracker/Target");
  auto *trackApply = new QPushButton("Apply Motion");
  trackApply->setObjectName("tracker/Apply");
  trackApply->setToolTip("Keys the chosen layer's Position so it rides on the point, keeping where it is now relative to it");
  trackTarget->setMinimumWidth(140);
  trackTarget->setMaximumWidth(240);
  applyRow->addWidget(trackTarget);
  applyRow->addWidget(trackApply);
  applyRow->addStretch(1);
  trackerBodyLayout->addLayout(applyRow);
  auto *trackStabilize = new QPushButton("Stabilize This Layer");
  trackStabilize->setObjectName("tracker/Stabilize");
  trackStabilize->setToolTip("Keys this layer's Anchor so the point holds still on screen");
  trackStabilize->setMaximumWidth(240);
  trackerBodyLayout->addWidget(trackStabilize, 0, Qt::AlignLeft);
  auto *trackHint = new QLabel(
      "Put the box on something with clear detail: a corner, a pattern, an edge that turns. Drag it in the viewer "
      "to place it, then track. Apply Motion carries another layer with the point from where it stands at this "
      "frame; Stabilize moves this footage so the point stays put.");
  trackHint->setWordWrap(true);
  trackHint->setStyleSheet("color:#9090A8;font-size:10px;");
  trackerBodyLayout->addWidget(trackHint);
  trackerLayout->addStretch();
  QWidget *trackerPage = panelScroll(trackerProperties);
  addPropTab(trackerPage, "Tracker", "track");

  // Time: a video layer's own clock, slowed, sped up, held or reversed.
  auto *timeProperties = new QWidget;
  timeProperties->setObjectName("timeProperties");
  auto *timeLayout = new QVBoxLayout(timeProperties);
  timeLayout->setContentsMargins(12, 12, 12, 12);
  timeLayout->setSpacing(8);
  auto *timeHeading = new QLabel("Time");
  timeHeading->setStyleSheet(
      "color:#9090A8;font-size:10px;font-weight:700;letter-spacing:1.4px;"
      "text-transform:uppercase;padding:0 0 5px 0;");
  timeLayout->addWidget(timeHeading);
  auto *timeEmpty = new QLabel("Select a video layer to slow it down, speed it up, hold a frame or play it backwards.");
  timeEmpty->setObjectName("time/Empty");
  timeEmpty->setWordWrap(true);
  timeEmpty->setStyleSheet("color:#9090A8;font-size:10px;");
  timeLayout->addWidget(timeEmpty);
  auto *timeBody = new QWidget;
  auto *timeBodyLayout = new QVBoxLayout(timeBody);
  timeBodyLayout->setContentsMargins(0, 0, 0, 0);
  timeBodyLayout->setSpacing(8);
  timeLayout->addWidget(timeBody);
  auto *timeRemapBox = new QCheckBox("Time Remap");
  timeRemapBox->setObjectName("time/Remap");
  timeRemapBox->setToolTip("Drive the footage from the Time Remap keyframes in the timeline instead of straight on");
  timeBodyLayout->addWidget(timeRemapBox);
  auto *speedRow = new QHBoxLayout;
  auto *timeSpeed = new ScrubSpin;
  timeSpeed->setObjectName("time/Speed");
  timeSpeed->setRange(-1000, 1000); timeSpeed->setDecimals(0); timeSpeed->setSuffix(" %"); timeSpeed->setValue(50);
  timeSpeed->setToolTip("50% is half speed, 200% double; below zero plays backwards");
  auto *timeSetSpeed = new QPushButton("Set Speed");
  timeSetSpeed->setObjectName("time/SetSpeed");
  auto *speedName = new QLabel("Speed");
  speedName->setMinimumWidth(104);
  speedRow->addWidget(speedName);
