  auto setStrokeWidth = [this](double width, bool step) {
    if (syncing || !layer()) return;
    Layer &l = *layer();
    if (l.type == "shape") {
      if (step) checkpoint();
      l.strokeWidth = width;
    } else if (l.type == "text") {
      TextStrokeStyle *style = timelineTextStroke();
      if (!style && width <= 0) return;
      if (step) checkpoint();
      if (!style) {
        l.textStrokes.push_back({width, l.strokeColor, 1});
        selectedTextStroke = int(l.textStrokes.size()) - 1;
        selectedTextStrokeLayer = l.id;
      } else
        style->width = width;
      syncLegacyTextStroke(l);
    } else
      return;
    dirty = true;
    refresh();
  };
  connect(shapeStrokeWidth, &QDoubleSpinBox::valueChanged, this, [=](double width) {
    if (!syncing) setStrokeWidth(width, true);
  });
  connect(shapeStrokeMode, &QComboBox::currentIndexChanged, this, [this](int mode) {
    if (syncing || !layer() || layer()->type != "shape") return;
    checkpoint();
    layer()->strokeMode = mode;
    dirty = true;
    refresh();
  });
  connect(layerFillSwatch, &QPushButton::clicked, this, [=] {
    if (!layer()) return;
    const QString id = layer()->id;
    if (layer()->type == "text") {
      pickColorLive(layer()->color, "Text Color", false, [this, id](const QColor &c) {
        if (!layer() || layer()->id != id) return;
        changeCharacter([=](Layer &l) { l.color = c; },
                        [=](QTextCharFormat &f) { f.setForeground(c); });
      });
      return;
    }
    if (layer()->type != "fill" && layer()->type != "shape") return;
    pickColorLive(layer()->color, "Fill Color", false, [this, id](const QColor &c) {
      if (!layer() || layer()->id != id) return;
      checkpoint();
      layer()->color = c;
      dirty = true;
      refresh();
    });
  });
  connect(layerStrokeSwatch, &QPushButton::clicked, this, [=] {
    if (!layer()) return;
    const QString id = layer()->id;
    if (layer()->type == "text") {
      const TextStrokeStyle *style = timelineTextStroke();
      pickColorLive(style ? style->color : layer()->strokeColor, "Stroke Color", false, [this, id](const QColor &c) {
        if (!layer() || layer()->id != id) return;
        checkpoint();
        Layer &l = *layer();
        if (TextStrokeStyle *picked = timelineTextStroke())
          picked->color = c;
        else {
          l.textStrokes.push_back({4., c, 1});
          selectedTextStroke = int(l.textStrokes.size()) - 1;
          selectedTextStrokeLayer = l.id;
        }
        syncLegacyTextStroke(l);
        dirty = true;
        refresh();
      });
      return;
    }
    if (layer()->type != "shape") return;
    pickColorLive(layer()->strokeColor, "Stroke Color", false, [this, id](const QColor &c) {
      if (!layer() || layer()->id != id) return;
      checkpoint();
      layer()->strokeColor = c;
      dirty = true;
      refresh();
    });
  });

