void Editor::applyUiScale(int percent) {
  if (percent != 50 && percent != 75 && percent != 100 && percent != 125 && percent != 150 && percent != 200)
    percent = 100;
  const int previous = uiScalePercent;
  if (uiScaleLaidOut && previous != percent) layoutAtUiScale[previous] = saveState(16);
  uiScalePercent = percent;

  if (!qApp->arguments().contains("--self-test")) {
    QSettings settings("Wavy-Flo", "Wavy-Flo");
    settings.setValue("ui/scalePercent", percent);
  }

  // Qt grows the whole window, every panel and every painted line with it
  // (ui_scale.h), live. Everything below stays at its 100% size in
  // device-independent pixels -- written here once, not once per scale: the
  // stylesheets set again would only cost time (the window's own takes 0.66 s).
  ui_scale::apply(percent / 100.0);
  if (uiScaleLaidOut && previous != percent && layoutAtUiScale.contains(percent)) {
    restoreState(layoutAtUiScale.value(percent), 16);
    syncDockPanels(this);
  }
  const double scale = 1.0;
  if (uiScaleLaidOut) return;
  uiScaleLaidOut = true;
  int baseFontSize = std::max(8, (int)std::round(12.0 * scale));
  QFont appFont = QApplication::font();
  appFont.setPixelSize(baseFontSize);
  QApplication::setFont(appFont);
  setFont(appFont);

  setStyleSheet(ui_theme::appDarkStyle() + makeAppStylesheet(scale));

  auto *tb = findChild<QToolBar *>("prototypeToolbar");
  if (tb) {
    int iconSz = 16;
    int btnSz = std::max(14, (int)std::round(22.0 * scale));
    int barH = std::max(18, (int)std::round(26.0 * scale));
    int padY = std::max(0, (int)std::round(1.0 * scale));
    int padX = std::max(1, (int)std::round(4.0 * scale));
    int spacing = std::max(1, (int)std::round(2.0 * scale));
    int sepMarginY = std::max(1, (int)std::round(3.0 * scale));
    int sepMarginX = std::max(1, (int)std::round(3.0 * scale));

    tb->setIconSize(QSize(iconSz, iconSz));
    QString tbQss;
    QTextStream tbOut(&tbQss);
    tbOut << "QToolBar {\n"
          << "  background: #18181B;\n"
          << "  border: 0;\n"
          << "  border-bottom: 1px solid #26262B;\n"
          << "  spacing: " << spacing << "px;\n"
          << "  padding: " << padY << "px " << padX << "px;\n"
          << "  min-height: " << barH << "px;\n"
          << "  max-height: " << barH << "px;\n"
          << "}\n"
          << "QToolBar::separator {\n"
          << "  width: 1px;\n"
          << "  background: #333338;\n"
          << "  margin: " << sepMarginY << "px " << sepMarginX << "px;\n"
          << "}\n"
          << "QToolButton {\n"
          << "  background: #232328;\n"
          << "  border: 1px solid #303036;\n"
          << "  border-radius: 3px;\n"
          << "  padding: 0px;\n"
          << "  margin: 0px;\n"
          << "  min-width: " << btnSz << "px;\n"
          << "  max-width: " << btnSz << "px;\n"
          << "  min-height: " << btnSz << "px;\n"
          << "  max-height: " << btnSz << "px;\n"
          << "}\n"
          << "QToolButton:hover {\n"
          << "  background: #32323C;\n"
          << "  border: 1px solid #444450;\n"
          << "}\n"
          << "QToolButton:pressed {\n"
          << "  background: #18181D;\n"
          << "  border: 1px solid #282830;\n"
          << "}\n"
          << "QToolButton:checked {\n"
          << "  background: #162E4C;\n"
          << "  border: 1px solid #2D8CFF;\n"
          << "}\n"
          << "QToolButton:checked:hover {\n"
          << "  background: #1C3A60;\n"
          << "  border: 1px solid #4DA3FF;\n"
          << "}\n"
          << "QToolButton::menu-indicator {\n"
          << "  image: none;\n"
          << "  width: 0px;\n"
          << "}\n";
    tb->setStyleSheet(tbQss);
  }

  if (timeline) {
    timeline->applyUiScale(scale);
  }

  if (stackedPanels) {
    stackedPanels->applyUiScale(scale);
  }

  for (auto *w : findChildren<QWidget *>("customDockTitle")) {
    if (auto *dt = dynamic_cast<CustomDockTitle *>(w)) dt->applyUiScale(scale);
  }

  if (auto *footer = findChild<QWidget *>("viewerFooter")) {
    footer->setFixedHeight(std::max(20, (int)std::round(35.0 * scale)));
  }
  if (auto *fit = findChild<QPushButton *>("previewFit")) {
    fit->setFixedSize(std::max(24, (int)std::round(32.0 * scale)), std::max(16, (int)std::round(20.0 * scale)));
  }
  if (auto *res = findChild<QComboBox *>("previewResolution")) {
    res->setFixedSize(std::max(60, (int)std::round(82.0 * scale)), std::max(16, (int)std::round(20.0 * scale)));
  }
  if (auto *zoom = findChild<QWidget *>("previewZoom")) {
    zoom->setFixedWidth(std::max(36, (int)std::round(47.0 * scale)));
  }

  int vBtnW = std::max(16, (int)std::round(22.0 * scale));
  int vBtnH = std::max(14, (int)std::round(20.0 * scale));
  int vIconSz = percent == 200 ? 22 : (percent == 150 ? 18 : (percent == 125 ? 16 : (percent == 75 ? 12 : (percent == 50 ? 10 : 14))));
  for (const char *btnName : {"previewAlpha", "previewGrid", "previewSnap", "previewLayerBox"}) {
    if (auto *b = findChild<QToolButton *>(btnName)) {
      b->setFixedSize(vBtnW, vBtnH);
      b->setIconSize(QSize(vIconSz, vIconSz));
    }
  }

  int timeFontSize = std::max(8, (int)std::round(11.0 * scale));
  if (viewerTime) {
    viewerTime->setStyleSheet(
        QString("QLabel { color: #38A4FF; font-family: monospace, 'Segoe UI Mono', 'Consolas'; font-weight: bold; font-size: %1px; padding: 0 4px; background: transparent; border: none; }").arg(timeFontSize));
  }
  if (timelineTimecode) {
    timelineTimecode->setStyleSheet(
        QString("QLabel { color: #38A4FF; font-family: monospace, 'Segoe UI Mono', 'Consolas'; font-weight: bold; font-size: %1px; padding: 0 4px; background: transparent; border: none; }").arg(timeFontSize));
  }

  for (auto *ph : findChildren<QLabel *>("panelHeader")) {
    if (ph) ph->setFixedHeight(std::max(18, (int)std::round(30.0 * scale)));
  }

  auto *scaleMenu = findChild<QMenu *>("uiScaleMenu");
  if (scaleMenu) {
    for (auto *act : scaleMenu->actions()) {
      act->setChecked(act->data().toInt() == percent);
    }
  }

  syncDockPanels(this);
  update();
}
void Editor::applyToolCursor() {
  if (handOverride || priorityCursorApplied) return;
  preview->setCursor(activeToolCursor);
  toolCursorApplied = true;
}
void Editor::clearToolCursor() {
  if (!toolCursorApplied) return;
  if (preview) preview->unsetCursor();
  toolCursorApplied = false;
}
void Editor::applyPriorityCursor(QWidget *owner, Qt::CursorShape shape) {
  if (!owner || handOverride) return;
  // Splitters briefly use the application cursor because Qt's private dock
  // separator is not always the widget receiving the hover event.
  if (priorityCursorApplied)
    QApplication::changeOverrideCursor(QCursor(shape));
  else {
    QApplication::setOverrideCursor(QCursor(shape));
    priorityCursorApplied = true;
  }
  priorityCursorOwner = owner;
}
void Editor::clearPriorityCursor(QWidget *owner) {
  if (!priorityCursorApplied || (owner && priorityCursorOwner != owner)) return;
  QApplication::restoreOverrideCursor();
  priorityCursorApplied = false;
  priorityCursorOwner = nullptr;
}
QWidget *Editor::panelDividerAt(const QPoint &globalPosition,
                                Qt::CursorShape *cursorShape) const {
  QWidget *closest = nullptr;
  Qt::CursorShape closestShape = Qt::ArrowCursor;
  int closestDistance = std::numeric_limits<int>::max();
  auto consider = [&](QWidget *owner, Qt::CursorShape shape, int distance) {
    if (distance >= closestDistance) return;
    closest = owner;
    closestShape = shape;
    closestDistance = distance;
  };
  // Found once, and again only after a widget has come or gone: going through
  // every widget of the window for them was half a millisecond, asked up to
  // twenty times for one movement of the pointer -- more than the rest of what
  // a drag in the viewer or on a number cost.
  if (dividersFoundAt != widgetTreeGeneration) {
    dividerWidgets.clear();
    dividerDocks.clear();
    for (auto *widget : findChildren<QWidget *>()) {
      const QString type = QString::fromLatin1(widget->metaObject()->className());
      if (widget->inherits("QMainWindowSeparator") || widget->inherits("QSplitterHandle") ||
          type.contains("separator", Qt::CaseInsensitive) || type.contains("splitterhandle", Qt::CaseInsensitive))
        dividerWidgets.emplace_back(widget);
    }
    for (auto *dock : findChildren<QDockWidget *>()) dividerDocks.emplace_back(dock);
    dividersFoundAt = widgetTreeGeneration;
    ++dividerScans;
  }
  for (const auto &found : dividerWidgets) {
    QWidget *widget = found.data();
    if (!widget || !widget->isVisible() || widget->width() <= 0 || widget->height() <= 0)
      continue;
    QRect hit(widget->mapToGlobal(QPoint(0, 0)), widget->size());
    // The visible dock seam is deliberately thin. Give it a modest forgiving
    // hit area without stealing pointer interaction from either panel.
    hit.adjust(-3, -3, 3, 3);
    if (!hit.contains(globalPosition))
      continue;
    consider(widget, widget->width() <= widget->height()
                         ? Qt::SplitHCursor : Qt::SplitVCursor, 0);
  }
  // Qt does not expose every QMainWindow dock separator as a public child on
  // every Windows style. The edges of dock widgets are stable though, so they
  // are the fallback hit targets. This is the same generous five-pixel target
  // Timeline uses for its own dividers.
  const QRect windowRect(mapToGlobal(QPoint(0, 0)), QWidget::size());
  if (windowRect.contains(globalPosition)) {
    constexpr int tolerance = 5;
    for (const auto &found : dividerDocks) {
      QDockWidget *dock = found.data();
      if (!dock || !dock->isVisible() || dock->isFloating()) continue;
      const QRect rect(dock->mapToGlobal(QPoint(0, 0)), dock->size());
      if (globalPosition.y() >= rect.top() + tolerance &&
          globalPosition.y() <= rect.bottom() - tolerance) {
        const int rightDistance = std::abs(globalPosition.x() - rect.right());
        const int leftDistance = std::abs(globalPosition.x() - rect.left());
        if (rect.right() < windowRect.right() - tolerance && rightDistance <= tolerance)
          consider(dock, Qt::SplitHCursor, rightDistance);
        if (rect.left() > windowRect.left() + tolerance && leftDistance <= tolerance)
          consider(dock, Qt::SplitHCursor, leftDistance);
      }
      if (globalPosition.x() >= rect.left() + tolerance &&
          globalPosition.x() <= rect.right() - tolerance) {
        const int bottomDistance = std::abs(globalPosition.y() - rect.bottom());
        const int topDistance = std::abs(globalPosition.y() - rect.top());
        if (rect.bottom() < windowRect.bottom() - tolerance && bottomDistance <= tolerance)
          consider(dock, Qt::SplitVCursor, bottomDistance);
        if (rect.top() > windowRect.top() + tolerance && topDistance <= tolerance)
          consider(dock, Qt::SplitVCursor, topDistance);
      }
    }
  }
  if (closest && cursorShape) *cursorShape = closestShape;
  return closest;
}
std::optional<Qt::CursorShape> Editor::windowResizeCursorAt(
    const QPoint &globalPosition) const {
  if (isMaximized() || isFullScreen() || !isVisible()) return std::nullopt;
  // Include a few physical pixels outside the frame as well as inside it. On
  // Windows that is the native non-client resize target, and it remains usable
  // with thick or thin system borders alike.
  constexpr int edge = 7;
  const QRect frame = frameGeometry();
  if (!frame.adjusted(-edge, -edge, edge, edge).contains(globalPosition))
    return std::nullopt;
  const bool left = std::abs(globalPosition.x() - frame.left()) <= edge;
  const bool right = std::abs(globalPosition.x() - frame.right()) <= edge;
  const bool top = std::abs(globalPosition.y() - frame.top()) <= edge;
  const bool bottom = std::abs(globalPosition.y() - frame.bottom()) <= edge;
  // The diagonal follows the visible edge: \ is top-left/bottom-right, / is
  // top-right/bottom-left.
  if ((left && top) || (right && bottom)) return Qt::SizeBDiagCursor;
  if ((right && top) || (left && bottom)) return Qt::SizeFDiagCursor;
  if (left || right) return Qt::SizeHorCursor;
  if (top || bottom) return Qt::SizeVerCursor;
  return std::nullopt;
}
void Editor::syncPanelDividerCursor() {
  if (handOverride || QApplication::activeModalWidget() ||
      QApplication::activePopupWidget() || !isActiveWindow()) {
    clearPriorityCursor();
    dividerCheckedAt.reset();
    return;
  }
  // A button held down: the pointer belongs to what it pressed -- a layer
  // dragged in the viewer, a number scrubbed, a divider pulled -- and the
  // cursor that press found stays until the button comes up.
  if (QApplication::mouseButtons() != Qt::NoButton) return;
  const QPoint globalPosition = QCursor::pos();
  // One movement of the pointer comes through here many times over: the move,
  // again for each panel it is handed up to, a hover move for every one that
  // lights up under it, a leave and an enter. With the pointer where it was and
  // no widget come or gone since, the answer is the one already given.
  if (dividerCheckedAt == globalPosition && dividerCheckedGeneration == widgetTreeGeneration) return;
  dividerCheckedAt = globalPosition;
  dividerCheckedGeneration = widgetTreeGeneration;
  // The native frame is outside every dock. Check it first, otherwise an
  // application-wide tool cursor masks Windows' left/right and diagonal resize
  // cursors at the outer edge of the Wavy-Flo window.
  if (const auto resize = windowResizeCursorAt(globalPosition)) {
    applyPriorityCursor(this, *resize);
    return;
  }
  Qt::CursorShape shape = Qt::ArrowCursor;
  if (auto *divider = panelDividerAt(globalPosition, &shape)) {
    applyPriorityCursor(divider, shape);
  } else {
    const bool overTimeline = timeline &&
        timeline->rect().contains(timeline->mapFromGlobal(globalPosition));
    // Timeline owns its own column-resize cursor while its pointer is inside.
    if (priorityCursorOwner != timeline || !overTimeline)
    clearPriorityCursor();
  }
}
void Editor::setTool(QString tool) {
  if (preview->tool != tool && !preview->pathDraft.isEmpty()) {
    // Leaving Pen with two or more points means "leave this path open", not
    // "throw away the drawing". One point cannot form a drawable path, so its
    // provisional Shape Layer is still safely cancelled.
    if (preview->pathDraft.size() >= 2)
      preview->finishPath(!preview->maskTarget.isEmpty());
    else
      preview->cancelPathDraft();
  } else if (preview->tool != tool) {
    preview->cancelPathDraft();
  }
  preview->tool = tool;
  activeToolCursor = toolCursor(tool);
  applyToolCursor();
}
void Editor::changeLetters(const std::function<void(QJsonObject &)> &change) {
  if (syncing || !layer() || layer()->type != "text") return;
  checkpoint();
  QJsonObject o = layer()->surfaceEffects.value("Letters").toObject();
  change(o);
  layer()->surfaceEffects["Letters"] = o;
  dirty = true;
  refresh();
}
void Editor::syncLetterUi() {
  if (!letterBackgroundBox) return;
  Layer *l = layer();
  const bool text = l && l->type == "text";
  const QJsonObject o = text ? l->surfaceEffects.value("Letters").toObject() : QJsonObject();
  const bool on = o.value("background").toBool();
  QSignalBlocker b1(letterBackgroundBox), b2(letterPadding), b3(letterRound), b4(letterOpacity), b5(letterTextureScale),
      b6(letterShape), b7(letterBackgroundTexture), b8(letterTextureSource), b9(letterPer), b10(letterTextureFit);
  letterPer->setCurrentIndex(std::clamp(o.value("per").toInt(0), 0, 2));
  letterTextureFit->setCurrentIndex(o.value("textureEach").toBool() ? 0 : 1);
  letterBackgroundBox->setEnabled(text);
  letterBackgroundBox->setChecked(on);
  if (lettersFold)
    lettersFold->setText(text && (on || !o.value("letterTexture").toString().isEmpty() ||
                                  layerFindExtra(*l, "Letters/letterTexture") >= 0)
                             ? QString::fromUtf8("Background & Texture  ·  on") : QString("Background & Texture"));
  for (QWidget *w : std::initializer_list<QWidget *>{letterBackgroundSwatch, letterPadding, letterRound, letterOpacity,
                                                     letterShape, letterBackgroundTexture, letterPer, letterTextureFit})
    w->setEnabled(text && on);
  letterTextureSource->setEnabled(text);
  letterTextureScale->setEnabled(text);
  // Each number as it is at the playhead, its curve's when it is animated.
  static const QHash<QString, double> defaults{{"padding", 10}, {"round", 30}, {"opacity", 100}, {"textureScale", 100}};
  for (auto it = letterSpins.constBegin(); it != letterSpins.constEnd(); ++it) {
    const int curve = text ? layerFindExtra(*l, "Letters/" + it.key()) : -1;
    QSignalBlocker spinBlock(it.value());
    it.value()->setValue(curve >= 0 ? l->at(curve).at(scene.frame - l->start) : o.value(it.key()).toDouble(defaults.value(it.key())));
    if (QToolButton *key = letterKeys.value(it.key())) {
      QSignalBlocker keyBlock(key);
      key->setChecked(curve >= 0);
      key->setEnabled(text && (it.key() == "textureScale" || on));
    }
  }
  const double at = text ? scene.frame - l->start : 0;
  const int shapeCurve = text ? layerFindExtra(*l, "Letters/shape") : -1;
  letterShape->setCurrentIndex(std::clamp(shapeCurve >= 0 ? int(std::lround(l->at(shapeCurve).at(at))) : o.value("shape").toInt(0), 0, 2));
  QColor shownColour(o.value("color").toString("#1d1d27"));
  const int red = text ? layerFindExtra(*l, "Letters/colorR") : -1;
  if (red >= 0) {
    const int green = layerFindExtra(*l, "Letters/colorG"), blue = layerFindExtra(*l, "Letters/colorB");
    shownColour = QColor(std::clamp(int(std::lround(l->at(red).at(at))), 0, 255),
                         green >= 0 ? std::clamp(int(std::lround(l->at(green).at(at))), 0, 255) : 0,
                         blue >= 0 ? std::clamp(int(std::lround(l->at(blue).at(at))), 0, 255) : 0);
  }
  setStyleIfChanged(letterBackgroundSwatch, "/*wf:keep*/background:" + shownColour.name() + ";border:3px solid #3C3C48;");
  for (const auto &[key, curve] : std::vector<std::pair<QString, int>>{{"color", red}, {"shape", shapeCurve}})
    if (QToolButton *switchKey = letterKeys.value(key)) {
      QSignalBlocker keyBlock(switchKey);
      switchKey->setChecked(curve >= 0);
      switchKey->setEnabled(text && on);
    }
  // Every other layer with a picture of its own can be a texture. The lists
  // are filled again only when those layers change: emptied and filled on
  // every refresh, a music video's hundred layers cost each step of a drag
  // half a millisecond.
  std::vector<std::pair<QString, QString>> textures;
  if (text)
    for (const auto &other : scene.layers) {
      if (other.id == l->id || other.type == "camera" || other.type == "light" || other.type == "audio" ||
          other.type == "empty" || other.type == "effect" || other.type == "group" || layerIsStructure(other))
        continue;
      textures.emplace_back(other.name, other.id);
    }
  QStringList texturesSeen;
  for (const auto &[name, id] : textures) texturesSeen << id + QChar(31) + name;
  for (auto entry : std::vector<std::pair<QComboBox *, QString>>{
           {letterBackgroundTexture, "backgroundTexture"}, {letterTextureSource, "letterTexture"}}) {
    QComboBox *combo = entry.first;
    if (combo->count() == 0 || combo->property("wfTextureLayers").toStringList() != texturesSeen) {
      combo->clear();
      combo->addItem("None", QString());
      for (const auto &[name, id] : textures) combo->addItem(name, id);
      combo->setProperty("wfTextureLayers", texturesSeen);
    }
    // Animated: the layer its curve is at here.
    QString chosen = o.value(entry.second).toString();
    const int curve = text ? layerFindExtra(*l, "Letters/" + entry.second) : -1;
    const QJsonArray list = o.value(entry.second + "List").toArray();
    if (curve >= 0 && !list.isEmpty())
      chosen = list[std::clamp(int(std::lround(l->at(curve).at(scene.frame - l->start))), 0, int(list.size()) - 1)].toString();
    const int at = combo->findData(chosen);
    combo->setCurrentIndex(std::max(0, at));
    if (QToolButton *textureKey = letterKeys.value(entry.second)) {
      QSignalBlocker keyBlock(textureKey);
      textureKey->setChecked(curve >= 0);
      textureKey->setEnabled(text && (entry.second == "letterTexture" || on));
    }
  }
}
TextStrokeStyle *Editor::timelineTextStroke() {
  Layer *l = layer();
  if (!l || l->type != "text" || l->textStrokes.empty()) return nullptr;
  const int index = selectedTextStrokeLayer == l->id ? std::clamp(selectedTextStroke, 0, int(l->textStrokes.size()) - 1) : 0;
  return &l->textStrokes[size_t(index)];
}
void Editor::syncTextStrokeUi() {
  if (!textStrokeList || !stroke || !strokeSwatch || !textStrokeMode) return;
  Layer *textLayer = layer();
  const bool text = textLayer && textLayer->type == "text";
  if (text && textLayer->textStrokes.empty() && textLayer->strokeWidth > 0)
    textLayer->textStrokes.push_back({textLayer->strokeWidth, textLayer->strokeColor,
                                      textLayer->strokeMode});
  if (!text || selectedTextStrokeLayer != textLayer->id) {
    selectedTextStrokeLayer = text ? textLayer->id : QString();
    selectedTextStroke = 0;
  }
  const int count = text ? int(textLayer->textStrokes.size()) : 0;
  selectedTextStroke = std::clamp(selectedTextStroke, 0, std::max(0, count - 1));
  {
    QSignalBlocker block(textStrokeList);
    textStrokeList->clear();
    for (int i = 0; i < count; ++i) {
      const auto &style = textLayer->textStrokes[size_t(i)];
      QPixmap chip(14, 14);
      chip.fill(style.color);
      // Its number alone: "Stroke 1" had no room, and showed as "Str".
      textStrokeList->addItem(QIcon(chip), QString::number(i + 1));
    }
    if (count) textStrokeList->setCurrentIndex(selectedTextStroke);
  }
  const bool editable = text && count > 0;
  textStrokeList->setEnabled(editable);
  stroke->setEnabled(editable);
  strokeSwatch->setEnabled(editable);
  textStrokeMode->setEnabled(editable);
  if (textStrokeJoin) textStrokeJoin->setEnabled(editable);
  if (textStrokeOnlyBox) {
    QSignalBlocker block(textStrokeOnlyBox);
    // Only means something with a stroke to show.
    textStrokeOnlyBox->setEnabled(editable);
    textStrokeOnlyBox->setChecked(text && textLayer->textStrokeOnly);
  }
  if (addTextStroke) addTextStroke->setEnabled(text && count < 32);
  if (removeTextStroke) removeTextStroke->setEnabled(editable);
  QSignalBlocker widthBlock(stroke);
  QSignalBlocker modeBlock(textStrokeMode);
  QSignalBlocker joinBlock(textStrokeJoin);
  if (editable) {
    const auto &style = textLayer->textStrokes[size_t(selectedTextStroke)];
    stroke->setValue(style.width);
    textStrokeMode->setCurrentIndex(std::clamp(style.mode, 0, 2));
    if (textStrokeJoin) textStrokeJoin->setCurrentIndex(std::clamp(style.join, 0, 1));
    setStyleIfChanged(strokeSwatch, "/*wf:keep*/background:" + style.color.name() +
                                      ";border:1px solid #5A6072;border-radius:2px;");
  } else {
    stroke->setValue(0);
    textStrokeMode->setCurrentIndex(1);
    if (textStrokeJoin) textStrokeJoin->setCurrentIndex(0);
    setStyleIfChanged(strokeSwatch, "background:#22242B;border:1px solid #5A6072;border-radius:2px;");
  }
  syncLetterUi();
}
void Editor::changeCharacter(std::function<void(Layer &)> plain,
                             std::function<void(QTextCharFormat &)> rich) {
  if (preview->inlineEditor)
    scene.selected = preview->editingLayer;
  if (!layer())
    return;
  checkpoint();
  if (preview->inlineEditor && rich) {
    auto *edit = preview->inlineEditor.data();
    auto cursor = edit->textCursor();
    if (cursor.hasSelection()) {
      QTextCharFormat format;
      rich(format);
      cursor.mergeCharFormat(format);
      edit->setTextCursor(cursor);
      preview->update();
      return;
    }
  }
  if (!preview->inlineEditor && rich) {
    std::unique_ptr<QTextDocument> doc(textDocument(*layer()));
    double scale = std::max(.001, preview->imageRect.width() / scene.width);
    scaleDocument(doc.get(), scale);
    plain(*layer());
    QTextCursor c(doc.get());
    c.select(QTextCursor::Document);
    QTextCharFormat f;
    rich(f);
    c.mergeCharFormat(f);
    scaleDocument(doc.get(), 1 / scale);
    layer()->richHtml = doc->toHtml();
    refresh();
    return;
  }
  plain(*layer());
  if (preview->inlineEditor && rich) {
    auto *edit = preview->inlineEditor.data();
    auto current = edit->textCursor();
    auto cursor = current;
    cursor.select(QTextCursor::Document);
    QTextCharFormat format;
    rich(format);
    cursor.mergeCharFormat(format);
    edit->setTextCursor(current);
  } else
    layer()->richHtml.clear();
  refresh();
}

// A preview has to reach the text the same way a permanent change does. Once
// the text has been edited the layer carries rich HTML, the document is built
// from that instead of from Layer::font, and every span in it names its own
// family -- so assigning the layer font alone changed nothing on screen. That
// is why the preview worked on a freshly typed layer and nowhere else.
void Editor::previewFont(const QString &family) {
  auto *l = layer();
  if (!l || l->type != "text") return;
  auto *edit = preview->inlineEditor.data();
  if (!fontPreviewActive) {
    fontPreviewBackup = l->font;
    fontPreviewHtmlBackup = edit ? edit->toHtml() : l->richHtml;
    fontPreviewActive = true;
  }
  l->font = family;
  QTextCharFormat format;
  format.setFontFamilies({family});
  if (edit) {
    // Whatever a commit would have covered: the selection, or all of it.
    auto current = edit->textCursor();
    auto cursor = current;
    if (!cursor.hasSelection()) cursor.select(QTextCursor::Document);
    cursor.mergeCharFormat(format);
    edit->setTextCursor(current);
    preview->update();
    return;
  }
  if (!l->richHtml.isEmpty()) {
    std::unique_ptr<QTextDocument> doc(textDocument(*l));
    const double scale = std::max(.001, preview->imageRect.width() / scene.width);
    scaleDocument(doc.get(), scale);
    QTextCursor cursor(doc.get());
    cursor.select(QTextCursor::Document);
    cursor.mergeCharFormat(format);
    scaleDocument(doc.get(), 1 / scale);
    l->richHtml = doc->toHtml();
  }
  refresh();
}

void Editor::endFontPreview() {
  if (!fontPreviewActive) return;
  fontPreviewActive = false;
  auto *l = layer();
  if (!l) return;
  l->font = fontPreviewBackup;
  if (auto *edit = preview->inlineEditor.data()) {
    const int anchor = edit->textCursor().anchor(), position = edit->textCursor().position();
    edit->setHtml(fontPreviewHtmlBackup);
    auto cursor = edit->textCursor();
    cursor.setPosition(anchor);
    cursor.setPosition(position, QTextCursor::KeepAnchor);
    edit->setTextCursor(cursor);
    preview->update();
    return;
  }
  l->richHtml = fontPreviewHtmlBackup;
  refresh();
}

void Editor::setBlendMode(const QString &mode) {
  std::vector<int> chosen;
  if (alignSelection.size() > 1)
    chosen.assign(alignSelection.begin(), alignSelection.end());
  else if (scene.selected >= 0 && scene.selected < int(scene.layers.size()))
    chosen.push_back(scene.selected);
  // Choosing what is already set is not an edit, and must not leave an undo
  // step behind that undoes nothing.
  // A camera, light, null or Layer Struktur among them has no blend mode.
  chosen.erase(std::remove_if(chosen.begin(), chosen.end(),
                              [this](int index) {
                                return index < 0 || index >= int(scene.layers.size()) ||
                                       !layerTakesBlend(scene.layers[size_t(index)]);
                              }),
               chosen.end());
  bool changing = false;
  for (int index : chosen)
    if (scene.layers[index].blendMode != mode) changing = true;
  if (!changing) return;
  checkpoint();
  for (int index : chosen) scene.layers[index].blendMode = mode;
  dirty = true;
  refresh();
}
void Editor::editExpression(int layerIndex, const std::vector<int> &properties) {
  if (layerIndex < 0 || layerIndex >= int(scene.layers.size()) || properties.empty()) return;
  Layer &target = scene.layers[size_t(layerIndex)];
  const int first = properties.front();
  if (first < 0 || first >= layerPropertyCount(target)) return;
  const QString propertyName = properties.size() > 1 && first == 0 ? QString("Position")
                               : properties.size() > 1 && first == 2 ? QString("Scale")
                               : properties.size() > 1 && first == AnchorX ? QString("Anchor Point")
                               : timelinePropertyName(target, first);
  QDialog dialog(this);
  dialog.setWindowTitle("Expression: " + target.name + " > " + propertyName);
  dialog.resize(620, 360);
  auto *layout = new QVBoxLayout(&dialog);
  auto *hint = new QLabel(
      "Written like an After Effects expression. <b>value</b> is the property's own value, "
      "<b>time</b> is in seconds, Scale and Opacity are in percent."
      + QString(properties.size() > 1 ? " One text drives every part: an array such as "
                                        "<b>[x, y]</b> gives each part its own share." : ""));
  hint->setWordWrap(true);
  layout->addWidget(hint);
  auto *editor = new QPlainTextEdit;
  QFont mono("Consolas");
  mono.setStyleHint(QFont::Monospace);
  mono.setPointSize(11);
  editor->setFont(mono);
  editor->setTabStopDistance(QFontMetricsF(mono).horizontalAdvance(' ') * 2);
  QString existing = target.at(first).expression;
  editor->setPlainText(existing.isEmpty() ? QString("value") : existing);
  editor->selectAll();
  layout->addWidget(editor, 1);
  auto *status = new QLabel;
  status->setWordWrap(true);
  status->setTextInteractionFlags(Qt::TextSelectableByMouse);
  layout->addWidget(status);
  auto *buttons = new QHBoxLayout;
  auto *snippets = new QToolButton;
  snippets->setText("Insert");
  snippets->setPopupMode(QToolButton::InstantPopup);
  auto *snippetMenu = new QMenu(snippets);
  const std::vector<std::pair<QString, QString>> idioms{
      {"Wiggle", "wiggle(2, 30)"},
      {"Loop the keyframes", "loopOut(\"cycle\")"},
      {"Ping-pong the keyframes", "loopOut(\"pingpong\")"},
      {"Keep turning", "value + time * 90"},
      {"Bounce", "value + Math.abs(Math.sin(time * 4)) * -60"},
      {"Map time onto a range", "linear(time, 0, 2, 0, 100)"},
      {"Ease onto a range", "ease(time, 0, 2, 0, 100)"},
      {"Follow another layer", "thisComp.layer(\"Layer Name\").transform.position"},
      {"Follow, half a second late", "thisComp.layer(\"Layer Name\").transform.position.valueAtTime(time - 0.5)"},
      {"Random per layer, fixed", "seedRandom(index, true);\nrandom(0, 100)"},
      {"Stagger by layer order", "value + index * 10"}};
  for (const auto &idiom : idioms)
    snippetMenu->addAction(idiom.first, editor, [editor, text = idiom.second] { editor->insertPlainText(text); });
  snippets->setMenu(snippetMenu);
  buttons->addWidget(snippets);
  auto *enabled = new QCheckBox("Enabled");
  enabled->setChecked(existing.isEmpty() || target.at(first).expressionOn);
  buttons->addWidget(enabled);
  buttons->addStretch();
  auto *remove = new QPushButton("Remove");
  remove->setEnabled(!existing.isEmpty());
  auto *cancel = new QPushButton("Cancel");
  auto *apply = new QPushButton("Apply");
  apply->setDefault(true);
  buttons->addWidget(remove);
  buttons->addWidget(cancel);
  buttons->addWidget(apply);
  layout->addLayout(buttons);
  // What the text works out to, at the playhead, as it is typed: an error the
  // moment there is one, and otherwise the number each part would take.
  auto check = [&] {
    QString error;
    const auto program = compileExpression(editor->toPlainText(), &error);
    apply->setEnabled(program != nullptr);
    if (!program) {
      status->setStyleSheet("color:#FF6B81");
      status->setText(error);
      return;
    }
    const double local = scene.frame - target.start;
    QStringList parts;
    QString runtime;
    for (int property : properties) {
      QString why;
      double v = evaluateExpression(*program, target.at(property), local, &why);
      if (!why.isEmpty() && runtime.isEmpty()) runtime = why;
      if (isPercentProperty(target, property)) v *= 100;
      parts << QString::number(v, 'f', 2);
    }
    status->setStyleSheet(runtime.isEmpty() ? "color:#40FFD0" : "color:#FFB454");
    status->setText(runtime.isEmpty() ? "At the playhead: " + parts.join(", ")
                                      : runtime + " -- the property keeps its own value (" + parts.join(", ") + ")");
  };
  connect(editor, &QPlainTextEdit::textChanged, &dialog, check);
  check();
  bool removing = false;
  connect(remove, &QPushButton::clicked, &dialog, [&] { removing = true; dialog.accept(); });
  connect(cancel, &QPushButton::clicked, &dialog, &QDialog::reject);
  connect(apply, &QPushButton::clicked, &dialog, &QDialog::accept);
  if (dialog.exec() != QDialog::Accepted) return;
  if (layerIndex >= int(scene.layers.size())) return;
  if (removing) { removeExpressions(layerIndex, properties); return; }
  const QString text = editor->toPlainText();
  bool changing = false;
  for (int property : properties) {
    const Property &current = scene.layers[size_t(layerIndex)].at(property);
    if (current.expression != text || current.expressionOn != enabled->isChecked()) changing = true;
  }
  if (!changing) return;
  checkpoint();
  for (int property : properties) {
    Property &current = scene.layers[size_t(layerIndex)].at(property);
    current.setExpression(text);
    current.expressionOn = enabled->isChecked();
  }
  dirty = true;
  refresh();
}
void Editor::setExpressionsOn(int layerIndex, const std::vector<int> &properties, bool on) {
  if (layerIndex < 0 || layerIndex >= int(scene.layers.size())) return;
  checkpoint();
  for (int property : properties) scene.layers[size_t(layerIndex)].at(property).expressionOn = on;
  dirty = true;
  refresh();
}
void Editor::removeExpressions(int layerIndex, const std::vector<int> &properties) {
  if (layerIndex < 0 || layerIndex >= int(scene.layers.size())) return;
  checkpoint();
  for (int property : properties) {
    Property &current = scene.layers[size_t(layerIndex)].at(property);
    current.setExpression({});
    current.expressionOn = true;
  }
  dirty = true;
  refresh();
}
void Editor::addMarker() {
  const double at = std::clamp(std::round(scene.frame), 0., double(std::max(0, scene.frames - 1)));
  for (const auto &m : scene.markers)
    if (std::abs(m.frame - at) < .5 && !m.beat) {
      statusBar()->showMessage("There is a marker here already. Double-click it to name it.", 4000);
      return;
    }
  checkpoint();
  scene.markers.push_back({at, {}, false});
  sortMarkers(scene.markers);
  dirty = true;
  refresh();
  statusBar()->showMessage("Marker added. Double-click it in the ruler to name it; drag it to move it.", 5000);
}
void Editor::editMarker(int index) {
  if (index < 0 || index >= int(scene.markers.size())) return;
  QDialog dialog(this);
  dialog.setWindowTitle("Marker");
  auto *layout = new QVBoxLayout(&dialog);
  const Marker current = scene.markers[size_t(index)];
  const int fps = std::max(1, scene.fps);
  const int frameAt = int(std::lround(current.frame));
  layout->addWidget(new QLabel(QString("At %1:%2").arg(frameAt / fps).arg(frameAt % fps, 2, 10, QChar('0'))));
  auto *label = new QLineEdit(current.label);
  label->setPlaceholderText("Name, cue or lyric");
  label->selectAll();
  layout->addWidget(label);
  auto *buttons = new QHBoxLayout;
  auto *remove = new QPushButton("Delete");
  auto *cancel = new QPushButton("Cancel");
  auto *ok = new QPushButton("OK");
  ok->setDefault(true);
  buttons->addWidget(remove);
  buttons->addStretch();
  buttons->addWidget(cancel);
  buttons->addWidget(ok);
  layout->addLayout(buttons);
  bool removing = false;
  connect(remove, &QPushButton::clicked, &dialog, [&] { removing = true; dialog.accept(); });
  connect(cancel, &QPushButton::clicked, &dialog, &QDialog::reject);
  connect(ok, &QPushButton::clicked, &dialog, &QDialog::accept);
  if (dialog.exec() != QDialog::Accepted || index >= int(scene.markers.size())) return;
  if (!removing && label->text() == current.label) return;
  checkpoint();
  if (removing) scene.markers.erase(scene.markers.begin() + index);
  else scene.markers[size_t(index)].label = label->text().left(200);
  dirty = true;
  refresh();
}
void Editor::jumpToMarker(int direction) {
  double target = -1;
  for (const auto &m : scene.markers) {
    if (direction > 0 && m.frame > scene.frame + .5) { target = m.frame; break; }
    if (direction < 0 && m.frame < scene.frame - .5) target = m.frame;
  }
  if (target < 0) return;
  scene.frame = std::clamp(std::round(target), 0., double(std::max(0, scene.frames - 1)));
  syncVideo();
  refresh();
}
void Editor::removeMarkers(bool beatsOnly) {
  const auto before = scene.markers.size();
  std::vector<Marker> kept;
  for (const auto &m : scene.markers) if (beatsOnly && !m.beat) kept.push_back(m);
  if (kept.size() == before) return;
  checkpoint();
  scene.markers = kept;
  dirty = true;
  refresh();
}
void Editor::detectBeatMarkers() {
  // The layer whose beat is wanted: the selected one if it has sound,
  // otherwise the first Audio layer, otherwise the first video.
  int source = -1;
  auto hasSound = [&](int i) {
    const auto &l = scene.layers[size_t(i)];
    return (l.type == "audio" || l.type == "video") && !l.path.isEmpty();
  };
  if (scene.selected >= 0 && scene.selected < int(scene.layers.size()) && hasSound(scene.selected)) source = scene.selected;
  for (int pass = 0; pass < 2 && source < 0; ++pass)
    for (int i = 0; i < int(scene.layers.size()) && source < 0; ++i)
      if (hasSound(i) && (pass == 1 || scene.layers[size_t(i)].type == "audio")) source = i;
  if (source < 0) {
    QMessageBox::information(this, "Detect Beats", "Add an Audio layer (or a video with sound) first: the beat is found in its sound.");
    return;
  }
  const Layer audio = scene.layers[size_t(source)];
  auto peaks = audioPeaks(audio.path, timeline);
  if (!peaks && audioPeaksPending(audio.path)) {
    QProgressDialog waiting("Reading the sound of " + audio.name + "…", "Cancel", 0, 0, this);
    waiting.setWindowModality(Qt::ApplicationModal);
    waiting.setMinimumDuration(300);
    QElapsedTimer clock; clock.start();
    while (!peaks && audioPeaksPending(audio.path) && !waiting.wasCanceled() && clock.elapsed() < 120000) {
      QCoreApplication::processEvents(QEventLoop::AllEvents, 50);
      peaks = audioPeaks(audio.path);
    }
    if (waiting.wasCanceled()) return;
  }
  if (!peaks) {
    QMessageBox::warning(this, "Detect Beats", "The sound of " + audio.name + " could not be read.");
    return;
  }
  BeatAnalysis found = detectBeats(*peaks);
  const int fps = std::max(1, scene.fps);
  // Beats in composition frames, where the layer plays them.
  auto framesOf = [&](const BeatAnalysis &analysis) {
    std::vector<double> frames;
    for (double seconds : analysis.beats) {
      const double f = std::round(audio.start + (seconds - audio.sourceOffsetMs / 1000.) * fps);
      if (f >= std::max(0., audio.start) && f < audio.start + audio.duration && f < scene.frames &&
          (frames.empty() || f > frames.back()))
        frames.push_back(f);
    }
    return frames;
  };
  std::vector<double> frames = framesOf(found);
  if (found.bpm <= 0 || frames.size() < 2) {
    QMessageBox::information(this, "Detect Beats", "No steady beat was found in " + audio.name + ".");
    return;
  }
  QDialog dialog(this);
  dialog.setWindowTitle("Detect Beats");
  auto *layout = new QVBoxLayout(&dialog);
  auto *summary = new QLabel;
  layout->addWidget(summary);
  // The tempo: what fits best first, then what it could also be heard as.
  // Music does not always settle whether its beat is this or twice this.
  auto *tempo = new QComboBox;
  std::vector<double> choices;
  auto offer = [&](double bpm) {
    if (bpm < 40 || bpm > 240) return;
    for (double c : choices) if (std::abs(c - bpm) < bpm * .02) return;
    choices.push_back(bpm);
  };
  offer(found.bpm);
  for (const auto &t : found.tempos) offer(t.first);
  offer(found.bpm * 2);
  offer(found.bpm / 2);
  for (size_t i = 0; i < choices.size(); ++i)
    tempo->addItem(i == 0 ? QString("%1 BPM (fits best)").arg(choices[i], 0, 'f', 1)
                          : QString("%1 BPM").arg(choices[i], 0, 'f', 1), choices[i]);
  auto *tempoRow = new QHBoxLayout;
  tempoRow->addWidget(new QLabel("Tempo"));
  tempoRow->addWidget(tempo, 1);
  layout->addLayout(tempoRow);
  auto *every = new QComboBox;
  every->addItem("A marker on every beat", 1);
  every->addItem("On every second beat", 2);
  every->addItem("On every fourth beat (about once a bar)", 4);
  every->setCurrentIndex(frames.size() > 400 ? 2 : 0);
  layout->addWidget(every);
  auto *replace = new QCheckBox("Replace beat markers found before (markers placed by hand stay)");
  replace->setChecked(true);
  layout->addWidget(replace);
  auto *box = new QDialogButtonBox(QDialogButtonBox::Ok | QDialogButtonBox::Cancel);
  connect(box, &QDialogButtonBox::accepted, &dialog, &QDialog::accept);
  connect(box, &QDialogButtonBox::rejected, &dialog, &QDialog::reject);
  layout->addWidget(box);
  BeatAnalysis chosen = found;
  auto describe = [&] {
    summary->setText(QString("<b>%1 BPM</b> &nbsp;·&nbsp; %2 beats in %3")
                         .arg(chosen.bpm, 0, 'f', 1).arg(frames.size()).arg(audio.name.toHtmlEscaped()));
    box->button(QDialogButtonBox::Ok)->setEnabled(frames.size() >= 2);
  };
  connect(tempo, &QComboBox::currentIndexChanged, &dialog, [&](int index) {
    chosen = index == 0 ? found : detectBeats(*peaks, tempo->itemData(index).toDouble());
    frames = framesOf(chosen);
    describe();
  });
  describe();
  if (dialog.exec() != QDialog::Accepted || frames.size() < 2) return;
  const int step = every->currentData().toInt();
  checkpoint();
  if (replace->isChecked())
    scene.markers.erase(std::remove_if(scene.markers.begin(), scene.markers.end(), [](const Marker &m) { return m.beat; }),
                        scene.markers.end());
  int placed = 0;
  for (size_t i = 0; i < frames.size(); i += size_t(step)) {
    Marker m{frames[i], {}, true};
    if (placed == 0) m.label = QString("%1 BPM").arg(chosen.bpm, 0, 'f', 1);
    scene.markers.push_back(m);
    ++placed;
  }
  sortMarkers(scene.markers);
  dirty = true;
  refresh();
  statusBar()->showMessage(QString("%1 BPM: %2 beat markers placed. Hold Shift while dragging layers, keys or the "
                                   "playhead to snap to them.").arg(chosen.bpm, 0, 'f', 1).arg(placed), 10000);
}



QColor Editor::pickColorLive(QColor initial, const QString &title, bool alpha,
                             const std::function<void(const QColor &)> &apply) {
  // Typing into a text layer on the canvas keeps its colours in the editor's
  // own document, which a scene copy cannot put back. That case -- a click on
  // a swatch closes the editor, so only the keyboard reaches it -- keeps the
  // picker as it was.
  if (preview && preview->inlineEditor) {
    const QColor chosen = pickColor(this, initial, title, alpha);
    if (chosen.isValid()) apply(chosen);
    return chosen;
  }
  const Scene before = scene;
  const bool wasDirty = dirty;
  bool previewed = false;
  const QColor chosen = pickColor(this, initial, title, alpha, [&](const QColor &color) {
    // Previews are not edits: none of them may reach the undo stack.
    colorPreviewing = true;
    apply(color);
    colorPreviewing = false;
    previewed = true;
  });
  if (previewed) {
    // Back to where the dialog opened, whichever way it closed. Only the
    // playhead is kept, which playback may have moved meanwhile.
    const double frame = scene.frame;
    scene = before;
    scene.frame = frame;
    dirty = wasDirty;
  }
  if (chosen.isValid()) apply(chosen);
  else if (previewed) refresh();
  return chosen;
}

void Editor::checkpoint() {
  ++sceneRevision;
  if (colorPreviewing || suppressCheckpoints > 0) {
    dirty = true;
    return;
  }
  // One continuous gesture is one undo step. Without this a scrub copies the
  // whole scene on every pixel of pointer travel and fills the stack with
  // states no one wants to step back through.
  if (interaction::active() && checkpointGesture == interaction::id() && !undoStack.empty()) {
    dirty = true;
    return;
  }
  checkpointGesture = interaction::active() ? interaction::id() : 0;
  // QImage and JSON use implicit sharing: do not PNG-encode footage on every edit.
  undoStack.push_back(scene);
  // A hundred steps back, as long as the copies stay reasonable: each step is a
  // copy of every layer (pictures and footage are shared, not copied), so a
  // thousand-layer project keeps twenty steps and an everyday one the hundred.
  size_t layersKept = 0;
  for (const Scene &step : undoStack) layersKept += step.layers.size();
  while (undoStack.size() > 1 && (undoStack.size() > 100 || layersKept > 20000)) {
    layersKept -= undoStack.front().layers.size();
    undoStack.erase(undoStack.begin());
  }
  redoStack.clear();
  dirty = true;
  updateUndoActions();
}
void Editor::updateUndoActions() {
  if (undoAction) undoAction->setEnabled(!undoStack.empty());
  if (redoAction) redoAction->setEnabled(!redoStack.empty());
}
QByteArray Editor::preRenderContext(QSize target) const {
  QByteArray content;
  QDataStream stream(&content, QIODevice::WriteOnly);
  // Everything true of the render but not of the scene. The backend belongs
  // here: the two agree to a fraction of a level, but a cache should hold one
  // film, not a mixture of two.
  stream << target << preferGpu;
  // Light frames are another film from exact ones: switching starts over.
  if (PreRenderCache::light()) stream << QByteArray("light frames");
  // So are Draft's, drawn without motion blur.
  if (draftPreview) stream << QByteArray("draft preview");
  return content;
}
// The folder a session's cached frames go in, or empty when the disk cannot be
// used. Old sessions' folders (a crash leaves them behind) are cleared away first.
static QString cacheSessionFolder() {
  const QString base = QSettings().value("render/cacheFolder",
      QStandardPaths::writableLocation(QStandardPaths::CacheLocation) + "/prerender").toString();
  QDir root(base);
  root.mkpath(".");
  if (!root.exists()) return {};
  const QString mine = "session-" + QString::number(QCoreApplication::applicationPid());
  for (const QFileInfo &entry : root.entryInfoList({"session-*"}, QDir::Dirs | QDir::NoDotAndDotDot))
    if (entry.fileName() != mine && entry.lastModified().secsTo(QDateTime::currentDateTime()) > 12 * 3600)
      QDir(entry.absoluteFilePath()).removeRecursively();
  const QString folder = root.filePath(mine);
  QDir().mkpath(folder);
  return QDir(folder).exists() ? folder : QString();
}
// Puts the cache in memory or on disk, and shows only the sizes that place can
// hold: a share of memory in one case, of the free space on the drive in the other.
void Editor::applyCacheLocation(bool onDisk, bool chosenNow) {
  QString folder;
  if (onDisk) folder = cacheSessionFolder();
  if (onDisk && folder.isEmpty()) {
    onDisk = false;
    if (preRenderWhere) { QSignalBlocker block(preRenderWhere); preRenderWhere->setCurrentIndex(0); }
    statusBar()->showMessage("The cache folder cannot be used; keeping the cache in memory.", 6000);
  }
  preRender.clear();
  PreRenderCache::setDiskDirectory(folder);
  qint64 ceiling = maximumCacheBudget();
  if (onDisk) {
    ceiling = std::min<qint64>(64LL << 30, qint64(double(QStorageInfo(folder).bytesAvailable()) * .6));
  }
  const QVector<QPair<QString, qint64>> budgets{
      {"Cache off", 0}, {"Cache 256 MB", 256}, {"Cache 512 MB", 512}, {"Cache 1 GB", 1024},
      {"Cache 2 GB", 2048}, {"Cache 4 GB", 4096}, {"Cache 8 GB", 8192}, {"Cache 16 GB", 16384},
      {"Cache 32 GB", 32768}, {"Cache 64 GB", 65536}};
  {
    QSignalBlocker block(preRenderBudget);
    preRenderBudget->clear();
    for (const auto &choice : budgets) preRenderBudget->addItem(choice.first, QVariant(choice.second * 1024LL * 1024LL));
    // Shown but not offered above what this place can hold: a budget past it is
    // swapping (memory) or a full drive (disk), not a bigger cache.
    if (auto *model = qobject_cast<QStandardItemModel *>(preRenderBudget->model()))
      for (int row = 1; row < preRenderBudget->count(); ++row)
        if (auto *item = model->item(row)) item->setEnabled(preRenderBudget->itemData(row).toLongLong() <= ceiling);
    // Until one is chosen: memory takes a share of the machine (never below
    // 512 MB nor above 4 GB); the disk takes a good part of what is free.
    qint64 fallback = 512LL << 20;
    for (const auto &choice : budgets) {
      const qint64 bytes = choice.second * 1024LL * 1024LL;
      const qint64 want = onDisk ? std::min<qint64>(16LL << 30, ceiling / 2) : std::min<qint64>(4LL << 30, ceiling / 4);
      if (bytes > 0 && bytes <= want) fallback = std::max(fallback, bytes);
    }
    const QString key = onDisk ? "render/cacheBudgetDisk" : "render/cacheBudget";
    qint64 saved = std::min(ceiling, QSettings().value(key, fallback).toLongLong());
    // Moving the cache somewhere is asking for a cache there: a size of "off"
    // kept from before (or written by mistake) would leave pre-render quietly
    // dead on the new drive.
    if (chosenNow && saved <= 0) {
      saved = fallback;
      QSettings().setValue(key, fallback);
    }
    int choice = preRenderBudget->findData(QVariant(saved));
    if (choice < 0)
      for (int row = 0; row < preRenderBudget->count(); ++row)
        if (preRenderBudget->itemData(row).toLongLong() <= ceiling) choice = row;
    preRenderBudget->setCurrentIndex(std::max(0, choice));
  }
  // Say where "On disk" is: the drive letter in the box, the whole path and the
  // room left on it when the pointer rests there.
  if (preRenderWhere) {
    const QString base = QSettings().value("render/cacheFolder",
        QStandardPaths::writableLocation(QStandardPaths::CacheLocation) + "/prerender").toString();
    const QStorageInfo drive(QFileInfo(base).absolutePath());
    QString root = drive.isValid() ? drive.rootPath() : QString();
    while (root.endsWith(QChar('/')) || root.endsWith(QChar(0x5C))) root.chop(1);
    QSignalBlocker block(preRenderWhere);
    preRenderWhere->setItemText(1, root.isEmpty() ? QString("On disk") : "On disk (" + root + ")");
    preRenderWhere->setItemData(1, QDir::toNativeSeparators(base) + (drive.isValid()
        ? QString("\n%1 GB free on %2").arg(drive.bytesAvailable() / 1073741824., 0, 'f', 1).arg(drive.rootPath()) : QString()),
        Qt::ToolTipRole);
  }
  preRender.setBudget(preRenderBudget->currentData().toLongLong());
  showPreRenderUsage();
  if (timeline) timeline->update();
}
void Editor::clearCache(const QString &baseFolder) {
  // Whatever is filling it stops first, and is waited for, so nothing finished
  // half way through lands back in it afterwards.
  preRenderCancel->store(true);
  if (preRenderBusy) { preRenderJob.wait(); preRenderBusy = false; }
  if (preRenderPacking) { preRenderPackJob.wait(); preRenderPacking = false; }
  const int frames = preRender.count();
  qint64 freed = preRender.bytes();
  preRender.clear();
  clearRenderCaches();
  const QString base = !baseFolder.isEmpty() ? baseFolder : QSettings().value("render/cacheFolder",
      QStandardPaths::writableLocation(QStandardPaths::CacheLocation) + "/prerender").toString();
  freed += PreRenderCache::clearStaleSessionFolders(base, PreRenderCache::diskDirectory());
  showPreRenderUsage();
  if (timeline) timeline->update();
  if (preview) preview->update();
  statusBar()->showMessage(QString("Cache cleared: %1 frames, %2 MB freed").arg(frames)
                               .arg(freed / (1024. * 1024.), 0, 'f', 0), 5000);
}
void Editor::syncPreRender() {
  if (!preview) return;
  preRenderOwed = false;
  // Nothing held and nothing claimed: there is no cache to keep honest yet, and
  // taking the scene apart to prove it would be work on the typing path.
  if (preRender.count() == 0 && preRender.fingerprint().isEmpty()) return;
  const QSize target = preview->cachedTarget;
  if (target.isEmpty()) {
    preRender.clear();
    return;
  }
  // Frames the edit cannot have touched are kept. That is the whole point of
  // the per-layer signature: changing one layer in a two-minute sequence costs
  // the seconds that layer is on screen, not the two minutes.
  preRender.reconcile(preRenderSignature(scene, preRenderContext(target)));
}
void Editor::accountDiskWrites() {
  constexpr double gigabyte = 1024. * 1024. * 1024.;
  QSettings settings;
  const QString today = QDate::currentDate().toString(Qt::ISODate);
  if (settings.value("render/diskWrittenDay").toString() != today) {
    settings.setValue("render/diskWrittenDay", today);
    settings.setValue("render/diskWrittenToday", 0);
    diskLimitReported = false;
  }
  const qint64 written = PreRenderCache::diskBytesWritten();
  qint64 day = settings.value("render/diskWrittenToday", 0).toLongLong();
  qint64 total = settings.value("render/diskWrittenTotal", 0).toLongLong();
  if (const qint64 fresh = written - diskWrittenSeen; fresh > 0) {
    diskWrittenSeen = written;
    day += fresh;
    total += fresh;
    settings.setValue("render/diskWrittenToday", day);
    settings.setValue("render/diskWrittenTotal", total);
  }
  const int limit = settings.value("render/diskWriteLimitGB", 5).toInt();
  const qint64 allowed = qint64(limit) * qint64(gigabyte);
  PreRenderCache::setDiskWriteRoom(limit > 0 ? allowed - day : std::numeric_limits<qint64>::max());
  const bool reached = limit > 0 && day >= allowed - 64LL * 1024 * 1024;
  if (reached && !diskLimitReported) {
    diskLimitReported = true;
    statusBar()->showMessage(QString("Today's disk write limit (%1 GB) is reached: the cache keeps frames in memory "
                                     "until tomorrow.").arg(limit), 8000);
  }
  if (!diskWrites) return;
  diskWrites->setText(QString("Disk %1 GB%2").arg(day / gigabyte, 0, 'f', day < 10 * gigabyte ? 1 : 0)
                          .arg(limit > 0 ? QString(" / %1").arg(limit) : QString()));
  diskWrites->setToolTip(
      QString("What the cache has written to the drive.\n"
              "Today: %1 GB%2\nThis session: %3 GB\nSince counting began: %4 GB\n\n"
              "Only frames that do not fit in memory are written, never while playing. "
              "Past the daily limit the cache keeps frames in memory instead; they look the same. "
              "Click to change the limit. \"In memory\" writes nothing at all.")
          .arg(day / gigabyte, 0, 'f', 2)
          .arg(limit > 0 ? QString(" of %1 GB allowed%2").arg(limit).arg(reached ? " (reached)" : "") : QString(", no limit"))
          .arg(written / gigabyte, 0, 'f', 2)
          .arg(total / gigabyte, 0, 'f', 1));
}
void Editor::showPreRenderUsage() {
  if (!preRenderUsage) return;
  const int held = preRender.count();
  const double seconds = scene.fps > 0 ? held / double(scene.fps) : 0;
  const QString activity=preRenderBusy ? (timer.isActive() ? " · caching ahead" : " · caching")
                                            : QString();
  preRenderUsage->setText(held > 0 ? QString("· %1 s · %2 MB%3")
                                         .arg(seconds, 0, 'f', 1)
                                         .arg(preRender.bytes() / (1024. * 1024.), 0, 'f', 0)
                                         .arg(activity)
                                   : activity.trimmed());
  const QSize target = preview ? preview->cachedTarget : QSize();
  QString reach;
  if (preRender.budget() > 0 && scene.fps > 0) {
    // Measured where it can be, estimated where it cannot: how many seconds of
    // timeline this budget actually holds is the only number that answers the
    // question someone editing a long sequence is really asking.
    const double perFrame = held > 0 ? preRender.bytes() / double(held)
                                     : double(std::max(1, target.width())) *
                                           std::max(1, target.height()) * 4;
    reach = QString(" At %1x%2 this holds about %3 s of timeline.")
                .arg(std::max(1, target.width()))
                .arg(std::max(1, target.height()))
                .arg(preRender.budget() / perFrame / scene.fps, 0, 'f', 0);
  }
  QString machine;
  if (const qint64 physical = physicalMemoryBytes())
    machine = QString(" Held in RAM, not on disk: this machine has %1 GB, and sizes it "
                      "could not hold are greyed out.")
                  .arg(physical / 1073741824., 0, 'f', 1);
  const QString note =
      "Frames render ahead on low-priority background workers while preview plays. "
      "The current frame keeps most CPU cores; the green strip under the ruler is "
      "what is ready. Editing "
      "one layer only drops the frames that layer is on screen for, so the rest of "
      "the timeline stays ready. It caches half a minute ahead of the playhead; "
      "on disk, the first part stays in memory and only the rest is written." +
      reach + machine;
  preRenderUsage->setToolTip(note);
  if (preRenderBudget) preRenderBudget->setToolTip(note);
}
// Renders a run of frames for the pre-render cache, several at a time.
//
// One frame drawn by every core at once scales badly: a frame of a busy
// composition is a few tens of milliseconds, too short to divide well, and each
// band repeats what the others do. The same cores drawing different frames each
// on its own never wait on one another, so the cache fills several times faster.
//
// Each lane takes the next frame as soon as it is done with its last, and hands
// each frame over the moment it is drawn: a run used to go in lots, every lane
// waiting for the slowest, and nothing reached the cache until the whole run was
// over -- a quarter of a second later, by which time the playhead had passed
// the frames it was for. Frames are kept as drawn (PreRenderCache::keep): packing
// them here cost twice the drawing. Frames that render alike are drawn once and
// share the picture, as before.
static void renderPreRenderBatch(const Scene &snapshot, const QVector<int> &queue, QSize target,
                                 const std::shared_ptr<std::atomic<bool>> &cancelled, int lanes, int sliceMs,
                                 PreRenderRun &run) {
  // Which frames look exactly like the last one drawn before them, and so take
  // its picture: the index of that one, or -1 for a frame to draw.
  QVector<int> like(queue.size(), -1);
  for (int i = 0, drawn = -1; i < queue.size(); ++i) {
    if (drawn >= 0 && sameCompositionPixels(snapshot, queue[drawn], queue[i])) like[i] = drawn;
    else drawn = i;
  }
  QElapsedTimer clock;
  clock.start();
  std::atomic<int> next{0};
  auto lane = [&] {
    // Its own passes run inline: the parallelism is between frames.
    RenderSchedulingScope alone(-1, 1);
    while (!cancelled->load() && clock.elapsed() < sliceMs) {
      const int i = next.fetch_add(1);
      if (i >= queue.size()) break;
      if (like[i] >= 0) continue;
      const int frame = queue[i];
      // The playhead is there already, or will be before this could be drawn:
      // the preview draws that one itself.
      if (run.playing && run.total > 0 &&
          ((frame - run.playhead.load()) % run.total + run.total) % run.total < run.lead.load())
        continue;
      QElapsedTimer drawing;
      drawing.start();
      Scene scene = snapshot;
      scene.frame = frame;
      QImage image = renderCPU(scene, frame, true, target);
      if (scene.exposure != 0) gradeCPU(image, float(scene.exposure));
      const auto picture = PreRenderCache::keep(image);
      run.renderNs += drawing.nsecsElapsed();
      ++run.rendered;
      QVector<QPair<int, PreRenderCache::Prepared>> made{{frame, picture}};
      for (int j = i + 1; j < queue.size() && like[j] == i; ++j) made.push_back({queue[j], picture});
      QMutexLocker lock(&run.guard);
      run.ready += made;
    }
  };
  std::vector<std::future<void>> others;
  for (int n = 1; n < lanes; ++n) others.push_back(std::async(std::launch::async, lane));
  lane();
  for (auto &other : others) other.get();
}
// Frames the running pre-render has drawn since last asked, into the cache.
void Editor::collectPreRender() {
  if (!preRenderRun) return;
  QVector<QPair<int, PreRenderCache::Prepared>> done;
  {
    QMutexLocker lock(&preRenderRun->guard);
    done.swap(preRenderRun->ready);
  }
  if (const int n = preRenderRun->rendered.load(); n > 0)
    preRenderFrameMs = preRenderRun->renderNs.load() / 1e6 / n;
  if (done.isEmpty()) return;
  // Nothing changed while the run went on, which is the usual case and worth
  // one comparison rather than one per frame.
  const bool settled = preRender.signature().global == preRenderStartedWith.global &&
                       preRender.signature().layers == preRenderStartedWith.layers;
  bool stored = false;
  int previous = -1;
  qintptr previousPicture = 0;
  for (const auto &made : done) {
    // Asked per frame, so an edit somewhere else on the timeline while the run
    // went on does not throw away the frames it did not touch.
    if (!settled && preRender.signature().frameKey(made.first) != preRenderStartedWith.frameKey(made.first))
      continue;
    // The run hands back the same picture for frames that render alike, so they
    // cost one copy between them rather than one each.
    if (previous >= 0 && qintptr(PreRenderCache::keyOf(made.second)) == previousPicture &&
        preRender.shareFrom(previous, made.first)) {
      previous = made.first;
      stored = true;
      continue;
    }
    preRender.storePrepared(made.first, made.second);
    if (!preRender.has(made.first)) continue;
    previous = made.first;
    previousPicture = qintptr(PreRenderCache::keyOf(made.second));
    stored = true;
  }
  if (stored && timeline) timeline->update();
}
void Editor::setPlayRange(bool start) {
  if (QApplication::focusWidget() && (qobject_cast<QLineEdit *>(QApplication::focusWidget()) ||
                                      qobject_cast<QTextEdit *>(QApplication::focusWidget()) ||
                                      qobject_cast<QAbstractSpinBox *>(QApplication::focusWidget())))
    return;
  checkpoint();
  const int at = std::clamp(int(std::floor(scene.frame)), 0, std::max(0, scene.frames - 1));
  const int first = playFirst(scene), last = playLast(scene);
  // The other end stays where it was, unless it would now be on the wrong side:
  // then it goes back to the Main's own start or end.
  if (start) {
    scene.playStart = at;
    scene.playEnd = at < last ? last : scene.frames - 1;
  } else {
    scene.playEnd = at;
    scene.playStart = at > first ? first : 0;
  }
  if (!hasPlayRange(scene)) scene.playStart = scene.playEnd = -1;
  dirty = true;
  statusBar()->showMessage(hasPlayRange(scene) ? QString("Play Range: frames %1 to %2").arg(scene.playStart).arg(scene.playEnd)
                                               : QString("Play Range cleared"), 3000);
  refresh(false, true);
}
void Editor::stepPreRender() {
  // A one-core machine cannot render foreground and background concurrently;
  // there the preview gets the core and idle caching resumes after playback.
  const bool playing=timer.isActive();
  if (!preview || interaction::active() ||
      (playing && std::max(1,QThread::idealThreadCount())<2)) {
    preRenderCancel->store(true);
    return;
  }
  const int total = std::max(1, scene.frames);
  const int playhead = ((int(scene.frame) % total) + total) % total;
  // Frames drawn so far go in whether or not the run is over.
  collectPreRender();
  if (preRenderBusy) {
    if (preRenderJob.wait_for(std::chrono::seconds(0)) != std::future_status::ready) {
      if (preRenderRun) preRenderRun->playhead.store(playhead);
      return;
    }
    preRenderBusy = false;
    try { preRenderJob.get(); } catch (...) {}
    collectPreRender();
  }
  if (preRenderPacking) {
    if (preRenderPackJob.wait_for(std::chrono::seconds(0)) != std::future_status::ready) return;
    preRenderPacking = false;
    try {
      for (const auto &[kept, packed] : preRenderPackJob.get()) preRender.repack(kept, packed);
    } catch (...) {
    }
  }
  const QSize target = preview->cachedTarget;
  if (target.isEmpty() || scene.frames <= 0 || preRender.budget() <= 0) return;
  // Global output plugins are not included by this CPU prerender entry point.
  // Layer plugins are included. Do not mark an unprocessed frame green.
  if(effects->currentIndex()>0)return;
  preRender.reconcile(preRenderSignature(scene, preRenderContext(target)));
  // During playback the frames nearest the playhead are the preview's to draw:
  // one started there would be finished after the playhead had gone by. The
  // lead is how far the playhead moves while a lane draws a frame, and a tick
  // of the playback timer to hand it over.
  const int lead = playing ? 1 + int(std::ceil((preRenderFrameMs + 1000. / std::max(1, scene.fps)) *
                                               std::max(1, scene.fps) / 1000.))
                           : 0;
  // The frames nobody has yet, from there forward, because that is where
  // someone is about to look. Frames the cache will refuse to keep -- video,
  // which the player decodes as the playhead moves -- are skipped, or every
  // idle moment would go into rendering the same one again.
  QVector<int> queue;
  const int firstStep = playing ? (preRenderFrameMs > 0 ? lead : 1) : 0;
  // Only so far ahead: half a minute from wherever the playhead is, playing or
  // not. Filling the whole timeline up to the budget kept every core and the
  // drive busy for minutes after each edit -- gigabytes written per song, per
  // session -- for frames nobody was about to look at. Playing moves the
  // playhead, and the half minute moves with it; what was cached behind it
  // stays until the budget needs the room.
  const int ahead = std::min(scene.frames, std::max(1, scene.fps) * 30);
  // On disk, playing writes nothing: the frames ahead are kept in the memory
  // part, which makes its room from the ones the playhead has gone past.
  const bool onDisk = !PreRenderCache::diskDirectory().isEmpty();
  PreRenderCache::setSpillAllowed(!playing);
  if (onDisk && playing) {
    const qint64 frameBytes = qint64(target.width()) * target.height() * 4;
    const qint64 inMemory = preRender.bytes() - preRender.diskBytes();
    const qint64 over = inMemory + frameBytes * 8 - (PreRenderCache::memoryFirstBytes() + preRender.hotBudget());
    if (over > 0) preRender.dropBehind(playhead, total, ahead + firstStep, over);
  }
  // Playing over a Play Range, the frames ahead are the range's, coming round
  // again after its last: the ones after it are never reached.
  const int loopFirst = playing ? playFirst(scene) : 0;
  const int loopLength = playing ? playLast(scene) - loopFirst + 1 : scene.frames;
  auto aheadBy = [&](int step) {
    if (playhead < loopFirst || playhead >= loopFirst + loopLength) return (playhead + step) % scene.frames;
    return loopFirst + (playhead - loopFirst + step) % loopLength;
  };
  for (int step = firstStep; step < std::min(ahead, loopLength) + firstStep && queue.size() < 240; ++step) {
    const int frame = aheadBy(step);
    if (!preRender.has(frame) && preRender.signature().stableAt(frame) && !queue.contains(frame)) queue.push_back(frame);
  }
  const int cores = std::max(1, QThread::idealThreadCount());
  // While the next few frames are already cached the screen needs almost no
  // CPU, so the cache may take half of it; when it is behind, the frame being
  // drawn live gets two thirds.
  int ready = 0;
  while (ready < loopLength && ready < 2 * std::max(1, scene.fps) && preRender.has(aheadBy(1 + ready)))
    ++ready;
  const bool aheadOfPlayhead = playing && ready >= 8;
  const int lanes = !playing ? std::max(1, std::min(cores - 2, 8))
                             : std::max(1, aheadOfPlayhead ? cores / 2 : cores / 3);
  // Kept frames are packed when that is what the time is best spent on: when
  // there is nothing left to draw, when the playhead has two seconds ready in
  // front of it, or when memory for kept frames (or the whole budget) is about
  // to run out -- packing gives back six sevenths of a busy frame, so it comes
  // before giving up frames.
  const qint64 rawFrame = qint64(target.width()) * target.height() * 4;
  const bool keptFull = preRender.hotBytes() + rawFrame * lanes > preRender.hotBudget();
  const bool budgetFull = preRender.bytes() + rawFrame * lanes > preRender.budget();
  const bool spare = queue.isEmpty() || (playing && ready >= 2 * std::max(1, scene.fps));
  if (preRender.hotBytes() > 0 && (keptFull || budgetFull || spare)) {
    auto kept = preRender.hotPictures(playhead, scene.frames, lanes * 2);
    auto cancelled = preRenderCancel = std::make_shared<std::atomic<bool>>(false);
    preRenderPacking = true;
    preRenderPackJob = std::async(std::launch::async, [this, kept = std::move(kept), cancelled, lanes] {
      std::vector<std::pair<PreRenderCache::Prepared, PreRenderCache::Prepared>> packed(kept.size());
      std::atomic<int> next{0};
      auto lane = [&] {
        for (int i = next.fetch_add(1); i < int(kept.size()) && !cancelled->load(); i = next.fetch_add(1))
          packed[size_t(i)] = {kept[size_t(i)], PreRenderCache::prepare(kept[size_t(i)].image)};
      };
      std::vector<std::future<void>> others;
      for (int n = 1; n < lanes; ++n) others.push_back(std::async(std::launch::async, lane));
      lane();
      for (auto &other : others) other.get();
      QMetaObject::invokeMethod(this, [this] { stepPreRender(); }, Qt::QueuedConnection);
      // A lane stopped part way leaves empty pairs; repack() ignores those.
      return packed;
    });
    return;
  }
  if (queue.isEmpty()) return;
  // How many more will fit. Without this the cache would render a frame, evict
  // an older one to make room for it, and find that older one missing on the
  // next pass: a core burned forever on a composition larger than the budget.
  qint64 room = std::min(preRender.budget() - preRender.bytes(), preRender.hotBudget() - preRender.hotBytes()) /
                std::max<qint64>(1, rawFrame);
  if (room <= 0) {
    // Full, and nothing left to pack. Worth going on only to trade a frame far
    // ahead of the playhead for one nearer to it, which is what the budget
    // should be spent on once the playhead has moved somewhere the cache does
    // not reach.
    const int furthest = preRender.furthestAhead(playhead, scene.frames);
    const int reach = furthest < 0 ? -1 : (furthest - playhead + scene.frames) % scene.frames;
    if (reach <= (queue.first() - playhead + scene.frames) % scene.frames) return;
    preRender.invalidate(furthest, furthest);
    room = 1;
  }
  if (queue.size() > int(room)) queue.resize(int(room));
  Scene snapshot = scene;
  preRenderStartedWith = preRender.signature();
  preRenderBusy = true;
  preRenderCancel=std::make_shared<std::atomic<bool>>(false);
  const auto cancelled=preRenderCancel;
  auto run = std::make_shared<PreRenderRun>();
  run->playhead = playhead;
  run->lead = firstStep;
  run->total = scene.frames;
  run->playing = playing;
  preRenderRun = run;
  // Pre-rendered frames are always CPU-rendered.
  preRenderJob = std::async(std::launch::async, [this, snapshot = std::move(snapshot), queue, target, cancelled, lanes, run] {
    renderPreRenderBatch(snapshot, queue, target, cancelled, lanes, 250, *run);
    // Straight on to the next run, rather than idle until the timer comes round.
    QMetaObject::invokeMethod(this, [this] { stepPreRender(); }, Qt::QueuedConnection);
  });
}
bool Editor::layerInActiveComposition(int index) const {
  if (index < 0 || index >= int(scene.layers.size())) return false;
  const auto &candidate = scene.layers[index];
  return activeGroupId.isEmpty() ? candidate.groupId.isEmpty()
                                 : candidate.groupId == activeGroupId;
}

Scene Editor::activeCompositionScene() const {
  if (activeGroupId.isEmpty()) return scene;
  // Descendants as well as direct members; the direct members become the top
  // level of this viewer (render_queue.cpp, where a render of it does the same).
  Scene isolated = compositionScene(scene, activeGroupId);
  if (scene.selected >= 0 && scene.selected < int(scene.layers.size())) {
    const QString selectedId = scene.layers[scene.selected].id;
    for (int index = 0; index < int(isolated.layers.size()); ++index)
      if (isolated.layers[index].id == selectedId) isolated.selected = index;
  }
  return isolated;
}

void Editor::pressOfxButton(const WavyEffectV1 *api, const QString &button) {
  const OfxEffectEntry *ofx = api ? ofxPlugins.value(api, nullptr) : nullptr;
  if (!ofx || !layer()) return;
  const QString name = QString::fromUtf8(api->name);
  const QString held = layer()->id;
  const double time = scene.frame - layer()->start;
  QVector<float> values = layerPluginValues(*layer(), api, time);
  QMap<QString, QString> texts = layerPluginTexts(*layer(), api);
  const QVector<float> valuesBefore = values;
  const QMap<QString, QString> textsBefore = texts;
  QString error;
  bool pressed = false;
  {
    QApplication::setOverrideCursor(Qt::WaitCursor);
    // The picture going into the effect, for a plug-in that measures it.
    QString note;
    QImage picture;
    const Scene shown = activeCompositionScene();
    int index = -1;
    for (int i = 0; i < int(shown.layers.size()); ++i)
      if (shown.layers[size_t(i)].id == held) index = i;
    try {
      picture = packEffectInput(shown, index, name, scene.frame, note);
    } catch (const std::exception &) {
      picture = QImage();
    }
    QApplication::restoreOverrideCursor();
    // Told on a thread of its own: a button may open a window of the
    // plug-in's (an "Edit Look") and keep it open as long as someone works in
    // it. Most answer at once; for one that does not, this window waits,
    // drawn, and says why.
    const int fps = std::max(1, scene.fps);
    // How far it says it has gone, and whether it has been asked to stop.
    struct Progress {
      std::mutex guard;
      QString label;
      double fraction = -1;
      std::atomic<bool> stop{false};
    };
    auto progress = std::make_shared<Progress>();
    auto heard = [progress](const QString &label, double fraction) {
      std::lock_guard<std::mutex> lock(progress->guard);
      progress->label = label;
      progress->fraction = fraction;
      return !progress->stop.load();
    };
    // Its window belongs to the plug-in host, in the background, and opened
    // behind Wavy-Flo: this click is Wavy-Flo's, so the right to come in
    // front is handed on.
    ofxLetPluginWindowsForward();
    auto answer = std::async(std::launch::async, [&] {
      return ofxPressButton(*ofx, held + "|" + name, button, time, fps, values, texts, picture, &error, heard);
    });
    if (answer.wait_for(std::chrono::milliseconds(300)) != std::future_status::ready) {
      struct Waiting : QDialog {
        using QDialog::QDialog;
        void reject() override {} // it ends when the plug-in answers, not before
      };
      Waiting wait(this);
      // Shown without taking the front from the plug-in's own window.
      wait.setAttribute(Qt::WA_ShowWithoutActivating);
      wait.setWindowTitle(name);
      wait.setWindowFlag(Qt::WindowCloseButtonHint, false);
      wait.setWindowFlag(Qt::WindowContextHelpButtonHint, false);
      auto *lines = new QVBoxLayout(&wait);
      auto *what = new QLabel(name + " is answering its button, perhaps in a window of its own.\n"
                                     "Finish there to come back to Wavy-Flo.");
      lines->addWidget(what);
      // Shown once the plug-in says how far it has gone; it can then be
      // stopped, which it hears the next time it says so.
      auto *bar = new QProgressBar;
      bar->setRange(0, 1000);
      bar->setVisible(false);
      lines->addWidget(bar);
      auto *stop = new QPushButton("Cancel");
      stop->setVisible(false);
      lines->addWidget(stop, 0, Qt::AlignRight);
      connect(stop, &QPushButton::clicked, &wait, [progress, stop] {
        progress->stop = true;
        stop->setEnabled(false);
        stop->setText("Stopping...");
      });
      wait.setMinimumWidth(360);
      QTimer poll;
      // The plug-in's window, put in front of Wavy-Flo once it shows.
      bool raised = false;
      int ticks = 0;
      connect(&poll, &QTimer::timeout, &wait, [&] {
        if (answer.wait_for(std::chrono::milliseconds(0)) == std::future_status::ready) {
          wait.done(0);
          return;
        }
        if (!raised && ++ticks % 4 == 0) raised = ofxRaisePluginWindow();
        std::lock_guard<std::mutex> lock(progress->guard);
        if (progress->fraction >= 0) {
          bar->setVisible(true);
          stop->setVisible(true);
          bar->setValue(int(progress->fraction * 1000));
          if (!progress->label.isEmpty()) what->setText(progress->label);
        }
      });
      poll.start(50);
      wait.exec();
    }
    pressed = answer.get();
  }
  if (!pressed) {
    statusBar()->showMessage(error, 6000);
    return;
  }
  // Kept on the layer it was pressed for, if that is still the one shown.
  if (!layer() || layer()->id != held) return;
  const auto *v4 = parameterPlugins.value(api, nullptr);
  if (!v4) return;
  checkpoint();
  Layer &l = *layer();
  auto settings = l.surfaceEffects[name].toObject();
  int at = 0;
  for (int index = 0; index < v4->parameterCount; ++index) {
    const auto &parameter = v4->parameters[index];
    const QString id = QString::fromUtf8(parameter.id);
    const int floats = wavyParameterFloats(&parameter);
    if (at + floats > values.size()) break;
    bool differs = false;
    for (int k = 0; k < floats; ++k) differs = differs || values[at + k] != valuesBefore[at + k];
    if (differs) {
      if (parameter.kind == WAVY_COLOR) {
        settings[id] = QColor::fromRgbF(values[at], values[at + 1], values[at + 2], values[at + 3]).name(QColor::HexArgb);
      } else {
        const double value = std::clamp(double(values[at]), double(parameter.minimum), double(parameter.maximum));
        // An animated control takes a key at the playhead, as moving it does.
        const int curve = layerFindExtra(l, pluginCurveId(name, id));
        if (curve >= 0) l.at(curve).set(time, value);
        else settings[id] = value;
      }
    }
    at += floats;
  }
  for (auto it = texts.cbegin(); it != texts.cend(); ++it)
    if (textsBefore.value(it.key()) != it.value()) settings[it.key()] = it.value();
  l.surfaceEffects[name] = settings;
  dirty = true;
  refresh();
}
void Editor::pressEffectButton(const PackEffect *pack, const QString &button) {
  if (!pack || !layer()) return;
  const QString held = layer()->id;
  const Layer owner = *layer();
  const double frame = scene.frame - owner.start;
  // The picture going into the effect, drawn from the Main (or the group) the
  // layer is seen in: an Effect Layer works on what is beneath it there.
  QString note;
  QImage picture;
  {
    QApplication::setOverrideCursor(Qt::WaitCursor);
    const Scene shown = activeCompositionScene();
    int index = -1;
    for (int i = 0; i < int(shown.layers.size()); ++i)
      if (shown.layers[size_t(i)].id == held) index = i;
    try {
      picture = packEffectInput(shown, index, pack->id, scene.frame, note);
    } catch (const std::exception &error) {
      picture = QImage();
      note = "no frame (" + QString::fromUtf8(error.what()) + ")";
    }
    QApplication::restoreOverrideCursor();
  }
  // The effect runs on a thread of its own and may keep a window open for as
  // long as someone works in it. This window stays drawn meanwhile, and
  // waits: nothing can be changed underneath what it is going to hand back.
  struct Waiting : QDialog {
    using QDialog::QDialog;
    void reject() override {} // it ends when the effect is done, not before
  };
  Waiting wait(this);
  wait.setWindowTitle(pack->name);
  wait.setWindowFlag(Qt::WindowCloseButtonHint, false);
  wait.setWindowFlag(Qt::WindowContextHelpButtonHint, false);
  auto *lines = new QVBoxLayout(&wait);
  auto *text = new QLabel(pack->name + " is working in its own window.\n"
                          "Apply or Cancel there to come back to Wavy-Flo.");
  lines->addWidget(text);
  wait.setMinimumWidth(360);
  QHash<QString, QByteArray> changed;
  QString message;
  int result = -1;
  std::thread worker([&] {
    try {
      result = pressPackButton(*pack, button, owner, picture, note, frame, changed, message);
    } catch (...) {
      result = -1;
      message = pack->name + ": the button failed.";
    }
    QMetaObject::invokeMethod(&wait, [&wait] { wait.done(0); }, Qt::QueuedConnection);
  });
  wait.exec();
  worker.join();
  if (result != 0) {
    if (!message.isEmpty()) QMessageBox::warning(this, pack->name, message);
    return;
  }
  if (!message.isEmpty()) statusBar()->showMessage(message, 8000);
  if (changed.isEmpty()) return;
  Layer *target = nullptr;
  for (auto &l : scene.layers)
    if (l.id == held) target = &l;
  if (!target) return;
  checkpoint();
  for (auto it = changed.cbegin(); it != changed.cend(); ++it)
    if (pack->dataIds.contains(it.key())) setPackEffectData(*target, *pack, it.key(), it.value());
  dirty = true;
  refresh();
  if (message.isEmpty()) statusBar()->showMessage(pack->name + ": applied.", 4000);
}

void Editor::openGroup(int index) {
  if (index < 0 || index >= int(scene.layers.size()) ||
      scene.layers[index].type != "group")
    return;
  activeGroupId = scene.layers[index].id;
  scene.selected = -1;
  for (int child = 0; child < int(scene.layers.size()); ++child)
    if (scene.layers[child].groupId == activeGroupId) {
      scene.selected = child;
      break;
    }
  alignSelection.clear();
  if (scene.selected >= 0) alignSelection.insert(scene.selected);
  timeline->graph = false;
  timeline->filter = timeline->filterLayer = -1;
  timeline->selected.clear();
  if (project) {
    QTreeWidgetItemIterator it(project);
    while (*it) {
      if ((*it)->data(0, ProjectIdRole).toString() == activeGroupId) {
        project->setCurrentItem(*it);
        break;
      }
      ++it;
    }
  }
  refresh(false);
  statusBar()->showMessage("Opened the group in its own timeline.", 2500);
}

void Editor::leaveGroup(bool allTheWay) {
  if (activeGroupId.isEmpty()) return;
  QString selectedGroup = activeGroupId;
  QString parentGroup;
  for (const auto &candidate : scene.layers)
    if (candidate.id == selectedGroup) {
      parentGroup = candidate.groupId;
      break;
    }
  if (allTheWay)
    while (!parentGroup.isEmpty()) {
      selectedGroup = parentGroup;
      parentGroup.clear();
      for (const auto &candidate : scene.layers)
        if (candidate.id == selectedGroup) {
          parentGroup = candidate.groupId;
          break;
        }
    }
  activeGroupId = allTheWay ? QString() : parentGroup;
  scene.selected = -1;
  for (int index = 0; index < int(scene.layers.size()); ++index)
    if (scene.layers[index].id == selectedGroup) {
      scene.selected = index;
      break;
    }
  alignSelection.clear();
  if (scene.selected >= 0) alignSelection.insert(scene.selected);
  timeline->graph = false;
  timeline->filter = timeline->filterLayer = -1;
  timeline->selected.clear();
  if (project) {
    const QString targetId = activeGroupId.isEmpty() ? QString("main_composition") : activeGroupId;
    QTreeWidgetItemIterator it(project);
    while (*it) {
      if ((*it)->data(0, ProjectIdRole).toString() == targetId) {
        project->setCurrentItem(*it);
        break;
      }
      ++it;
    }
  }
  refresh(false);
}

// These places and, for each group or Layer Struktur among them, the places of
// everything inside it (groups and structures in them too), in the order they
// stand in the project.
static std::vector<int> indicesWithContents(const Scene &s, const std::vector<int> &indices) {
  std::set<int> chosen;
  QSet<QString> inside, held; // groups, structures
  auto take = [&](const Layer &l) {
    // Without an id nothing is inside it; an empty one would take in the Main.
    if (l.id.isEmpty()) return false;
    if (l.type == "group" && !inside.contains(l.id)) {
      inside.insert(l.id);
      return true;
    }
    if (layerIsStructure(l) && !held.contains(l.id)) {
      held.insert(l.id);
      return true;
    }
    return false;
  };
  for (int index : indices)
    if (index >= 0 && index < int(s.layers.size())) {
      chosen.insert(index);
      take(s.layers[size_t(index)]);
    }
  for (bool more = !inside.isEmpty() || !held.isEmpty(); more;) {
    more = false;
    for (const Layer &l : s.layers)
      if (inside.contains(l.groupId) || held.contains(l.structureId)) more |= take(l);
  }
  std::vector<int> found;
  for (int index = 0; index < int(s.layers.size()); ++index)
    if (chosen.count(index) || inside.contains(s.layers[size_t(index)].groupId) ||
        held.contains(s.layers[size_t(index)].structureId))
      found.push_back(index);
  return found;
}

// Of these places, the ones not inside a Layer Struktur that is among them
// too: what a command on a structure works on once, its contents coming along.
static std::vector<int> outermostLayers(const Scene &s, const std::vector<int> &indices) {
  QSet<QString> structures;
  for (int index : indices)
    if (index >= 0 && index < int(s.layers.size()) && layerIsStructure(s.layers[size_t(index)]))
      structures.insert(s.layers[size_t(index)].id);
  std::vector<int> outer;
  for (int index : indices) {
    if (index < 0 || index >= int(s.layers.size())) continue;
    bool covered = false;
    QString up = s.layers[size_t(index)].structureId;
    for (int guard = 0; !up.isEmpty() && guard <= int(s.layers.size()) && !covered; ++guard) {
      covered = structures.contains(up);
      const auto owner = std::find_if(s.layers.begin(), s.layers.end(), [&](const Layer &l) { return l.id == up; });
      up = owner == s.layers.end() ? QString() : owner->structureId;
    }
    if (!covered) outer.push_back(index);
  }
  std::sort(outer.begin(), outer.end());
  outer.erase(std::unique(outer.begin(), outer.end()), outer.end());
  return outer;
}

// The layer at `source`, and everything a structure there holds, taken out
// and put back before the layer at `before` (at the end of the list when
// `before` is its size), listed under `structure` (none when empty). Nothing
// happens when that is where it already is, or when it would go inside itself.
static bool moveBlockInScene(Scene &s, int source, int before, const QString &structure) {
  const int count = int(s.layers.size());
  if (source < 0 || source >= count || before < 0 || before > count) return false;
  std::vector<int> block{source};
  for (int inside : structureContents(s, source)) block.push_back(inside);
  std::sort(block.begin(), block.end());
  const std::set<int> moving(block.begin(), block.end());
  const QString movingId = s.layers[size_t(source)].id;
  if (moving.count(before)) return false;
  if (!structure.isEmpty()) {
    // Not into itself, nor into anything inside it.
    for (int index : block)
      if (s.layers[size_t(index)].id == structure) return false;
  }
  const QString beforeId = before < count ? s.layers[size_t(before)].id : QString();
  std::vector<Layer> taken, rest;
  for (int index = 0; index < count; ++index)
    (moving.count(index) ? taken : rest).push_back(s.layers[size_t(index)]);
  int at = int(rest.size());
  if (!beforeId.isEmpty())
    for (int index = 0; index < int(rest.size()); ++index)
      if (rest[size_t(index)].id == beforeId) {
        at = index;
        break;
      }
  for (Layer &l : taken)
    if (l.id == movingId) l.structureId = structure;
  rest.insert(rest.begin() + at, taken.begin(), taken.end());
  bool changed = false;
  for (int index = 0; index < count && !changed; ++index)
    changed = rest[size_t(index)].id != s.layers[size_t(index)].id ||
              rest[size_t(index)].structureId != s.layers[size_t(index)].structureId;
  if (!changed) return false;
  QString selectedId;
  if (s.selected >= 0 && s.selected < count) selectedId = s.layers[size_t(s.selected)].id;
  s.layers = std::move(rest);
  for (int index = 0; index < count; ++index)
    if (s.layers[size_t(index)].id == selectedId) s.selected = index;
  tidyStructures(s);
  return true;
}

// The layers at these places with what is inside the groups among them. A
// group's copy is drawn from its contents: copied without them it shows nothing.
static std::vector<Layer> layersWithContents(const Scene &s, const std::vector<int> &indices) {
  std::vector<Layer> found;
  for (int index : indicesWithContents(s, indices)) found.push_back(s.layers[size_t(index)]);
  return found;
}

// Copies made new: each gets an id of its own, and whatever pointed at a layer
// copied with it -- its group, its structure, its parent, its matte -- points at that layer's
// copy. Returns each old id with its new one.
static QHash<QString, QString> renewLayerIds(std::vector<Layer> &layers) {
  QHash<QString, QString> fresh;
  for (const Layer &l : layers) fresh.insert(l.id, QUuid::createUuid().toString(QUuid::WithoutBraces));
  for (Layer &l : layers) {
    l.id = fresh.value(l.id);
    if (fresh.contains(l.groupId)) l.groupId = fresh.value(l.groupId);
    if (fresh.contains(l.structureId)) l.structureId = fresh.value(l.structureId);
    if (fresh.contains(l.parentId)) l.parentId = fresh.value(l.parentId);
    if (fresh.contains(l.trackMatteId)) l.trackMatteId = fresh.value(l.trackMatteId);
  }
  return fresh;
}

// A field taking typed text or a number keeps its own keys.
static bool typingIntoField() {
  auto *focused = QApplication::focusWidget();
  return qobject_cast<QLineEdit *>(focused) || qobject_cast<QTextEdit *>(focused) ||
         qobject_cast<QPlainTextEdit *>(focused) || qobject_cast<QAbstractSpinBox *>(focused);
}

void Editor::deselectLayers() {
  // Escape also cancels a one-point Pen draft and removes its provisional
  // empty Shape Layer. A drawable path is committed before selection clears,
  // so using deselect never throws away finished work.
  if (preview && !preview->pathDraft.isEmpty()) {
    if (preview->pathDraft.size() >= 2)
      preview->finishPath(!preview->maskTarget.isEmpty());
    else
      preview->cancelPathDraft();
  }
  scene.selected = -1;
  alignSelection.clear();
  if (timeline) {
    timeline->selected.clear();
    timeline->selectedItems.clear();
    timeline->selectionAnchorRow = -1;
    timeline->filter = timeline->filterLayer = -1;
  }
  refresh(false);
  statusBar()->showMessage("Layer selection cleared. The next Pen path creates a new Shape Layer.",
                           3000);
}

void Editor::dropOpening(Layer &l, double elapsed) {
  l.start += elapsed;
  l.duration -= elapsed;
  for (int p = 0; p < layerPropertyCount(l); ++p)
    if (auto *curve = layerProperty(l, p))
      for (auto &key : curve->keys) key.frame -= elapsed;
  if (l.sourceDurationMs > 0)
    l.sourceOffsetMs += elapsed * 1000. / std::max(1, scene.fps);
}

std::vector<int> Editor::timingTargets() const {
  // A Layer Struktur has no time, keys or effects of its own: what is done to
  // the selection reaches the layers inside it, which are selected with it.
  std::vector<int> usable = layerTargets();
  usable.erase(std::remove_if(usable.begin(), usable.end(),
                              [this](int index) { return layerIsStructure(scene.layers[size_t(index)]); }),
               usable.end());
  return usable;
}

std::vector<int> Editor::layerTargets() const {
  std::vector<int> chosen;
  if (alignSelection.size() > 1)
    chosen.assign(alignSelection.begin(), alignSelection.end());
  else if (scene.selected >= 0 && scene.selected < int(scene.layers.size()))
    chosen.push_back(scene.selected);
  // Never a locked layer, however it came to be among them: nothing is done to it.
  std::vector<int> usable;
  for (int index : chosen)
    if (index >= 0 && index < int(scene.layers.size()) && layerInActiveComposition(index) &&
        !scene.layers[size_t(index)].locked)
      usable.push_back(index);
  return usable;
}

void Editor::deleteSelectedLayers() {
  if (timeline && !timeline->selected.empty()) {
    timeline->expandPairedSelection();
    checkpoint();
    for (int l = 0; l < int(scene.layers.size()); l++)
      for (int p = 0; p < layerPropertyCount(scene.layers[l]); p++) {
        auto &keys = scene.layers[l].at(p).keys;
        for (int k = int(keys.size()) - 1; k >= 0; k--)
          if (timeline->selected.count({l, k, p}))
            keys.erase(keys.begin() + k);
      }
    timeline->selected.clear();
    refresh();
    return;
  }
  if (timeline && timeline->hasNonLayerSelection()) {
    timeline->deleteSelectedItems();
    return;
  }
  deleteLayers(layerTargets());
}

void Editor::deleteLayers(std::vector<int> targets, const QString &done) {
  targets.erase(std::remove_if(targets.begin(), targets.end(),
                               [this](int idx) { return idx < 0 || idx >= int(scene.layers.size()); }),
                targets.end());
  std::sort(targets.begin(), targets.end());
  targets.erase(std::unique(targets.begin(), targets.end()), targets.end());
  if (targets.empty()) return;
  checkpoint();
  // A group goes with everything inside it, groups in it too. Left behind,
  // they would point at a group that is not there: saved, never drawn.
  const std::vector<int> going = indicesWithContents(scene, targets);
  std::set<QString> deletedIds;
  for (int idx : going)
    if (!scene.layers[size_t(idx)].id.isEmpty()) deletedIds.insert(scene.layers[size_t(idx)].id);
  // The group open in the Timeline is left first, out to the nearest Main that stays.
  for (size_t up = 0; up <= scene.layers.size() && !activeGroupId.isEmpty() && deletedIds.count(activeGroupId); ++up)
    leaveGroup();
  for (int index = 0; index < int(scene.layers.size()); ++index) {
    if (deletedIds.count(scene.layers[size_t(index)].id)) continue;
    if (deletedIds.count(scene.layers[size_t(index)].parentId))
      setLayerParent(scene, index, -1);
    if (deletedIds.count(scene.layers[size_t(index)].trackMatteId)) {
      scene.layers[size_t(index)].trackMatteId.clear();
      scene.layers[size_t(index)].trackMatteInverted = false;
    }
  }
  for (auto idx = going.rbegin(); idx != going.rend(); ++idx)
    scene.layers.erase(scene.layers.begin() + *idx);
  // Picks are held by layer number, which the layers below have just changed.
  if (timeline) {
    timeline->selected.clear();
    timeline->selectedItems.clear();
  }
  alignSelection.clear();
  scene.selected = -1;
  for (int index = 0; index < int(scene.layers.size()); ++index) {
    if (layerInActiveComposition(index)) {
      scene.selected = index;
      alignSelection.insert(index);
      break;
    }
  }
  releaseOfxInstances();
  refresh(true);
  const size_t inside = going.size() - targets.size();
  statusBar()->showMessage(QString("%1 %2 layer%3%4.")
                               .arg(done)
                               .arg(targets.size())
                               .arg(targets.size() == 1 ? "" : "s")
                               .arg(inside ? QString(" and the %1 inside").arg(inside) : QString()),
                           3000);
}

void Editor::duplicateSelectedLayers() {
  if (timeline && timeline->hasNonLayerSelection()) {
    bool hasMask = false;
    for (const auto &item : timeline->selectedItems) {
      if (item.section == 13) { hasMask = true; break; }
    }
    if (hasMask) {
      checkpoint();
      std::set<Timeline::TimelineItem> newSelected;
      for (const auto &item : timeline->selectedItems) {
        if (item.section == 13 && item.layer >= 0 && item.layer < int(scene.layers.size())) {
          auto &layer = scene.layers[item.layer];
          int m = item.uid.toInt();
          if (m >= 0 && m < int(layer.masks.size())) {
            auto dup = layer.masks[m].toObject();
            dup["name"] = dup.value("name").toString() + " copy";
            layer.masks.append(dup);
            newSelected.insert({item.layer, 13, -1, QString::number(layer.masks.size() - 1)});
          }
        }
      }
      if (!newSelected.empty()) {
        timeline->selectedItems = newSelected;
      }
      dirty = true;
      timeline->rebuild();
      refresh(true);
      statusBar()->showMessage("Duplicated selected mask(s).", 3000);
      return;
    }
  }
  const auto targets = outermostLayers(scene, layerTargets());
  if (targets.empty()) return;
  checkpoint();
  std::vector<int> sortedTargets = targets;
  std::sort(sortedTargets.rbegin(), sortedTargets.rend());
  std::set<QString> newCopyIds;
  for (int origIdx : sortedTargets) {
    if (origIdx < 0 || origIdx >= int(scene.layers.size())) continue;
    // A group comes with what is inside it. The copies go in above the
    // original; whatever of a group's contents stands among them belongs to
    // the group, not to this Main, so the copy is still right above it here.
    std::vector<Layer> copies = layersWithContents(scene, {origIdx});
    const QString copyId = renewLayerIds(copies).value(scene.layers[size_t(origIdx)].id);
    for (Layer &copy : copies)
      if (copy.id == copyId) copy.name += " copy";
    newCopyIds.insert(copyId);
    scene.layers.insert(scene.layers.begin() + origIdx, copies.begin(), copies.end());
  }
  alignSelection.clear();
  if (timeline) timeline->selected.clear();
  for (int i = 0; i < int(scene.layers.size()); ++i) {
    if (newCopyIds.count(scene.layers[size_t(i)].id))
      alignSelection.insert(i);
  }
  if (!alignSelection.empty())
    scene.selected = *alignSelection.begin();
  // The selection is the copies, chosen for the list as it now is: refresh()
  // otherwise takes the changed layer count for a stale selection and keeps
  // only one of them, so a delete straight after removed one copy of several.
  alignLayerCount = int(scene.layers.size());
  refresh(true);
  statusBar()->showMessage(QString("Duplicated %1 layer%2.")
                               .arg(sortedTargets.size())
                               .arg(sortedTargets.size() == 1 ? "" : "s"),
                           3000);
}

void Editor::selectAllLayers() {
  alignSelection.clear();
  for (int i = 0; i < int(scene.layers.size()); ++i) {
    if (layerInActiveComposition(i) && !scene.layers[size_t(i)].locked)
      alignSelection.insert(i);
  }
  if (!alignSelection.empty())
    scene.selected = *alignSelection.begin();
  refresh(false);
  statusBar()->showMessage(QString("Selected all %1 layers.").arg(alignSelection.size()), 3000);
}

void Editor::moveLayersToPlayhead(bool inPoint) {
  const auto targets = timingTargets();
  if (targets.empty()) return;
  checkpoint();
  for (int index : targets) {
    if (index >= 0 && index < int(scene.layers.size())) {
      if (inPoint)
        scene.layers[size_t(index)].start = scene.frame;
      else
        scene.layers[size_t(index)].start = scene.frame - scene.layers[size_t(index)].duration;
    }
  }
  refresh(true);
  statusBar()->showMessage(inPoint ? "Moved in-point to playhead." : "Moved out-point to playhead.", 3000);
}

