      drag({2, -20}, Qt::ShiftModifier);
      drag({80, -20}, Qt::ShiftModifier);
      check(property.keys[0].frame == 30 && property.keys[0].value == 120 && t->shiftDragAxis == 2,
            "Shift graph drag stays vertical without time snapping");
