      check(glowGroup && glowGroup->isExpanded() && !glowGroup->isHidden(), "effect search opens matching group");
      search->clear();
      check(tree->topLevelItem(0)->isExpanded() && !tree->topLevelItem(1)->isExpanded(), "clearing effect search restores group state");
